CREATE TABLE [PpcTxnUpd](
	[IdKey] [int] IDENTITY(1,1) NOT NULL,
	[PpuOdlIdKey] [int] NOT NULL,
	[PpuPrcs]	varchar(12) NOT NULL,
	[PpuEvnt]	varchar(12) NOT NULL,
	[PpuLoc] [varchar](12) NOT NULL,
	[PpuQtyCmpl]  float NOT NULL,
	EntityRowNum [int] NOT NULL,
 CONSTRAINT [PK_PpcTxnUpd] PRIMARY KEY CLUSTERED 
(
	[IdKey] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY]

