IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE upper(TABLE_NAME) = upper('OrdLn')) 
		DROP TABLE dbo.OrdLn

GOGO
CREATE TABLE [dbo].[OrdLn]
(
	IdKey int identity(1,1) NOT NULL,
	[OdlCoCd] varchar(2) NOT NULL,
    [OdlTc] [varchar](3) NOT NULL,
    [OdlYy] [varchar](2) NOT NULL,
    [OdlChr] [varchar](3) NOT NULL,
    [OdlNo] [INT] NOT NULL,
    [OdlSr] [INT] NOT NULL,
    [OdlSrNo] [INT] NOT NULL,
	[OdlOdIdNo] INT NOT NULL,
    [OdlPrcsSEQ] [varchar](12) NOT NULL,
	[OdlPrdSEQ] [varchar](12) NOT NULL,
    [OdlCell] [varchar](5) NOT NULL,
    [OdlStrtDt] [datetime] NOT NULL,
    [OdlEndDt] [datetime] NOT NULL,
    [OdlDtCyc] [int] NOT NULL,
    [OdlMkPln] [varchar](2) NOT NULL,
	[OdlLastMakePlanMessage] varchar(100) NOT NULL,
	[OdlPrdQty] int NOT NULL,

	[EntityRowNum] [int] NULL
)

Alter Table OrdLn
Add 
CONSTRAINT [PK_OrdLn] PRIMARY KEY CLUSTERED 
(
	[IdKey] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]

CREATE UNIQUE NONCLUSTERED INDEX [UK_OrdLn] ON OrdLn
(
	[OdlCoCd] ASC,
	[OdlTc] ASC,
	[OdlYy] ASC,
	[OdlChr] ASC,
	[OdlNo] ASC,
	[OdlSr] ASC,
	[OdlSrNo] ASC
)


