/* New field in Head	*/
IF NOT EXISTS(SELECT *
          FROM   INFORMATION_SCHEMA.COLUMNS
          WHERE  upper(TABLE_NAME) = 'HEAD'
                 AND upper(COLUMN_NAME) = upper('HDefRepBagLoc')) 
BEGIN
Alter table Head add HDefRepBagLoc varchar(8) not null default ''
END
GOGO
/* Prdline – System Param	*/
Update Param set PValue ='Y'  where PTyp ='PTyp' and  PMCd ='PrdLine' and PSCd=''

/* WIWLONG, WIWSEQ	*/
UpdATE TcStr set TsMaxLen =192   where TsTbl ='vparam' and TsTyp='WIWlong' and TsIdName ='vPDesc225'

UpdATE TcStr set TsMaxLen =104   where TsTbl ='vparam' and TsTyp='WIWseq' and TsIdName ='vPDesc225'

UpdATE TcStr set TsMaxLen =8    where TsTbl ='vparam' and TsTyp='WIWlong'  and TsIdName ='vPMCd'

UpdATE TcStr set TsMaxLen =8    where TsTbl ='vparam' and TsTyp='WIWseq'  and TsIdName ='vPMCd'

UpdATE TcStr set TsLbl ='Location Sequence'    where TsTbl ='vparam' and TsTyp='WIWseq'  and TsIdName ='vPDesc225'

UpdATE TcStr set TsLbl ='Location Sequence'    where TsTbl ='vparam' and TsTyp='WIWlong'  and TsIdName ='vPDesc225'

/* Location for Work	*/
UPDATE TcStr SET TsMaxLen =8  where TsTbl ='VParam' and TsTyp ='WORK' and TsIdName ='vPValue'

UPDATE TcStr SET TsLbl ='Production Loc'  where TsTbl ='VParam' and TsTyp ='WORK' and TsIdName ='vPValue'

/* Size for PrdSeq in OrdDsg	*/
Alter table OrdDsg alter column ODPrdSeq varchar(80) not null

/* Loc Table change	*/
Alter table Loc alter column LocCd varchar(8) not null
Alter table Loc alter column LocPrntCd varchar(8) not null
Alter table Loc alter column LocLoss varchar(8) not null
Alter table Loc alter column LocBrk varchar(8) not null
Alter table Loc alter column LocMsg varchar(8) not null
