	select @row=count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'BCHR' and PMCd= BChr)
	if @row>0 
	Begin
		select @errmsg= 'Bag Character Not Defined'
		goto ErrHndlr
	end

	/******  BNo  >  0  ******/
	/* Current Partition */
	select @row=count('x') from inserted where BNo<= 0 
