	if @row>0 
	Begin
		select @errmsg= 'Sales Order Tc Not Defined'
		goto ErrHndlr
	end

	/******  Bag Order Sr should exist in OrdDsg  ******/
	/* Current Partition */
	select @row=count('x') from inserted where 
