		select @errmsg= 'Bag Opening Qty Should Be Greater Than Or Equal To Zero'
		goto ErrHndlr
	end

	/******  BOpnQty  >=  0 ******/
	/* Current Partition */	
	select @row=count('x') from inserted where BRepYN='Y' and BRepQty>BQty 
	if @row>0 
	Begin
		select @errmsg= 'Repair Qty must be less than or equal To BQty'
		goto ErrHndlr
	end
