		/* (Bef 27/11/06) select @errmsg= 'Opening Part Qty Should Be Greater Than Or Equal To Zero For Component Bag' */
		goto ErrHndlr
	end
	/* *** jay 2.13(CT) *** */ 

	/******  BOpnDt  <>  Blank  ( '01/01/1980', '01/01/1900'  are also considered blank)  ******/
	select @row=count('x') from inserted where BOpnDt in ('01/01/1980', '01/01/1900')  
	if @row>0 
	Begin
		select @errmsg= 'Bag Opening Date Should Be Entered'
		goto ErrHndlr
	end

	/*** urmi 2.06 BRecvDt */
	/******  BRecvDt  <>  Blank  ( '01/01/1980', '01/01/1900'  are also considered blank)  ******/
