	select @row=count('x') from inserted where 
			BLstYyKey<> BLstYy+ (case when BLstKey= 0 then '' else SubString(str(BLstKey), 4, 7) end) 
	if @row>0 
	Begin
		select @errmsg= 'Last YyKey Not Defined'
		goto ErrHndlr
	end

	/******  BPrdStg  =  PMCd ( 'PRDSTG' )  ******/	/* Current Partition */	select @row= count('x') from inserted where 
			BPrdStg<>'' and not exists (select 'x' from Param where PTyp= 'PRDSTG' and PMCd= BPrdStg)
	if @row> 0 
	Begin
		select @errmsg= 'Invalid Production Stage'
		goto ErrHndlr
	end

	/*** BFgSubLoc  =  Blank Or vPMCd('FGSUBLOC') ***/
	/* Current Partition */
	Select @Row= Count('x') From Inserted Ins Where BFgSubLoc<> '' and 
			Not Exists (Select vPMCd From vParam Where vPCoCd= BCoCd and 
				    vPTyp= 'FGSUBLOC' And vPMCd = BFgSubLoc)
  	If @Row> 0
	begin
		Select @ErrMsg= 'Fg Sub Location Not Defined'
		GoTo ErrHndlr
	end

	/******  BOdCtCd  =  Blank or CmCd from CustMst (CmCtg= 'T')  ******/
	/* Current Partition */
	select @row= count('x') from inserted where BOdCtCd<> '' and 
		not exists (select 'x' from CustMst where CmCtg= 'T' and CmCd= BOdCtCd)
	if @row> 0 
	begin		select @errmsg= 'Contractor Code Not Defined'
		goto ErrHndlr
	end

	/*** 2.11 (Jen) ***/	
	/******  Do Not Allow Flute Bags (where Bag Chr is for a particular Rm Ctg,SubCtg) and the Ord Design does not have this Ctg,SubCtg ******/
	/* Current Partition */
	select @row= count('x') from inserted Join Param on PTyp= 'BCHR' and PMCd = BChr 
						where (PValue1<> '' Or PValue2<> '') and 
							not exists(Select 'x' From OrdRm where OrPrtKey=BPrtKey and OrOdIdNo=BOdIdNo and OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy 
								and OrChr= BOdChr and OrNo= BOdNo and OrSr= BOdSr and OrRmCtg= PValue1 
								and (PValue2= '' Or ','+ PValue2+ ',' like '%,'+ OrRmSCtg + ',%' ) ) 

										/* and PValue2= (case when PValue2= '' then '' else OrRmSCtg end) */
	if @row> 0 
	begin		select @errmsg= 'Order Design Of Bag Does Not Contain Rm Ctg/ SubCtg Of Flute Bag Character'
		goto ErrHndlr
	end
	/*** 2.11 (Jen) ***/	


/*      This check should be put if you do not want the user to enter any wt in a zero Qty bag (but it conflicts with the Txnd trigger) 
	******  If BGrWt > 0  then  BQty > 0  or  BPtQty > 0  ******
	select @row=count('x') from inserted where Round(BGrWt, 3)<> 0 and BQty= 0 and BPtQty <= 0 
	if @row>0 
	Begin
		select @errmsg= 'Cannot Enter Weight In Bag When Bag Qty and Part Qty Equal To Zero'
		goto ErrHndlr
	end
*/

/* **** Zubin 211 **** */ 
	/****** The total Bag Qty for an Order Serial should not exceed the PrdQty for that Order Serial 
			(for primary bags only) ******/ 
/*	select @row= count('x') from inserted ins join OrdDsg on OdCoCd= ins.BCoCd and OdTc= ins.BOdTc and 
		OdYy= ins.BOdYy and OdChr= ins.BOdChr and OdNo= ins.BOdNo and OdSr= ins.BOdSr 
	where (Select sum(Bg.BQty) from Bag Bg where Bg.BCoCd= OdCoCd and Bg.BOdTc= OdTc and 
		Bg.BOdYy= OdYy and Bg.BOdChr= OdChr and Bg.BOdNo= OdNo and Bg.BOdSr= OdSr)> OdPrdQty 
*/
	/* Current Partition */
	select @row= count('x') from inserted ins 
		Join OrdDsg on OdPRtKey=ins.BPrtKey and OdIdNo=ins.BOdIdNo and OdCoCd= ins.BCoCd and OdTc= ins.BOdTc 
			and OdYy= ins.BOdYy and OdChr= ins.BOdChr and OdNo= ins.BOdNo and OdSr= ins.BOdSr 
		Join Param On PTyp= 'BCHR' and PMCd= ins.BChr and PSCd= '' and PValue = 'P' 
		where 
			(Select convert(decimal(16,1), sum(Bg.BQty)) from Bag Bg 
				where Bg.BCoCd= OdCoCd and Bg.BPrtKey=OdPRtKey and Bg.BOdIdNo=OdIdNo and 
				Bg.BOdTc= OdTc and Bg.BOdYy= OdYy and Bg.BOdChr= OdChr and Bg.BOdNo= OdNo and 
				Bg.BOdSr= OdSr and 
			(Select PValue from Param where PTyp= 'BCHR' and PMCd= BChr and PSCd= '')= 'P') > 
				convert(decimal(16,1), OdPrdQty, 1) 
	if @row> 0 
	Begin
		select @errmsg= 'Primary Bag Qty Cannot Not Be Greater Than Prd Qty' 
		goto ErrHndlr 
	end 

	/****** The total Bag Qty for an Order Serial-BChr should not exceed the PrdQty for that Order Serial 
			(for flute bags only) ******/ 
	/* Current Partition */
	select @row= count('x') from inserted ins 
		Join OrdDsg on OdPRtKey=ins.BPrtKey and OdIdNo=ins.BOdIdNo and OdCoCd= ins.BCoCd and OdTc= ins.BOdTc and OdYy= ins.BOdYy 
			and OdChr= ins.BOdChr and OdNo= ins.BOdNo and OdSr= ins.BOdSr 
		Join Param On PTyp= 'BCHR' and PMCd= ins.BChr and PSCd= '' and PValue = 'F' 
		where 
			(Select convert(decimal(16,1), sum(Bg.BQty)) from Bag Bg where Bg.BPrtKey=OdPrtKey 
				and Bg.BOdIdNo=OdIdNo and Bg.BCoCd= OdCoCd and 
				Bg.BOdTc= OdTc and Bg.BOdYy= OdYy and Bg.BOdChr= OdChr and Bg.BOdNo= OdNo and 
				Bg.BOdSr= OdSr and Bg.BChr= ins.BChr and 
			(Select PValue from Param where PTyp= 'BCHR' and PMCd= BChr and PSCd= '')= 'F') > 
				convert(decimal(16,1), OdPrdQty, 1) 
	if @row> 0 
	Begin
		select @errmsg= 'Flute Bag Qty For This Bag Character Cannot Not Be Greater Than Prd Qty'
		goto ErrHndlr
	end

	/* *** jay 2.13(CT) *** */ 
	/****** The total Bag Qty for an Order Serial-BChr should not exceed the PrdQty for that Order Serial 
			(for flute bags only) ******/ 
	/* Current Partition */
	select @row= count('x') from inserted ins 
		Join OrdDsg on OdPrtKey=ins.BPrtKey and OdIdNo=ins.BOdIdNo and OdCoCd= ins.BCoCd and OdTc= ins.BOdTc 
			and OdYy= ins.BOdYy and OdChr= ins.BOdChr and OdNo= ins.BOdNo and OdSr= ins.BOdSr 
		Join Param On PTyp= 'BCHR' and PMCd= ins.BChr and PSCd= '' and PValue = 'C' 
		where 
			(Select convert(decimal(16,1), sum(Bg.BQty)) from Bag Bg 
				where Bg.BPrtKey=OdPrtKey and Bg.BOdIdNo=OdIdNo and Bg.BCoCd= OdCoCd and 
				Bg.BOdTc= OdTc and Bg.BOdYy= OdYy and Bg.BOdChr= OdChr and Bg.BOdNo= OdNo and 
				Bg.BOdSr= OdSr and Bg.BChr= ins.BChr and 
			(Select PValue from Param where PTyp= 'BCHR' and PMCd= BChr and PSCd= '')= 'C') > 
				convert(decimal(16,1), OdPrdQty, 1) 
	if @row> 0 
	Begin
		select @errmsg= 'Component Bag Qty For This Bag Character Cannot Not Be Greater Than Prd Qty'
		goto ErrHndlr
	end

	/********************Geeta***Crm****2.12*******************/
		/****** Cannot Generate Bags For OmChr='WEB' and OmAckYN='N' ******/
		/* Current Partition */
	 	select @row=count('x') from inserted where (Select OmAckYN from OrdMst where 
		  	OmPrtKey=BPrtKey and OmIdNo=BOmIdNo and OmCoCd= BCoCd and OmTc= BOdTc and OmYy= BOdYy 
			and OmChr= BOdChr and OmNo= BOdNo )= 'N'
		if @row>0 
		Begin
			select @errmsg= 'Order is not Acknowledged. Bags Cannot Be Generated.'
			goto ErrHndlr
		end     


/* **** Zubin 211 **** */ 
return

ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end


GOGO

ALTER TRIGGER [dbo].[DsgMst_INUPDL] ON [dbo].[DsgMst] 
       FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS  
BEGIN  
	/* Trigger Version 3.10.0 */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @wSelfCoCd varchar(3)
	DECLARE @ctSelfCmCd varchar(8)	
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)

	set @wSelfCoCd= 'ZZZ'
	set @ctSelfCmCd= 'ZSELF'
	set @wCurrPrtn = 'C'

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgMst' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
	case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='A' And @ReplAgt <> 1
	begin
		Select @row=count('x') From Inserted Where DmPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	if @mode='C' And @ReplAgt <> 1
	begin
		Select @row=count('x') From Inserted Where DmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end

	if @mode='D' And @ReplAgt <> 1
	begin
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition */
		select @row= count('x') from deleted del where del.DmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	end

	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
			If   exists (select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
			exists (select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
				Begin 
					select @errmsg= 'Cannot Insert /Update /Delete ' 
					goto ErrHndlr 
				end 
		End 				
		If @Mode='D' 
		Begin 
			/* *** jay 2.13(CT) *** (DsgCT) */  
			/*****Geeta***2.10**DsgPrt*DsgTgt*/
			/****** Delete all records of the child tables DsgRm, DsgLab, DsgAna ******/
			/* 3.02 Deletions On Current Db As all tables for the current design will be on current partition only  */
			Delete DsgRm From deleted, DsgRm where DmPrtKey=DrPrtKey and DmIdNo=DrDmIdNo and DmTcTyp= DrTcTyp 
				and DmCd= DrCd and DmSz= DrSz 
			Delete DsgLab From deleted, DsgLab where DmPrtKey=DlPrtKey and DmIdNo=DlDmIdNo and DmTcTyp= DlTcTyp 
				and DmCd= DlCd and DmSz= DlSz 
			Delete DsgAna From deleted join DsgAna on DmPrtKey=DaPrtKey and DmIdNo=DaDmIdNo and DmTcTyp= DaTcTyp 
				and DmCd= DaCd and DmSz= DaSz 
			Delete DsgTgt From deleted, DsgTgt where DmTcTyp= DtTcTyp 
				and DmCd= DtCd and DmSz= DtSz 
			Delete DsgModAvl From deleted, DsgModAvl where DmTcTyp= DmaTcTyp 
				and DmCd= DmaCd and DmSz= DmaSz 		
			Delete DsgCT From deleted, DsgCT where DmPrtKey=DctPrtKey and DmIdNo=DctDmIdNo and DmTcTyp= DctTcTyp 
				and DmCd= DctDmCd and DmSz= DctDmSz 
			/*** Jay 3.4(FG) ***/
			Delete DsgPrm From deleted, DsgPrm where DpDmCd= DmCd and DmSz=''
			/*** Jay 3.4(FG) ***/
		End
	End  

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		/* ****** Sachin 3.02 - Current Partition */
  		select @Row=Count('x') from deleted del where DmPrtKey=@wCurrPrtn and
    		not exists (Select 'x' from inserted ins where ins.DmIdNo=del.DmIdNo and ins.DmTcTyp= del.DmTcTyp and ins.DmCd= del.DmCd 
							and ins.DmSz= del.DmSz)
  		If @Row > 0
	  	begin 
			Select @ErrMsg = 'Cannot Change DsgMst Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	begin
		/******  DmTcTyp  =  PMCd ('DMTCTYP')  ******/
		/* ****** Sachin 3.02 - Partition Key Not required */
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
				PTyp= 'DMTCTYP' and PMCd= DmTcTyp)
		if @row> 0 
		Begin
			select @errmsg= 'Design Type Not Defined'
			goto ErrHndlr
		end

		/* ****** Sachin 3.02 - Partition Key Not required */
		/******  DmCd  =  Not Blank ******/
		select @row=count('x') from inserted where DmCd= '' 
		if @row>0 
		Begin
			select @errmsg='Design Code Cannot Be Blank'
			goto ErrHndlr
		end

/*
		******  DmHistory, DmFaults  =  Not Blank ******
		select @row=count('x') from inserted where DmHistory= '' or DmFaults= '' 
		if @row>0 
		Begin
			select @errmsg= 'Design History/ Faults Cannot Be Blank'
			goto ErrHndlr
		end
*/

/*		Manoj 2.10.0		*/
		/******  If DmTcTyp  = 'DM' or 'SM'   then  DmSz = Blank or PMCd ('DMSZ')  ******/
/*		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') 
			and DmSz<> '' and not exists (select 'x' from Param where 
			PTyp= 'DMSZ' and PMCd= DmSz)
		if @row> 0 
		Begin
			select @errmsg= 'Design Size Not Defined'
			goto ErrHndlr
		end
*/
		/* ****** Sachin 3.02 - Partition Key Not required */
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') 
			and DmSz<> '' and not exists (select 'x' from Param where 
			PTyp= 'DMSZ' and PMCd= DmSz And PValidYn = 'Y')
		if @row> 0 
		Begin
			select @errmsg= 'Design Size Not Defined / Invalid.'
			goto ErrHndlr
		end
/*		Manoj 2.10.0		*/


		/***************Geeta*******2.10***********/
		/* *** Jay 2.13(CT) *** */ 

		/******  If DmTcTyp  = 'PM'  then  DmSz <> Blank  ******/
/*		select @row= count('x') from inserted where DmTcTyp= 'PM' and DmSz= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Design Component Code Cannot Be Blank'
			goto ErrHndlr
		end
*/
		/******  If DmTcTyp  = 'PM'  then  DmSz = Not Blank  ******/
/*		select @row= count('x') from inserted where DmTcTyp= 'PM' and DmSz<> '' and 
			not exists (select 'x' from Param where PTyp= 'BCHR' and PMCd= DmSz And PValue= 'C')
		if @row> 0 
		Begin
			select @errmsg= 'Design Component Code Not Defined / Invalid.'
			goto ErrHndlr
		end
*/		/* *** Jay 2.13(CT) *** */ 


		/***Geeta*2.10****/
		/******  If DmSz = Not Blank then record with Blank Size should exist in DsgMst for the same DmTcTyp ('DM' in case of 'PM') and DmCd  ******/
		/* Sachin 3.02 - 02-01-08 - Current Partition */
		select @row= count('x') from inserted ins where DmPrtKey=@wCurrPrtn and DmSz<> '' And DmTcTyp <>'PM' 
			and not exists (select 'x' from DsgMst DM where 
					DM.DmTcTyp= (case when ins.DmTcTyp = 'DM' then 'DM'  
									  when ins.DmTcTyp = 'SM' then 'SM' else '' end) 
					and DM.DMCd= ins.DmCd and DM.DmSz= '' and Dm.DmPrtKey=ins.DmPrtKey)
		if @row> 0 
		Begin
			select @errmsg= 'Design Code With Size Blank Does Not Exist'
			goto ErrHndlr
		end
/*
	select @row= count('x') from inserted ins where DmSz<> '' and  not exists (select 'x' from DsgMst DM where 
			DM.DmTcTyp= (case when ins.DmTcTyp in ('DM','PM') then 'DM'  
			when ins.DmTcTyp = 'SM' then 'SM' else '' end) 
			and DM.DMCd= ins.DmCd and DM.DmSz= '')
		if @row> 0 
		Begin
			select @errmsg= 'Design Code With Size Blank Does Not Exist'
			goto ErrHndlr
		end
*/

/*		Manoj 2.10.0		*/
		/******  DmCtg  =  PMCd ('DMCTG')  (Blank allowed in case of 'PM')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'DMCTG' and PMCd= DmCtg) and DmCtg<> ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Category Not Defined'
			goto ErrHndlr
		end
*/
		/* ***** Partition Key added ***** */
		select @row= count('x') from inserted Ins where Ins.DmCtg<> '' And
			Ins.DmCtg <> IsNull((Select Del.DmCtg From Deleted Del Where Ins.DmPrtKey=Del.DmPrtKey 
				and Ins.DmIdNo=Del.DmIdNo and Ins.DmTcTyp = Del.DmTcTyp And Ins.DmCd = Del.DmCd 
				And Ins.DmSz = Del.DmSz), '') And not exists (select 'x' from Param where PTyp= 'DMCTG' and PMCd= Ins.DmCtg And PValidYn = 'Y') 
		if @row> 0 
		Begin
			select @errmsg= 'Design Category Not Defined / Invalid.'
			goto ErrHndlr
		end
/*		Manoj 2.10.0		*/

		/* Sachin 3.02 - 02-01-08 - Current Partition */
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmCtg= '' and DmPrtKey=@wCurrPrtn
		if @row> 0 
		Begin
			select @errmsg= 'Design Category Should Be Entered'
			goto ErrHndlr
		end

/*		Manoj 2.10.0		*/
		/******  DmPrdCtg  =  PMCd ('PRDCTG')  (Blank allowed in case of 'PM')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'PRDCTG' and PMCd= DmPrdCtg) and DmPrdCtg<> ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Production Category Not Defined'
			goto ErrHndlr
		end
*/
		/* ***** Partition Key/IdNo added */
		Select @row= count('x') from inserted Ins where Ins.DmPrdCtg <> '' And 
			Ins.DmPrdCtg <> IsNull((Select Del.DmPrdCtg From Deleted Del Where 
				Ins.DmIdNo=Del.DmIdNo and Ins.DmTcTyp = Del.DmTcTyp 
				And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
			not exists (select 'x' from Param where PTyp= 'PRDCTG' and PMCd= Ins.DmPrdCtg And PValidYn = 'Y')
		If @row> 0 
		Begin
			select @errmsg= 'Design Production Category Not Defined / Invalid.'
			goto ErrHndlr
		end
/*		Manoj 2.10.0		*/

		/* Sachin 3.02 - 02-01-08 - Current Partition */
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmPrdCtg= '' and DmPrtKey=@wCurrPrtn
		if @row> 0 
		Begin
			select @errmsg= 'Design Production Category Should Be Entered'
			goto ErrHndlr
		end

/*		Manoj 2.10.0		*/
		/******  DmSalCtg  =  PMCd ('SALCTG')  (Blank allowed in case of 'PM')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'SALCTG' and PMCd= DmSalCtg) and DmSalCtg<> ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Not Defined'
			goto ErrHndlr
		end
*/

		/*********Geeta*****Crm***2.12************/
		select @row= count('x') from inserted Ins where Ins.DmSalCtg<> '' And
			Ins.DmSalCtg <> IsNull((Select Del.DmSalCtg From Deleted Del Where 
				Ins.DmIdNo=Del.DmIdNo and Ins.DmTcTyp = Del.DmTcTyp 
				And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
			not exists (select 'x' from Param where PTyp= 'SALCTG'  and PMCd=DmCtg and PSCd= DmSalCtg And PValidYn = 'Y') 
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Not Defined / Invalid.'
			goto ErrHndlr
		end

		select @row= count('x') from inserted Ins where 
			not exists (select 'x' from Param where PTyp= 'SALCTG' and PMCd=DmCtg and PSCd= DmSalCtg) 
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Not Defined.'
			goto ErrHndlr
		end
	
		/*********Geeta*****Crm***2.12************/
/*		Manoj 2.10.0		*/

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmSalCtg= ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Should Be Entered'
			goto ErrHndlr
		end

		/******  DmBagPcs  > 0  (<= Zero allowed in case of 'PM')  ******/
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmBagPcs<= 0
		if @row> 0 
		Begin
			select @errmsg= 'Bag Opening Pieces Cannot Be Zero'
			goto ErrHndlr
		end

		/**** Jay 3.1.0_1 *** */
		Select @row= count('x') from inserted Ins 
			where not exists (select 'x' from Param where PTyp= 'SETCD' and PMCd= Ins.DmSetCd)
				and exists(select 'x' from Head where HCoCd= 'ZZZ' and HValidDsgSetCd= 'Y')
		If @row> 0 
		Begin
			select @errmsg= 'Design Set Code Not Defined/Can Not Be Blank.'
			goto ErrHndlr
		end
		/**** Jay 3.1.0_1 *** */

		/******  DmCmCd  =  Blank  or  valid  CmCd  from CustMst (CmCtg = 'C')  ******/
		select @row= count('x') from inserted where DmCmCd<> '' 
			and not exists (select 'x' from CustMst where 
			CmCtg= 'C' and (',' + DmCmCd + ',') Like ('%,' + CmCd + ',%'))			
		if @row> 0 
		Begin
			select @errmsg= 'One of the Customer Code Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmPrfVendCd<> '' 
			and not exists (select 'x' from CustMst where 
			CmCtg= 'S' and CmCd =DmPrfVendCd) 		
		if @row> 0 
		Begin
			select @errmsg= 'Preferred Vendor Code Invalid'
			goto ErrHndlr
		end
		/******  DmHld  =  PMCd ('YN')  ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'YN' and PMCd= DmHld)
		if @row> 0 
		Begin
			select @errmsg= 'Enter Design On Hold as ''Y'' or ''N'' '
			goto ErrHndlr
		end

		/******  DmParts  >  0  ******/
		select @row= count('x') from inserted where DmParts<= 0
		if @row> 0 
		Begin
			select @errmsg= 'Design Parts Cannot Be Zero'
			goto ErrHndlr
		end

/*		MAnoj 2.10.0		*/
		/******  DmCol  =  PMCd ('DMCOL')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd= DmCol)
		if @row> 0 
		Begin
			select @errmsg= 'Design Colour Not Defined'
			goto ErrHndlr
		end
*/

		/*** (Bef 3.01)
		select @row= count('x') from inserted Ins where 
			Ins.DmCol <> IsNull((Select Del.DmCol From Deleted Del Where 
				Ins.DmTcTyp = Del.DmTcTyp And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
			not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd= Ins.DmCol And PValidYn = 'Y')
		if @row> 0 
		Begin
			select @errmsg= 'Design Colour Not Defined / Invalid.'
			goto ErrHndlr
		end
		(Bef 3.01) ***/
/*		Manoj 2.10.0		*/

		/*** (Jen 3.01) ***/
		select @row= count('x') from inserted Ins where 
			Ins.DmCol= '' or 
			(	Ins.DmCol <> IsNull((Select Del.DmCol From Deleted Del Where Ins.DmIdNo=Del.DmIdNo and 
				Ins.DmTcTyp = Del.DmTcTyp And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
				not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd= Ins.DmCol And PValidYn = 'Y')
			)
		if @row> 0 
		Begin
			select @errmsg= 'Design Colour Not Defined / Invalid.'
			goto ErrHndlr
		end
		/*** (Bef 3.01) ***/


		/******  DmPrdSeq  =  PMCd ('PRDSEQ')  (Blank allowed in case of 'PM')  ******/
		/***uma *** prd to prc****/
		select @row= count('x') from inserted where DmPrcsSeq  <> '' and 
			not exists (select 'x' from vParam where 
				vPTyp= 'PRCSSEQ' and vPMCd= DmPrcsSeq) 
		if @row> 0 
		Begin
			select @errmsg= 'Process Sequence Not Defined'
			goto ErrHndlr
		end
		/*** uma **** DmPrdSeq= '' ****/
		/*select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmPrdSeq= ''
		if @row> 0 
		Begin
			select @errmsg= 'Production Sequence Should Be Entered'
			goto ErrHndlr
		end*/
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmPrcsSeq = ''
		if @row> 0 
		Begin
			select @errmsg= 'Process Sequence Should Be Entered'
			goto ErrHndlr
		end
		

		/******  DmUom  =  PMCd ('DMUOM')  (Blank allowed in case of 'PM')  ******/ 
		select @row= count('x') from inserted where DmUom<> '' and 
			not exists (select 'x' from Param where 
			PTyp= 'DMUOM' and PMCd= DmUom)
		if @row> 0 
		Begin
			select @errmsg= 'Design Unit Of Measurement Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmUom= ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Unit Of Measurement Should Be Entered'
			goto ErrHndlr
		end

		/******  DmVaCtg  =  PMCd ('VACTG')  (Blank allowed in case of 'PM')  ******/
		select @row= count('x') from inserted where DmVaCtg<>'' and 
			not exists (select 'x' from Param where 
			PTyp= 'VACTG' and PMCd= DmVaCtg)
		if @row> 0 
		Begin
			select @errmsg= 'Value Addition Category Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmVaCtg= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Value Addition Category Should Be Entered'
			goto ErrHndlr
		end

		/******  DmKt  =  PMCd ('KT')  ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'KT' and PMCd= DmKt)
		if @row> 0 
		Begin
			select @errmsg='Karat Not Defined'
			goto ErrHndlr
		end

		/******  DmLsCtg  =  valid  PMCd ('LSCTG')  ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'LSCTG' and PmCd= DmLsCtg)
		if @row> 0 
		Begin
			select @errmsg= 'Loss Category Not Defined'
			goto ErrHndlr
		end

		/******  DmRegnExc  =  Blank  or  valid  PMCd ('YN')  ******/
		select @row= count('x') from inserted where DmRegnExc<> '' 
			and not exists (select 'x' from Param where 
			PTyp= 'YN' and PmCd= DmRegnExc)
		if @row> 0 
		Begin
			select @errmsg= 'Region Exclusivity Not Defined'
			goto ErrHndlr
		end

		/******  DmRegnExc  =  valid  PMCd ('YN') when DmCmCd<> '' ******/
		select @row= count('x') from inserted where DmCmCd<> '' and DmRegnExc= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Specify Whether The Dsg Is Region Exclusive For The Cust Or Not'
			goto ErrHndlr
		end

		/******  DmRegnExc  =  Blank when DmCmCd= '' ******/
		select @row= count('x') from inserted where DmCmCd= '' and DmRegnExc<> '' 
		if @row> 0 
		Begin
			select @errmsg= 'Region Exclusivity Not To Be Entered When Customer Is Not Specified'
			goto ErrHndlr
		end
		/******      *******/
/*		select @row= count('x') from inserted where DrQty <> DrPrdQty and DrWt <> DrPrdWt and
			(Select HShowPrdRmDets from head where HCd= @ctSelfCmCd and HCoCd = @wSelfCoCd) = 'N' 
		if @row> 0 
		Begin
			select @errmsg= 'Both the Weights and Quantities should be equal'
			goto ErrHndlr
		end
*/

/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
		/******  DmLockYN =  valid  PMCd ('YN')  ******/
		select @row= count('x') from inserted where
			Not Exists (select 'x' from Param where PTyp= 'YN' and PmCd= DmLockYN)
		if @row> 0
		Begin
			select @errmsg= 'Design Lock (Y/N) Not Defined'
			goto ErrHndlr
		end
/*  #########################################  Manoj  #########################################  */
	end


	/****** Check For Use In OrdDsg, CustDsg, Fgd   ******/	
	/****** If In Use Do Not Allow Delete ******/
	if @mode = 'D'  And @ReplAgt <> 1
	begin
		/****** Cannot a delete a record with DmSz= '' if record with DmSz Not Blank exists for the same DmTcTyp ('DM' in case of 'PM') and DmCd ******/
/****Geeta***2.10***/
/*
		select @row= count('x') from deleted del where DmSz= '' and 
			( (del.DmTcTyp = 'DM' and exists (select 'x' from DsgMst DM where DM.DmTcTyp in ('DM','PM') 
				and DM.DMCd= del.DmCd and DM.DmSz<> ''))
			or (del.DmTcTyp = 'SM' and exists (select 'x' from DsgMst DM where DM.DmTcTyp= 'SM'  
				and DM.DMCd= del.DmCd and DM.DmSz<> ''))
			)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Design As Record With Size Not Blank Exists'
			goto ErrHndlr
		end
*/
		/* Sachin 3.02 - 02-01-08 */
		select @row= count('x') from deleted del where DmSz= '' and 
			 del.DmTcTyp <> 'PM' and exists (select 'x' from DsgMst DM where DM.DmTcTyp =Del.DmTctyp 
				and DM.DMCd= del.DmCd and DM.DmSz<> '' and del.DmPRtKey=DM.DmPrtKey)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Design As Record With Size Not Blank Exists'
			goto ErrHndlr
		end

		/* *** Jay 2.13(CT) *** */
		/* Sachin 3.02 - 02-01-08 */
		select @row= count('x') from deleted del where DmTcTyp = 'PM' and DmPRtKey=@wCurrPrtn
			and exists (select 'x' from DsgCt where DctCd= DmCd and DctSz=DmSz and DctPrtKey=DmPrtKey)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Component Used In DsgCt Table'
			goto ErrHndlr
		end
		/* *** Jay 2.13(CT) *** */	

		/* *** Jay 2.13(CT) *** */
		select @row= count('x') from deleted del where DmTcTyp = 'PM' 
			and exists (select 'x' from OrdCt where OctCd= DmCd and OctSz=DmSz)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Component Used In OsgCt Table'
			goto ErrHndlr
		end
		/* *** Jay 2.13(CT) *** */	

		/* Bef 2.13(CT)
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'PM' 
			and exists (select 'x' from DsgPrt where DpPrtCd= DmCd and DpPrtSz=DmSz)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Part In Use In DsgPrt Table'
			goto ErrHndlr
		end
		 Bef 2.13(CT)*/
		/***********Geeta****2.10******************/	
		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from OrdDsg where OdDmIdNo=DmIdNo and OdDmCd= DmCd and 
					(Select PValue from Param where PTyp= 'TC' and PMCd= OdTc) in ('SO', 'QT', 'PL') )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design In Use In OrdDsg Table'
			goto ErrHndlr
		end

		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'SM' 
			and exists (select 'x' from OrdDsg where OdDmIdNo=DmIdNo and OdDmCd= DmCd and 
					(Select PValue from Param where PTyp= 'TC' and PMCd= OdTc)= 'QS')
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Sketch In Use In OrdDsg Table'
			goto ErrHndlr
		end

/*		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp in('DM', 'SM') 
			and exists (select 'x' from OrdDsg where OdDmCd= DmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design In Use In OrdDsg Table'
			goto ErrHndlr
		end
*/
		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from CustDsg where CdPrtKey=DmPrtKey and CdOurDmCd= DmCd)
		if @row> 0 
		Begin
			select @errmsg='Cannot Delete As Design In Use In CustDsg Table'
			goto ErrHndlr
		end

		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from Fgd where FdDmIdNo=DmIdNo and FdDmCd= DmCd and FdBNo= 0)
		if @row> 0 
		Begin
			select @errmsg='Cannot Delete As Design In Use In Fgd Table'
			goto ErrHndlr
		end

    /***** Manali 3.9.1 - RfId Module */		
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from RfIdMst where DmCd=RimDmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design Is In Use In RfId Master Table'
			goto ErrHndlr
		end
		
    /***** Manali 3.10.0 - Multi Price QT Module */		
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from MultiPrcQtDsg where DmCd=MqdDmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design Is In Use In Multi Price Quotation Master Table'
			goto ErrHndlr
		end
		
		
		/****Geeta**Crm**2.12*********Moved To Not For Replication Trigger*****/ 
		/*****Geeta***2.10**DsgPrt*DsgTgt*/
		/****** Delete all records of the child tables DsgRm, DsgLab, DsgAna ******/
/*		Delete DsgRm From deleted, DsgRm where DmTcTyp= DrTcTyp 
			and DmCd= DrCd and DmSz= DrSz 
		Delete DsgLab From deleted, DsgLab where DmTcTyp= DlTcTyp 
			and DmCd= DlCd and DmSz= DlSz 
		Delete DsgAna From deleted join DsgAna on DmTcTyp= DaTcTyp 
			and DmCd= DaCd and DmSz= DaSz 
		Delete DsgPrt From deleted, DsgPrt where DmTcTyp= DpTcTyp 
			and DmCd= DpCd and DmSz= DpSz 
		Delete DsgTgt From deleted, DsgTgt where DmTcTyp= DtTcTyp 
			and DmCd= DtCd and DmSz= DtSz 
*/
	end

	if @SYS= 'XEMR' 
	BEGIN

		/****** If In Use Do Not Allow Delete ******/
		if @mode = 'D' 
		Begin

			/****** Check For Use In xTxnDsg, xDsgYyMm   ******/	
			/****** If In Use Do Not Allow Delete ******/
			select @row= count('x') from deleted where exists
				(select 'x' from xTxnDsg where xTdDmSz= '' and xTdDmTyp= DmTcTyp
					and xTdDmCd= DmCd)	
			if @row> 0 
			Begin
				select @errmsg='Cannot Delete As Design In Use In xTxnDsg Table'
				goto ErrHndlr
			end
			
			select @row= count('x') from deleted where exists
				(select 'x' from xDsgYyMm where xDyDmSz= '' and DmTcTyp= 'DM'
					and xDyDmCd= DmCd)	
			if @row> 0 
			Begin
				select @errmsg='Cannot Delete As Design In Use In xDsgYyMm Table'
				goto ErrHndlr
			end
		End

	END


	
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end


GOGO

ALTER TRIGGER [dbo].[Head_INUPDL] ON [dbo].[Head]
    FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/* *** Trigger Version 3.11.0 *** */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wSelfCoCd varchar(3)
	DECLARE @ReplAgt BIT
	
	set @wSelfCoCd= 'ZZZ'
	set @wSelfCd = 'ZSELF'	

	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Head')
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
			else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
			end 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd  +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd  +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	If @mode in ('A' , 'C')
	Begin
	/* Zubin 211 (hFluteBagYN= ins.hFluteBagYN and HDTPrdPtr= ins.HDTPrdPtr added) */ 
		/*** introduced hLooseInv (Jen 2.12 Patch 3)***/
		/*** introduced HConsolidatedInv, HAutomateReturns (Jen 2.13)***/
		/****** Sachin 2.13.0 - introduced HQWModYN And HModAvlYN ******/ 
		/****** Sachin 2.14.0 - introduced HImpComLoc ******/ 
		/* Zubin 213 (HMultiCurYn added) */ 
		/* *** JAY 2.13(CT) *** (hCompBagsYn ADDED)*/
		/* *** Jay 2.14(LclInv) *** [HLclInvYn]*/
		/* *** Jay 3.01 *** [FgTag Module] */
		/*** (Jen 3.1.0_1 added HInInvGrsWtEqActual) ***/
		/*** Jay 3.1.0_1 [HValidDsgSetCd] ***/ 
		/****** Jen (3.1.2) added hBestUse ******/
		/****** Manali 3.03 added HPdModYN */
		/****** Sachin 3.3.0 (30-06-08) - [hChkVldRmLnYN added for 28. Valid RmSz Master] */
		/*** Jay 3.3(FG) [hFgIOYn] ***/
		/***** Manali 3.4.1 - 22/10/08 - Design Catalogue Module [added HDsgCatYN] *****/
		/* **** Manali 3.5.0 -  hCustomizeRmCtgExp, HMaxDsgViewRec added */
		/* **** Manali 3.6.0 - HOrdExcelRepYn added */
		/* **** Manali 3.9.1 - RfId Module ****/
		/* **** Manali 3.10.0 - Multi Price Quotation Module */
        /* 4.1.4 */
		Update Head 
		Set hCmFixPrc= ins.hCmFixPrc, hCmGldAs= ins.hCmGldAs, hCmLabAs=ins.hCmLabAs, 
			hCmIWtEqOrd = ins.hCmIWtEqOrd, hCmIWtFrOrd= ins.hCmIWtFrOrd, 
			hCmIGldRtEqOrd= ins.hCmIGldRtEqOrd, hCmDiaRtFA= ins.hCmDiaRtFA, 
			hCmCsRtFA= ins.hCmCsRtFA, HPtrYn= ins.HPtrYn, 
			hPPCYN= ins.hPPCYN, HPDCSfx= ins.HPDCSfx,
			HRndOrdSalPrc= ins.HRndOrdSalPrc, HShowPrdRmDets= ins.HShowPrdRmDets, 
			HCtbMod= ins.HCtbMod, hFluteBagYN= ins.hFluteBagYN, 
			HDTPrdPtr= ins.HDTPrdPtr, HSlvModYN = ins.HSlvModYN, HPdModYN = ins.HPdModYN,
			hLooseInv= ins.hLooseInv, hConsolidatedInv= ins.hConsolidatedInv, 
			HAutomateReturns= ins.HAutomateReturns, HQWModYN = Ins.HQWModYN, 
			HModAvlYN = Ins.HModAvlYN, HMultiCurYn= Ins.HMultiCurYn, hCompBagsYn= Ins.hCompBagsYn,
			HImpComLoc = Ins.HImpComLoc, HInRepMetLsRmCd= Ins.HInRepMetLsRmCd, HLclInvYn= Ins.HLclInvYn,
			HFgTagMod = Ins.HFgTagMod, HCustomiseOrd= Ins.HCustomiseOrd, HAutoCustmMtch= Ins.HAutoCustmMtch, 
			HInInvGrsWtEqActual= Ins.HInInvGrsWtEqActual, HValidDsgSetCd = Ins.HValidDsgSetCd, 
			hBestUse= Ins.hBestUse, hChkVldRmLnYN= Ins.hChkVldRmLnYN , HExcelImpInOrdYN=Ins.HExcelImpInOrdYN,
			HTravelExlYN=Ins.HTravelExlYN,hFgIOYn= Ins.hFgIOYn, HDsgCatYN= Ins.HDsgCatYN, 
			hCustomizeRmCtgExp=Ins.hCustomizeRmCtgExp, HMaxDsgViewRec=ins.HMaxDsgViewRec, HOrdExcelRepYn=Ins.HOrdExcelRepYn,
			HRfIdMod=ins.HRfIdMod, HMultiPrcQtMod=ins.HMultiPrcQtMod, hRtfrRtChrtYN=ins.hRtfrRtChrtYN,
			hTolQtyPctDC=ins.hTolQtyPctDC, hTolWtPctDC=ins.hTolWtPctDC, HCstRtEdtYn = ins.HCstRtEdtYn,
			hRwrkModYn = ins.hRwrkModYn    
		From Inserted ins where ins.HCoCd= @wSelfCoCd and Head.HCd= ins.HCd 
			And Head.HCoCd<> ins.HCoCd 
			And (IsNull((Select ''','+ SdCoCd + ',''' From SysDb Where SysId='EMR'),',' + Head.HCoCd + ',')) Like
					'%,' + Head.HCoCd + ',%'  
	/* Zubin 211 (hFluteBagYN= ins.hFluteBagYN added) */ 

/*      urmi 2.04-3 maintain HPtrYn same for other cocds as that of 'ZZZ'*/
/**  	Update the HPtrYn for other  Compny Codes when changed for 'ZZZ'    **/
/*		select @row=count('x') from inserted ins where ins.HCoCd= @wSelfCoCd and
			Exists(Select 'x' from Deleted del where 
				ins.HCoCd= del.HCoCd and ins.HCd= del.HCd and ins.hPtrYN<> del.hPtrYN)
		if @row> 0 
		begin
			Update Head set HPtrYn = (select H1.hPtrYn from inserted H1 where H1.HCoCd= @wSelfCoCd)
			where HCoCd<> @wSelfCoCd			
		end
*/
	End

	if @mode in ('A','C')
	Begin
		/****** Sachin 3.3.0 - Cannot Update the Check Integrity Field ******/
		Select @row=count('x') from inserted ins Where 
			Not Exists(Select 'x' From Deleted del Where del.HChkIntgty=ins.HChkIntgty)
		if @row>0 
		begin
			select @errmsg= ' Cannot Update Check Integrity Field...'
			goto ErrHndlr
		end

		/****** The HCd field in Head will always have the value 'ZSELF' ******/
		select @row=count('x') from inserted where HCd<> 'ZSELF' 
		if @row>0 
		begin
			select @errmsg= ' In Head Master Head Code Should Always Be ''ZSELF'' '
			goto ErrHndlr
