			(convert (decimal (14, 2), HPtrMinusX)<> convert (decimal (14, 2), 0) and convert (decimal (14, 2), HPtrPlusX)<> convert (decimal (14, 2), 0) and convert (decimal (14, 2), HPtrMinusX)> convert (decimal (14, 2), HPtrPlusX)) 
		if @row> 0 
		begin
			select @errmsg= 'From Pc/Ct Variation Percentage Cannot Be Greater Than To Pc/Ct Variation Percentage' 
			goto ErrHndlr 
		end
		/*** (Jen 3.01) ***/ 

		/* ***** Manali 3.03 - Check on bef and aft dates for Auto-Custom matching ***** */
		Select @row= count('x') from Inserted where
			(HImpAftD <> '01/01/80' and HImpBefD <> '01/01/80' and HImpAftD > HImpBefD ) Or
			(HImpAftC <> '01/01/80' and HImpBefC <> '01/01/80' and HImpAftC > HImpBefC ) Or
			(HImpAftG <> '01/01/80' and HImpBefG <> '01/01/80' and HImpAftG > HImpBefG ) Or
			(HImpAftP <> '01/01/80' and HImpBefP <> '01/01/80' and HImpAftP > HImpBefP ) Or
			(HImpAftS <> '01/01/80' and HImpBefS <> '01/01/80' and HImpAftS > HImpBefS ) Or
			(HImpAftL <> '01/01/80' and HImpBefL <> '01/01/80' and HImpAftL > HImpBefL ) Or
			(HImpAftX <> '01/01/80' and HImpBefX <> '01/01/80' and HImpAftX > HImpBefX ) 
		If @row> 0 
		Begin
			Select @errmsg= 'Import After Date(s) Cannot Be Greater Than Import Before Date(s)' 
			Goto ErrHndlr 
		End
		/* ***** Manali 3.03 - Check on bef and aft dates for Auto-Custom matching ***** */


		/*** (Jen 3.1.0_1) ***/ 
		Select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= HInInvGrsWtEqActual) 
		if @row> 0 
		begin 
			select @errmsg= 'Specify Whether To Keep The Invoice Gross Weight Equal To Actual Gross Weight During Copy (Y/N)' 
			goto ErrHndlr 
		end
		/*** (Jen 3.1.0_1) ***/ 
		/*** Jay 3.1.0_1 ***/ 
		Select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= HValidDsgSetCd) 
		if @row> 0 
		begin 
			select @errmsg= 'Design Set Code Validate from Param (Yes/ No) Invalid.' 
			goto ErrHndlr 
		end
		/*** Jay 3.1.0_1 ***/ 

		/*** (Jen 3.1.2) ***/
		Select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= hBestUse) 
		if @row> 0 
		begin
			select @errmsg= 'Enable Best Use In Auto Custom Matching (Y/N)' 
			goto ErrHndlr 
		end
		/*** (Jen 3.1.2) ***/

		/* Sachin 3.11.0 - Invoice rate from Rate Chart */
		select @row=count('x') from inserted where 
			Not Exists (select 'x' from Param where PTyp='YN' and PMCd= hRtfrRtChrtYN and PSCd= '')
		if @row>0 
		begin
			select @errmsg= '''Invoice Rates from Rate Chart'' (Enter Y/N)' 
			goto ErrHndlr
		End 

	End

	if @mode = 'C' 
	Begin
		/****** Key Cannot Be Changed ******/
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.HCoCd= del.HCoCd and ins.HCd= del.HCd) 
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Company Code'
			GoTo ErrHndlr
		end
		/****** Cannot Change HName ******/	
		select @row=count('x') from inserted ins where 
			not Exists(Select 'x' from Deleted del where 
				ins.HCoCd= del.HCoCd and ins.HCd= del.HCd and ins.HName= del.HName)
		if @row>0 
		begin
			select @errmsg= 'Cannot Change Company Name'
			goto ErrHndlr
		end
		/****** Cannot change hPtrYN if 'Ptr Y/N' is 'Y' for any RmSCtg ******/	
		select @row=count('x') from inserted ins where 
			not Exists(Select 'x' from Deleted del where 
				ins.HCoCd= del.HCoCd and ins.HCd= del.HCd and ins.hPtrYN= del.hPtrYN)
			and exists (select 'x' from Param where PTyp= 'RMSCTG' and PValue2= 'Y')
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change The ''Ptr Y/N'' Option When ''Ptr Y/N'' option of RMSCTG is ''Y'' '
			goto ErrHndlr
		end

		/****** Cannot Change ExpLocal Option ******/	
		select @row=count('x') from inserted ins where 
			not Exists(Select 'x' from Deleted del where 
				ins.HCoCd= del.HCoCd and ins.HCd= del.HCd and ins.hExpLocal= del.hExpLocal)
		if @row>0 
		begin
			select @errmsg= 'Cannot Change The Local Export Option'
			goto ErrHndlr
		end

		/****** Cannot Change 'Show PPC Module' option if rec exists in PpcCap, OrdPln, OrdPlnDt ******/	
		select @row= count('x') from inserted ins where 
			not Exists(Select 'x' from Deleted del where ins.HCoCd= del.HCoCd 
					and ins.HCd= del.HCd and ins.hPpcYN= del.hPpcYN) 
			and (	Exists(Select 'x' from PpcCap where PcCoCd= HCoCd) 
				Or Exists(Select 'x' from OrdPln where OpCoCd= HCoCd) 
			    )
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change ''Show PPC Module'' Option As Plan Rec Exists'
			goto ErrHndlr
		end

		/*** Check For HShowPrdRmDets ***/
		/*select @row= count('x') from inserted ins where 
			ins.HShowPrdRmDets= 'N' and 
			Exists(Select 'x' from Deleted del where ins.HCoCd= del.HCoCd and 
				ins.HCd= del.HCd and del.HShowPrdRmDets= 'Y') 
			and Exists(Select 'x' from OrdRm where OrCoCd= HCoCd 
				   and (	Str(OrPrdWt, 16, 3)<> Str(OrWt, 16, 3) 
						or OrQty<> OrPrdQty
					) 
				   )
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change 'Show Prd Rm Dets' Option To 'N' As OrdRm Rec Exists Where OrdWt<> PrdWt or OrdQty<> PrdQty'
			goto ErrHndlr
		end*/

		/*** Check For HShowPrdRmDets ***/
		select @row= count('x') from inserted ins where ins.hCoCd= @wSelfCoCd and
			ins.HShowPrdRmDets= 'N' and 
			Exists(Select 'x' from Deleted del where ins.HCoCd= del.HCoCd and 
				ins.HCd= del.HCd and del.HShowPrdRmDets= 'Y') 
			and (Exists(Select 'x' from OrdRm where 
					Str(OrPrdWt, 16, 3)<> Str(OrWt, 16, 3) 
					or OrQty<> OrPrdQty)   
				or Exists(Select 'x' from DsgRm where 
					Str(DrPrdWt, 16, 3)<> Str(DrWt, 16, 3) 
					or DrQty<> DrPrdQty)  
			    )
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change ''Show Prd Rm Dets'' Option To ''N'' As OrdRm Rec Exists Where OrdWt<> PrdWt or OrdQty<> PrdQty'
			goto ErrHndlr
		end

		/*** Check For Bag Acknowledgement ***/
		select @row= count('x') from inserted ins where ins.hTdAck= 'N' and 
			Exists(Select 'x' from Deleted del where ins.HCoCd= del.HCoCd and 
				ins.HCd= del.HCd and del.hTdAck= 'Y')
			and Exists(Select 'x' from Txnd join Param on PTyp = 'TC' and 
				PMCd = TdTc where TdCoCd= HCoCd and PValue = 'BV' and 
				TdAck = 'N')
		if @row>0 
		begin
			select @errmsg= 'Cannot Change ''Acknowledgement Reqd'' Option If Any Bag Movement Is UnAcknowledged'
			goto ErrHndlr
		end

		/****** HCtbMod cannot be changed to 'N' if record exists in CustMst(CmCtg= 'T') ******/	
		select @row= count('x') from inserted where HCtbMod= 'N' 
			and exists (select 'x' from CustMst where CmCtg= 'T') 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change The ''Show Contractor Module'' Option To ''N'' When Contractor Code Exists'
			goto ErrHndlr
		end
		/* Zubin 213 - HBaseCurCd shld be valid */ 
		select @row= count('x') from inserted ins where 
			Not Exists (select 'x' from Param where PTyp= 'CURNCY' and PMCd= HBaseCurCd and PSCd= '') 
		if @row> 0 
		begin
			select @errmsg= 'Invalid Currency Code' 
			goto ErrHndlr
		end

		/* Zubin 213 - Cannot change Base Cur if rec exists in DtTbl table */ 
		select @row= count('x') from deleted del where 
			Not Exists (select 'x' from inserted ins where ins.hCd= del.hCd and ins.hCoCd= del.hCoCd and 
				ins.HBaseCurCd= del.HBaseCurCd) and 
			Exists (select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
				(DtCurCd1= HBaseCurCd or DtCurCd2= HBaseCurCd) ) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change ''Base Currency Code'' As Record(s) Exist In Date Table For Currency Conversion' 
			goto ErrHndlr
		end
		/* Zubin 213 (250606) - Cannot change Base Cur if rec exists in OrdMst table */ 
		select @row= count('x') from deleted del where 
			Not Exists (select 'x' from inserted ins where ins.hCoCd= del.hCoCd and ins.hCd= del.hCd and 
				ins.HBaseCurCd= del.HBaseCurCd) and 
			Exists (select 'x' from OrdMst where OmCoCd= HCoCd) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change ''Base Currency Code'' As Record(s) Exist In Order Master Table' 
			goto ErrHndlr
		end
		/* Zubin 213 - Cannot change Base Cur if rec exists in Txn table */ 
		select @row= count('x') from deleted del where 
			Not Exists (select 'x' from inserted ins where ins.hCoCd= del.hCoCd and ins.hCd= del.hCd and 
				ins.HBaseCurCd= del.HBaseCurCd) and 
			Exists (select 'x' from Txn where TCoCd= HCoCd) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change ''Base Currency Code'' As Record(s) Exist In Txn Table' 
			goto ErrHndlr
		end
		/* Zubin 213 (250606) */ 
		
		/* ****** Sachin 2.14.0 - 27-10-2006 [Multi-Company] ****** */
		Select @row= Count('x') From Deleted Del Where Del.HImpComLoc='Y' And
			Not Exists (Select 'x' From Inserted Ins Where Ins.hCoCd= Del.hCoCd And Ins.hCd= Del.hCd and 
				Ins.HImpComLoc= del.HImpComLoc) And 
			Exists (Select 'x' From Loc Where LocPrntCd<>'' Or LocPrntYN='Y') 
		If @row> 0 
		Begin
			Select @errmsg= 'Cannot Change ''Implement Common Locations'' As Record(s) Exist With Parent Location Codes in Loc Master Table' 
			GoTo ErrHndlr
		End
		/* ****** Sachin 2.14.0 - 27-10-2006 [Multi-Company] ****** */

		/*** (Jen 3.01) ***/
		Select @row= Count('x') From Deleted Del Where Del.HCustomiseOrd= 'Y' And 
			Not Exists (Select 'x' From Inserted Ins Where Ins.hCoCd= Del.hCoCd And Ins.hCd= Del.hCd and 
				Ins.HCustomiseOrd= del.HCustomiseOrd) And 
			Exists (Select 'x' From UsrRight where not(UrGrp= '')) 
		If @row> 0 
		Begin
			Select @errmsg= 'Cannot Change ''Customise Order Entry Screen'' As User Right Record(s) Exists' 
			GoTo ErrHndlr
		End
		/*** (Jen 3.01) ***/

		Select @row=count('x') from Inserted where 
			Not Exists (select 'x' from Param where PTyp='YN' and PMCd= HjStkNumjFrBagYN and PSCd= '')
		if @row>0 
		begin
			select @errmsg= 'Invalid ''Copy jEmr DmStkNum from Bag'' value. (Enter Y/N)' 
			goto ErrHndlr
		End 


	End

	If @mode = 'D' 
	Begin
		/****** Cannot Delete Any Record ******/	
		Select @row= count('x') from deleted 
		If @row> 0 
		Begin
			Select @errmsg= 'Cannot Delete Any Record From Head file'
			GoTo ErrHndlr
		End
	End

Return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
END

GOGO
ALTER TRIGGER [dbo].[Loc_INUPDL] ON [dbo].[Loc] 
	FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS 
BEGIN 
	/* Trigger Version 3.7.0  */
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @LocTyp varchar(2)
	Declare @wHCd Varchar(8)
	DECLARE @SYS VARCHAR(5)
 	DECLARE @ReplAgt BIT  
	DECLARE @wSelfCoCd varchar(3)
	
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Loc' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	Set @wHCd= 'ZSELF'
	set @wSelfCoCd= 'ZZZ'
	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '')

	/*** Storing LocTyp In The Variable @LocTyp ***/
	select @LocTyp= case  when @mode in ('C', 'A') then (Select max(LocTyp) from inserted)  else (Select max(LocTyp) from deleted) end

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ LocCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ LocCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	
	
 	/******** Locations Of Only One Typ Can Be Inserted At A Time ********/
	select @Row= Count(distinct(LocTyp)) from inserted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Locations Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End
	/******** Locations Of Only One Typ Can Be Deleted At A Time ********/
	select @Row= Count(distinct(LocTyp)) from deleted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Locations Of Only One Type Can Be Acted On'
		GOTo ErrHndlr
	End

	If @mode = 'A'
 	Begin
		/* ****** Location Code if Not Present In the ZZZ Company will be Added to It ****** */
		/***** Manali 3.10.0 - LocAllowLsPer added *****/
		Select @Row=Count('x') From Inserted Ins Where Ins.LocPrntYN='N' And Ins.LocCoCd<>@wSelfCoCd
			And Not Exists (Select 'x' From Loc ZLoc Where Ins.LocCd=ZLoc.LocCd And ZLoc.LocCoCd=@wSelfCoCd)  			
		If @Row > 0
		Begin
			Insert Into Loc (LocCd, LocDesc, LocTyp, LocPrdTyp, LocLoss, LocBrk, LocMsg, ModUsr, ModDt, ModTime,
					LocCoCd, LocPrdStg, LocValidYN, LocLsTyp, LocPrntYN, LocPrntCd, LocAllowLsPer, LocHideYN)  
				Select LocCd, LocDesc, LocTyp, LocPrdTyp, LocLoss, LocBrk, LocMsg, ModUsr, ModDt, ModTime,
					@wSelfCoCd, LocPrdStg, LocValidYN, LocLsTyp, LocPrntYN, LocPrntCd, LocAllowLsPer, LocHideYN From Inserted 				
		End

		Select @Row=Count('x') From Inserted Ins Where
			 Not Exists (Select 'x' From Loc Lz Where Lz.LocCoCd= @wSelfCoCd And
				Lz.LocCd= Ins.LocCd and Lz.LocTyp=Ins.LocTyp)
		If @Row > 0
		Begin
			Select @ErrMsg='The Location Type of New Location Code Should Match with ''ZZZ'' Location Type'
			GoTo ErrHndlr
		End
	End

 	/******** Key Cannot Be Changed ********/
	/******** LocTyp is Not Part Of The Key But It Is Advisable Not To Change It ********/
 	if @mode = 'C'
 	Begin
		select @Row=Count('x') from deleted del where
			 not exists (Select 'x' from inserted ins where ins.LocCoCd= del.LocCoCd And
				ins.LocCd= del.LocCd and ins.LocTyp= del.LocTyp)
		If @Row > 0
		Begin
			Select @ErrMsg='Cannot Change Company Code/ Location Code/ Type'
			GoTo ErrHndlr
		End

		/* ****** Sachin 2.14.0 [Multi-Company] ****** */
		/* Cannot change PValidYN to 'N' if the Parent Code is in Use in Other Companies */
		Select @Row=Count('x') From Deleted Del Where Del.LocPrntYN='Y' And Del.LocValidYN='Y' And Del.LocCoCd=@wSelfCoCd			
			And Exists (Select 'x' From Inserted Ins Where Ins.LocCoCd=Del.LocCoCd And Ins.LocCoCd=@wSelfCoCd And			
							Ins.LocCd=Del.LocCd And Ins.LocPrntYN='Y' And Ins.LocValidYN='N')
			And Exists (Select 'x' From Loc Lc Where Lc.LocCoCd<>@wSelfCoCd And Lc.LocPrntYN='N' And Lc.LocPrntCd=Del.LocCd)
		If @Row > 0
		Begin
			Select @ErrMsg='Cannot Change Valid YN As Parent Code is in Use in Other Companies'
			GoTo ErrHndlr
		End

		/* Cannot Change Parent Code Fields If the Common Locations Module is Set to 'N' In Head Master */
		Select @Row=Count('x') From Deleted Del Where
			Exists (Select 'x' From Head Where HCd=@wHCd And HCoCd=Del.LocCoCd And HImpComLoc='N')  
			And Exists (Select 'x' From Inserted Ins Where Ins.LocCoCd=Del.LocCoCd And 
				Ins.LocCd=Del.LocCd And (Ins.LocPrntYN<>Del.LocPrntYN Or Ins.LocPrntCd<>Del.LocPrntCd))
		If @Row > 0
		Begin
			Select @ErrMsg='Cannot Change Location Parent Code Fields If ''Implement Common Locations'' Module is Set to ''N'' In Head Master'
			GoTo ErrHndlr
		End
		
		--Updating the Parent Code of the Location in Company 'ZZZ' will update the Parent Code for that Location in Other Companies also
		Select @Row=Count('x') From Inserted Ins Where Ins.LocPrntYN='N' And Ins.LocCoCd=@wSelfCoCd And
				Exists (Select 'x' From Deleted Del Where Del.LocCoCd=Ins.LocCoCd And Del.LocCd=Ins.LocCd And Del.LocPrntCd<>Ins.LocPrntCd)
				And Exists (Select 'x' From Head Where HCd=@wHCd And HCoCd=Ins.LocCoCd And HImpComLoc='Y')  			
		If @Row > 0
		Begin
			Update Loc
			Set LocPrntCd=Ins.LocPrntCd
			From Loc Lc
				Join Inserted Ins On Lc.LocCd=Ins.LocCd And Ins.LocPrntYN='N'			
			Where Ins.LocPrntYN='N' And Lc.LocCd<>@wSelfCoCd 
		End
		/* ****** Sachin 2.14.0 [Multi-Company] ****** */
	End

	If @mode in ('A','C')
 	Begin
		/* ****** The Parent Code should be specified if Implement Common Location is Enabled in Head Master ****** */
		Select @Row=Count('x') From Inserted Ins Where Ins.LocPrntYN='N' And Ins.LocPrntCd=''  
			And Exists (Select 'x' From Head Where HCd=@wHCd And HCoCd=Ins.LocCoCd And HImpComLoc='Y')  			
		If @Row > 0
		Begin
			Select @ErrMsg='Parent Code Cannot be Blank If ''Implement Common Locations'' is enabled in Head Master'
			GoTo ErrHndlr
		End

		/* ****** The Parent Code should be valid value from ZZZ where ParentYN='Y' ****** */
		Select @Row=Count('x') From Inserted Ins Where Ins.LocPrntYN='N' And  Ins.LocPrntCd<>''  
			And Not Exists (Select 'x' From Loc Lc Where Lc.LocPrntYN='Y' And Lc.LocCoCd=@wSelfCoCd And Lc.LocCd=Ins.LocPrntCd And Lc.LocValidYN='Y') 
			And Exists (Select 'x' From Head Where HCd=@wHCd And HCoCd=Ins.LocCoCd And HImpComLoc='Y')  			
		If @Row > 0
		Begin
			Select @ErrMsg='Not a Valid Parent Code'
			GoTo ErrHndlr
		End

		/* ****** The Parent Code of a Location should be same as the Parent Code of Location in ZZZ ****** */
		Select @Row=Count('x') From Inserted Ins Where Ins.LocPrntYN='N' And Ins.LocCoCd<>@wSelfCoCd And
			Exists (Select 'x' From Head Where HCd=@wHCd And HCoCd=Ins.LocCoCd And HImpComLoc='Y')  
			And Exists (Select 'x' From Loc Lc Where Lc.LocCd=Ins.LocCd And  Lc.LocCoCd=@wSelfCoCd)
			And Not Exists (Select 'x' From Loc Lc Where Lc.LocCd=Ins.LocCd And Lc.LocPrntCd=Ins.LocPrntCd
							And  Lc.LocCoCd=@wSelfCoCd)
		If @Row > 0
		Begin
			Select @ErrMsg='Parent Code Specified should be same as the Parent Code at the ZZZ Company'
			GoTo ErrHndlr
		End
	End	

	/****** LocTyp  =  PMCd ('LOCTYP')  ******/
	Select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp='LOCTYP' and PMCd= LocTyp)
	If @row>0
	Begin
		Select @errmsg='Location Not Defined'
		GoTo ErrHndlr
	End

	/******  LocCoCd = HCoCd   *******/
	select @row=count('x') from inserted where not exists (select 'x' from Head where HCoCd= LocCoCd and HCd= @wHCd)
	if @row>0
	begin
		select @errMsg= 'Company Code Not Valid'
		goto ErrHndlr
	end
	/****** LocCd  =  Not Blank  ******/
	select @row=count('x') from inserted where LocCd= ''
	if @row>0
	Begin
		select @errmsg='Location Code Cannot Be Blank'
		goto ErrHndlr
	end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date: 09/12/2003																			 */
	/******  LocValidYN = PMCD(YN)   *******/
	select @row=count('x') from inserted where
		Not Exists (select 'x' from Param where PTyp = 'YN' And  PMCd= LocValidYN)
	if @row>0
	begin
		select @errMsg= 'LocValidYN Not Valid (Y/N)'
		goto ErrHndlr
	end
/*  #########################################  Manoj  #########################################  */
	/****** If LocTyp = 'P'   then  LocPrdTyp  =  PMCd ('PRDTYP')  else  LocPrdTyp  =  Blank  ******/
	/* ****** Sachin 2.14.0 28-10-2006 [Multi-Company] - LocPrntYN added Below */
		/*** uma LocTyp<> 'P' to LocTyp<> 'R' *******/
	select @row=count('x') from inserted where
			LocTyp= 'R' And LocPrntYN='N' and not exists (select 'x' from Param where PTyp='PRDTYP' and PMCd= LocPrdTyp)
	If @row>0
	Begin
		select @errmsg= 'Production Type Not Defined'
		goto ErrHndlr
	End
	/*** uma LocTyp 'P' refer LocTyp 'R' *******/
	/*select @row= count('x') from inserted ins where ins.LocTyp= 'P' and Ins.LocPrntYn='N' And
			not exists (select 'x' from Loc Lc where Lc.LocCoCd= ins.LocCoCd and Lc.LocTyp= 'R' and Lc.LocCd= ins.LocPrdTyp)	 
	if @row>0
	Begin
		select @errmsg= 'Production Type Not Defined'
		goto ErrHndlr
	End*/
		
	/*** uma LocTyp<> 'P' to LocTyp<> 'R' *******/
	select @row=count('x') from inserted where LocPrdTyp<> '' and (LocTyp<> 'R' Or LocPrntYN='Y') 
	if @row>0
	Begin
		select @errmsg= 'Production Type Should Not Be Entered'
		goto ErrHndlr
	end

	/****** If LocTyp = 'P'   then  LocLoss  =  valid LocCd from Loc(LocTyp = 'L')   else  LocLoss  =  Blank  ******/
	/*** uma LocTyp<> 'P' to LocTyp<> 'R' *******/
	select @row=count('x') from inserted where LocLoss<> '' and (LocTyp<> 'P' Or LocPrntYN='Y')
	if @row>0
	Begin
		select @errmsg='Loss Location Should Not Be Entered'
		goto ErrHndlr
	end
	
	/* ****** Sachin 2.14.0 28-10-2006 [Multi-Company] - LocPrntYN added Below */
	select @row= count('x') from inserted ins where ins.LocTyp= 'P' and Ins.LocPrntYn='N' And
			not exists (select 'x' from Loc Lc where Lc.LocCoCd= ins.LocCoCd and
					 Lc.LocTyp= 'L' and Lc.LocCd= ins.LocLoss)
	if @row> 0
	Begin
		select @errmsg='Loss Location Not Defined'
		goto ErrHndlr
	end
	/****** If LocTyp = 'P'   then  LocBrk  =  valid LocCd from Loc(LocTyp = 'B')   else  LocBrk  =  Blank  ******/
	select @row=count('x') from inserted where LocBrk<> '' and (LocTyp<> 'P' Or LocPrntYN='Y')
	if @row>0
	Begin
		select @errmsg='Break Location Should Not Be Entered'
		goto ErrHndlr
	end
	
	/****Geeta***Emr208***/
	/****** LocLsTyp  =  PMCd ('LSTYP')  ******/
	/* ****** Sachin 2.14.0 28-10-2006 [Multi-Company] - LocPrntYN added Below */
	select @row=count('x') from inserted where LocLsTyp<>'' and LocPrntYN='N' And 
		not exists (select 'x' from Param where PTyp='LSTYP' and PMCd= LocLsTyp)
	if @row>0
	Begin
		select @errmsg='Loss Type Not Defined'
		goto ErrHndlr
	end

	Select @row= count('x') from inserted ins where ins.LocTyp= 'P' And Ins.LocPrntYN='N' And
			not exists (select 'x' from Loc Lc where Lc.LocCoCd= ins.LocCoCd and
					Lc.LocTyp= 'B' and Lc.LocCd= ins.LocBrk)
	If @row> 0
	Begin
		select @errmsg='Break Location Not Defined'
		goto ErrHndlr
	end

	/****** If LocTyp = 'P'   then  LocMsg  =  valid LocCd from Loc(LocTyp = 'M')   else  LocMsg  =  Blank  ******/
	select @row=count('x') from inserted where LocMsg<> '' and (LocTyp<> 'P' Or LocPrntYN='Y')
	if @row>0
	Begin
		select @errmsg='Missing Location Should Not Be Entered'
		goto ErrHndlr
	end

	select @row=count('x') from inserted ins where ins.LocTyp= 'P' and Ins.LocPrntYN='N' And
			not exists (select 'x' from Loc Lc where Lc.LocCoCd= ins.LocCoCd and
					Lc.LocTyp= 'M' and Lc.LocCd= ins.LocMsg)
	if @row>0
	Begin
		select @errmsg='Missing Location Not Defined'
		goto ErrHndlr
	end

	/**Uma *****EmrSv  If LocTyp = 'P' then LocPrcs = valid LocCd from Loc(LocTyp = 'R') ***/
	select @row=count('x') from inserted where LocPrcs <> '' and (LocTyp<> 'P' Or LocPrntYN='Y')
	if @row>0
	Begin
		select @errmsg='Process Should Not Be Entered'
		goto ErrHndlr
	end

	select @row=count('x') from inserted ins where ins.LocTyp= 'P' and Ins.LocPrntYN='N' And
			not exists (select 'x' from Loc Lc where Lc.LocCoCd= ins.LocCoCd and
					Lc.LocTyp= 'R' and Lc.LocCd= ins.LocPrcs)
	if @row>0
	Begin
		select @errmsg='Process Location Not Defined'
		goto ErrHndlr
	end
	
	/**Uma *****EmrSv  If LocTyp = 'P' then LocUseCapOf = valid LocCd from Loc(LocTyp = 'P') ***/
	select @row=count('x') from inserted where LocUseCapOf <> '' and (LocTyp<> 'P' Or LocPrntYN='Y')
	if @row>0
	Begin
		select @errmsg='Physical Location Should Not Be Entered'
		goto ErrHndlr
	end

	select @row=count('x') from inserted ins where ins.LocTyp= 'P' and Ins.LocPrntYN='N' And
			not exists (select 'x' from Loc Lc where Lc.LocCoCd= ins.LocCoCd and
					Lc.LocTyp= 'P' and Lc.LocCd= ins.LocUseCapOf )
	if @row>0
	Begin
		select @errmsg='Physical Location Not Defined'
		goto ErrHndlr
	end

	/****** If LocTyp = 'P'   then  LocPrdStg =  PMCd ('PRDSTG')  else  LocPrdStg  =  Blank  ******/
	select @row= count('x') from inserted where LocTyp= 'R' and LocPrdStg<> '' And LocPrntYN='N'
			and not exists (select 'x' from Param where PTyp='PRDSTG' and PMCd= LocPrdStg)
			/* LocCd<> 'PFG' */
	if @row>0
	Begin
		select @errmsg= 'Production Stage Not Defined'
		goto ErrHndlr
	end
	/*** uma LocTyp<> 'P' to LocTyp<> 'R' *******/
	select @row= count('x') from inserted where (LocTyp<> 'R' or LocCd= 'PFG' Or LocPrntYN='Y') and LocPrdStg<> ''
	if @row> 0
	Begin
		select @errmsg= 'Production Stage Should Not Be Entered'
		goto ErrHndlr
	end
	if @mode = 'D'
	Begin
		/****** Cannot delete Record where LocTyp = 'B' which is in use in Loc Table ******/
		select @row=count('x') from deleted del where del.LocTyp= 'B' and
			exists (select 'x' from Loc Lc where Lc.LocCoCd= del.LocCoCd and
					Lc.LocTyp= 'P' and Lc.LocBrk= del.LocCd)
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Break Location In Use In Loc Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record where LocTyp = 'M' which is in use in Loc Table ******/
		select @row=count('x') from deleted del where del.LocTyp= 'M' and
			exists (select 'x' from Loc Lc where Lc.LocCoCd= del.LocCoCd and
					Lc.LocTyp= 'P' and Lc.LocMsg= del.LocCd)
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Missing Location In Use In Loc Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record where LocTyp = 'L' which is in use in Loc Table ******/
		select @row=count('x') from deleted del where del.LocTyp= 'L' and
			exists (select 'x' from Loc Lc where Lc.LocCoCd= del.LocCoCd and
					Lc.LocTyp= 'P' and Lc.LocLoss= del.LocCd)
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Loss Location In Use In Loc Table'
			goto ErrHndlr
		end

		/****** Cannot delete Record which is in use in Param  Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from vParam where vPCoCd = LocCoCd and vPTyp= 'CHR' and
					(vPDesc225= LocCd or vPValue= LocCd or vPValue1= LocCd))
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''CHR'' '
			goto ErrHndlr
		end

		/* *** Jay 3.2.0 *** */
		/****** Cannot delete Record which is in use in Param  Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from vParam where vPCoCd = LocCoCd and vPTyp= 'TRDEF' and
					vPValue= LocCd)
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''TRDEF'' '
			goto ErrHndlr
		end
		/* *** Jay 3.2.0 *** */

		/**Uma EmrSv **** Cannot delete Record where LocTyp = 'R' which is in use in Loc Table ******/
		select @row=count('x') from deleted del where del.LocTyp= 'R' and
			exists (select 'x' from Loc Lc where Lc.LocCoCd= del.LocCoCd and
					Lc.LocTyp= 'P' and Lc.LocPrcs = del.LocCd)
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Process Location In Use In Loc Table'
			goto ErrHndlr
		end

		if @LocTyp= 'P'
		begin
			/****** Cannot delete Record which is in use in Head Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from Head where HCoCd= LocCoCd and HCd= @wHCd and hBOpnLoc= LocCd)
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In Head Table'
				goto ErrHndlr
			end
			/** Uma EmrSv 'P' Loc in Head Table **********/			
			select @row=count('x') from deleted del where
				exists (select 'x' from Head where HCoCd= LocCoCd and HCd= @wHCd and HDefRepBagLoc= LocCd)
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In Head Table'
				goto ErrHndlr
			end

			/* *** Jay 2.14 *** [Intoduced Company Code In Where Condition] */
			/** Uma EmrSv 'P' in SUBPRc changed to 'R' **********/
			/****** Cannot delete Record which is in use in Param ('SUBPRC') Table ******/
			/*select @row=count('x') from deleted del where LocCoCd= 'ZZZ' and 
				exists (select 'x' from Param where PTyp= 'SUBPRC' and PMCd= LocCd)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''SUBPRC'' '
				goto ErrHndlr
			end*/
			/****** Cannot delete Record which is in use in Param ('WORK') Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from vParam where vPCoCd = LocCoCd and
					vPTyp= 'WORK' and vPMCd= LocCd)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''WORK'' '
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in Param ('PRDSEQ') Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from vParam where vPCoCd= LocCoCd and vPTyp= 'PRDSEQ' and
					 charindex(','+LocCd+',', ','+vPDesc225+',')> 0)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''PRDSEQ'' '
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in Param ('WIWSEQ') Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from vParam where vPCoCd= LocCoCd and vPTyp= 'WIWSEQ' and
					charindex(','+LocCd+',', ','+vPDesc225+',')> 0)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''WIWSEQ'' '
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in Bag Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from Bag where BCoCd= LocCoCd and
						(BOpnLoc= LocCd or BLoc= LocCd))
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Bag Table'
				goto ErrHndlr
			end
			
			/*********Bhavna*****/
			/****** Cannot delete Record which is in use in DsgPrd Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from DsgPrd where DppLoc = LocCd)
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In Design Process Production Category Table'
				goto ErrHndlr
			end
	
		end
		/* ***Uma EmrSv  */
		if @LocTyp= 'R'
		begin						
			/****** Cannot delete Record which is in use in Param ('SUBPRC') Table ******/
			select @row=count('x') from deleted del where LocCoCd= 'ZZZ' and 
				exists (select 'x' from Param where PTyp= 'SUBPRC' and PMCd= LocCd)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''SUBPRC'' '
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in Param ('PRDSEQ') Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from vParam where vPCoCd= LocCoCd and vPTyp= 'PRCSSEQ' and
					 charindex(','+LocCd+',', ','+vPDesc225+',')> 0)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''PRCSSEQ'' '
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in Param ('WIWSEQ') Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from vParam where vPCoCd= LocCoCd and vPTyp= 'RWIWSEQ' and
					charindex(','+LocCd+',', ','+vPDesc225+',')> 0)
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Location In Use In Param Table Where PTyp= ''RWIWSEQ'' '
				goto ErrHndlr
			end
		end
		/* ***Uma EmrSv  */

	
		/****** Cannot delete Record which is in use in Fg Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from Fg where FgCoCd= LocCoCd and
					(FgFrRmLoc= LocCd or FgToRmLoc= LocCd or FgToBLoc= LocCd))
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Location In Use In Fg Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record which is in use in FgRm Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from FgRm where FrCoCd= LocCoCd and
					(FrFrRmLoc= LocCd or FrToRmLoc= LocCd))
		if @row>0
		Begin
			select @errmsg='Cannot Delete As Location In Use In FgRm Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record which is in use in SYyMm Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from SYyMm where SCoCd= LocCoCd and SLoc= LocCd)
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location In Use In SYyMm Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record which is in use in Txn Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from Txn where TCoCd= LocCoCd and
					(TFrRmLoc= LocCd or TToRmLoc= LocCd or TFrBLoc= LocCd))
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location In Use In Txn Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record which is in use in Txnd Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from Txnd where TdCoCd= LocCoCd and
				(TdFrBLoc= LocCd or TdToBLoc= LocCd or TdFrRmLoc= LocCd or TdToRmLoc= LocCd))
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location In Use In Txnd Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record which is in use in Fg Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from Fg where FgCoCd= LocCoCd and
				(FgFrRmLoc= LocCd or FgToRmLoc= LocCd or FgFrBLoc= LocCd or FgToBLoc= LocCd))
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location In Use In Fg Table'
			goto ErrHndlr
		end
		/****** Cannot delete Record which is in use in FgRm Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from FgRm where FrCoCd= LocCoCd and
					(FrFrRmLoc= LocCd or FrToRmLoc= LocCd))
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location In Use In FgRm Table'
			goto ErrHndlr
		end

		/***** Manali Trading Module ******/
		/****** Cannot delete Record which is in use in FgRm Table ******/
		select @row=count('x') from deleted del where
			exists (select 'x' from OrdMst where OmCoCd= LocCoCd and (OmFrRmLoc= LocCd or OmToRmLoc= LocCd))
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location In Use In OrdMst Table'
			goto ErrHndlr
		end

		/* ****** Sachin 2.14.0 28-10-2006 [Multi-Company] ****** */
		/* ****** Cannot delete Record Where Company Code is ZZZ and which has corresponding records in other companies ****** */
		Select @row=Count('x') From Deleted Del Where Del.LocPrntYN='Y' And Del.LocCoCd=@wSelfCoCd And 
			Exists (Select 'x' From Loc Lc where Lc.LocPrntYN='N' And Lc.LocPrntCd=Del.LocCd)
		If @row>0
		Begin
			Select @errmsg= 'Cannot Delete As Parent Code is being used for some Location(s)'
			Goto ErrHndlr
		End

		Select @row=Count('x') From Deleted Del Where Del.LocPrntYN='N' And Del.LocCoCd=@wSelfCoCd And 
			Exists (Select 'x' From Loc Lc where Lc.LocCoCd<>Del.LocCoCd and Lc.LocPrntYN='N' And  Lc.LocCd=Del.LocCd)
		if @row>0
		Begin
			select @errmsg= 'Cannot Delete As Location is being used in Other Companies'
			goto ErrHndlr
		end

		/* ****** Location Code If Not Exist In Any Other Company Will Be Delete From ZZZ Record ****** */
		Select @Row=Count('x') From Deleted Del Where Del.LocPrntYN='N' And Del.LocCoCd<>@wSelfCoCd
			And Not Exists (Select 'x' From Loc OthCo Where Del.LocCd=OthCo.LocCd And OthCo.LocCoCd 
						Not In (@wSelfCoCd,Del.LocCoCd))  			
		If @Row > 0
		Begin
			Delete Loc From Deleted Del, Loc DLoc Where DLoc.LocCd=Del.LocCd And DLoc.LocCoCd=@wSelfCoCd
		End
		/* ****** Sachin 2.14.0 28-10-2006 [Multi-Company] ****** */

	End
	if @SYS= 'XEMR'
	BEGIN
		if @mode = 'D'
		Begin
			/****** Cannot delete Record which is in use in xTxn Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from xTxn where xTFrRmLoc= LocCd or xTToRmLoc= LocCd )
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In xTxn Table'
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in xTxnRm Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from xTxnRm where xTrFrRmLoc= LocCd or xTrToRmLoc= LocCd )
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In xTxnRm Table'
				goto ErrHndlr
			end
			/****** Cannot delete Record which is in use in xStkYyMm Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from xStkYyMm where xSyLoc= LocCd)
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In xStkYyMm Table'
				goto ErrHndlr
			end

			/****** Cannot delete Record which is in use in xTcTyp Table ******/
			select @row=count('x') from deleted del where
				exists (select 'x' from xTcTyp where xTpFrRmLoc= LocCd or xTpToRmLoc= LocCd )
			if @row>0
			Begin
				select @errmsg= 'Cannot Delete As Location In Use In xTcTyp Table'
				goto ErrHndlr
			end
		End
	END
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

ALTER TRIGGER [dbo].[LossMst_INUPDL] ON [dbo].[LossMst] 
	    FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS 
BEGIN 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'LossMst' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ LmCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ LmCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	/******** Location Not Defined ********/
	/***uma chanegd p to R ***/
	select @row= count('x') from inserted where
		     not exists (select 'x' from Loc where LocTyp= 'R' and LocCoCd=LmCoCd and LocCd= LmLocCd)
 	if @row> 0
 	Begin
  		select @errmsg= 'Location Not Defined'
  		goto ErrHndlr
 	end
	/******  If not Blank then LmDmCtg= valid PMCd('DMCTG')******/
	select @row= count('x') from inserted where LmDmCtg<> '' and
  		not exists (select 'x' from Param where PTyp= 'DMCTG' and PMCd= LmDmCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Category Not Defined'
  		goto ErrHndlr
 	end
	/******  If LmDmCtg=''  Then  LmDmCd Should be ''  ******/
	select @row= count('x') from inserted where LmDmCtg= '' and LmDmCd<>''
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code Cannot be entered when Design Category is Blank '
  		goto ErrHndlr
 	end
	/******  If LmDmCd<>'' Then LmDmCd= valid DmCd('DM') From DsgMst******/
	select @row= count('x') from inserted where LmDmCd<> '' and
  		not exists (select 'x' from DsgMst  where DmTcTyp='DM' and DmCd=LmDmCd and DmSz='' and DmCtg=LmDmCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Not Defined for this Design category'
  		goto ErrHndlr
 	end
	/******  If LmDmCtg='' and LmDmcd='' Then  LmWorkcd Should be Blank  ******/
	select @row= count('x') from inserted where  LmDmCd='' and LmWorkCd<>''
 	if @row> 0
 	Begin
  		select @errmsg= 'Worker Cannot be entered  when Design Category,Design is Blank '
  		goto ErrHndlr
 	end
	/******  If LmWorkCd<>'' Then LmWorkCd= valid vPMCd(LmCoCd,'WORK')******/
	select @row= count('x') from inserted where LmWorkCd<> '' and
  		not exists (select 'x' from vParam where vPTyp='WORK' and vPCoCd=LmCoCd and
				  vPMCd=LmWorkCd and vPSCd='')
 	if @row> 0
 	Begin
  		select @errmsg= 'Worker  Not Defined'
  		goto ErrHndlr
 	end
	/******  If Should be LmLossPer>0******/
	select @row= count('x') from inserted where LmLossPer<=0
 	if @row> 0
 	Begin
  		select @errmsg= 'Permitted Loss Percentage Cannot be <=0'
  		goto ErrHndlr
 	end
return
ErrHndlr:
	begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	end
end
GOGO
ALTER TRIGGER [dbo].[OrdDsg_INUPDL] ON [dbo].[OrdDsg]     
   FOR INSERT,UPDATE,DELETE     NOT FOR REPLICATION
As    
BEGIN    
 /* Trigger Version 3.9.1  */    
 DECLARE @ROW INT    
 DECLARE @mode char(1)    
 DECLARE @errmsg varchar(255)    
 Declare @wSelf VarChar(8)    
 Declare @wSysDb Varchar(3)    
 DECLARE @ReplAgt BIT    
 DECLARE @wCurrPrtn VarChar(1)    
 /*** Jay 3.3(FG) ***/  
 Declare @wInFob Float  
 Declare @wInFobRs Float  
 Declare @wInLclOctroiRs Float  
 Declare @wInLclVatRs Float  
 Declare @wInLclCstRs Float  
 /*** Jay 3.3(FG) ***/     
 /*** Manali - UniDesign ****/  
 DECLARE @wTcTyp varchar(3)   
 declare @wIsJLTc char(1)
 /*** Manali - UniDesign ****/  
   
 IF @@ROWCOUNT=0   RETURN    
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'OrdDsg' )    
  RETURN    
    
 select @mode= case (select count('x') from inserted) when 0 then 'D'    
        else    
    case (select count('x') from deleted) when 0 then 'A' else 'C' end    
        end     
    
 Select @wSysDb=SysDb From SysDb where SysId='CRM'     
 Select @wCurrPrtn = 'C'       
 Set @wSysDb=IsNull(@wSysDb,'')     
    
 /* **** Checking Whether a Normal Transaction or Replicated One **** */    
 Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))    
 If @ReplAgt = 1         Return
 

Select @wSelf='ZSELF'     
    
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */    
 if @mode='C' And @ReplAgt<>1   
 Begin    
  Select @row=count('x') From Inserted Where OdPrtKey<>@wCurrPrtn    
    if @row> 0     
  Begin    
     select @errmsg= 'Cannot Edit Records of Previous Partition'    
     goto ErrHndlr    
  End   
  
  Select @row=count('x') From Deleted del  
      Where (Select PValue From Param Where PTyp='TCTYP' and PMCd=del.OdTc)<>'PL' and   
        Exists(Select 'x' From Inserted ins Where ins.OdIdNo=del.OdIdNo and ins.OdCoCd=del.OdCoCd   
            and ins.OdTc=del.OdTc and ins.OdYy=del.OdYy and ins.OdChr=del.OdChr   
            and ins.OdNo=del.OdNo and ins.OdSr=del.OdSr and ins.OdPrtKey<>del.OdPrtKey)   
  if @row> 0   
  begin  
   select @errmsg= 'Cannot Edit Partition Key Field'  
   goto ErrHndlr  
  end  
   
 End    
   
 /**** Manali - (UniDesign Prob) ****/  
 /******** Only One TcTyp records can be Inserted at a time.********/  
 /* Current Partition */   
 select @Row= Count(distinct(PValue)) from inserted Join param On  
  PTyp= 'TC' and PMCd= OdTc and PScd= '' Where OdPrtKey=@wCurrPrtn   
 If @Row> 1  
 begin  
  Select @ErrMsg= 'Transactions of only One TcType can be Acted On'  
  GoTo ErrHndlr  
 end  
  
 /**** Manali - (UniDesign Prob) ****/  
 /******** Only One TcTyp records can be Deleted at a time. *********/  
 /* Current Partition */  
 select @Row= Count(distinct(PValue)) from deleted Join param on  
  PTyp= 'TC' and PMcd= OdTc and PSCd='' Where OdPrtKey=@wCurrPrtn  
 If @Row> 1  
 begin  
  Select @ErrMsg= 'Transactions of only One TcType can be Acted on'  
  GoTo ErrHndlr  
 end  
  
 /*** Manali 3.8.2 Storing Tc Type In The Variable @wTcTyp ***/  
 if @mode in ('A','C')  
 begin  
  select @wTcTyp= max(PValue),@wIsJLTc = max(PValue1) from inserted join Param on PTyp= 'TC' and PMCd= OdTc and PSCd= ''  
  if @wTcTyp = '' select @wTcTyp = 'N'
 end  
  
 if @mode in ('D')  
 begin  
  select @wTcTyp=max(PValue), @wIsJLTc = max(PValue1) from deleted join Param on PTyp= 'TC' and PMCd= OdTc and PSCd= ''   
 end  
  
   
 if @mode='A'  And @ReplAgt<>1    
 Begin    
  Select @row=count('x') From Inserted Where OdPrtKey <> @wCurrPrtn     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''    
   goto ErrHndlr    
  end    
 end     
    
 If @Mode='D'  And @ReplAgt<>1    
 Begin     
  select @row= count('x') from deleted del where del.OdPrtKey<>@wCurrPrtn    
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Delete Records From Previous Partition'    
   goto ErrHndlr    
  end    
 End    
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */    
    
    If (@ReplAgt<>1)    
  Begin    
   /*db='WEB' then cannot  Insert /Update/Delete  where OmChr<> 'WEB'     
   Cannot edit/Delete where OmSubmitYN=’Y’ i.e Check deleted.OmSubmitYN=’Y’      
   Cannot edit OmAckYN      
   */    
  /*******No Need to Check  Sysdb='' beceuse Chr='WEB' insert is not allowed in vParam where not exists SysId='CRM'*************************/    
  If @Mode in ('A','C' )     
  Begin      
   /******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/    
   /***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/    
   Select @ROW =Count('x')  From inserted where      
   Exists (Select 'x' From SysDb where (SysId='EMR' and ',' + SdCoCd + ',' Not  like '%,'+ OdCoCd +',%'))    
   If @Row > 0      
   Begin     
    select @errmsg= 'Cannot Insert /Update '     
    goto ErrHndlr     
   end     
       
   /*****If  db= '-' then Insert  Not allowed in OrdDsg  for OmChr='WEB' if OmAckYN<>'Y' ******/    
   /* Current Partition */    
   Select @Row= Count('x') From Inserted where OdPrtKey=@wCurrPrtn and OdChr= 'WEB' and @wSysDb= '-' and     
    (Select OmAckYN From OrdMst where OmIdNo=OdOmIdNo and OmCoCd=OdCoCd and OmTc=OdTc and OmYy=OdYy and OmChr=OdChr and OmNo=OdNo and OmPrtKey=OdPrtKey)= 'N'      
   If @Row> 0    
   Begin      
    select @errmsg= 'Cannot Insert/Update Order Design of an UnAcknowledged Web Orders'      
    goto ErrHndlr      
   end      
     
   /*****If  db= 'WEB' then Insert/Update  Not allowed in OrdMst  for OdChr<>'WEB'/OdChr='WEB' and OmSubmitYN='Y' ******/    
   /* Current Partition */    
   Select @Row= Count('x') From Inserted where OdPrtKey=@wCurrPrtn and @wSysDb= 'WEB' and     
    (OdChr<> 'WEB' Or (OdChr= 'WEB' and (Select OmSubmitYN From OrdMst where OmIdNo=OdOmIdNo and OmCoCd=OdCoCd and OmTc=OdTc and     
        OmYy=OdYy and OmChr=OdChr and OmNo=OdNo and OmPrtKey=OdPrtKey)= 'Y'))     
   If @Row> 0    
   Begin      
    select @errmsg= 'Cannot Insert/Update Orders Other than Chr=''WEB'' and Submitted=''N'' '      
    goto ErrHndlr   
   End      
 /*** Jay 3.3(FG) ***/  
 select @Row= Count('x') from inserted join InvHd on InCoCd= OdCoCd and InTc= OdTc and   
   InYy= OdYy and InChr= OdChr and InNo= OdNo where InCls= 'Y' and OdTc='FOT'  
 If @Row > 0  
 begin   
  Select @ErrMsg= 'Cannot Add/Change As Invoice Is Closed'  
  GoTo ErrHndlr  
 end     
 End    
 Select @Row= Count('x') from deleted where OdTc = 'JRI' and exists 
 (Select 'a' from Txnd where TdCoCd = OdCoCd and TdBYy = OdDmStkYy and TdBChr = OdDmStkChr and TdBNo = OdDmStkNo and (Txnd.ModDt > deleted.ModDt or (Txnd.ModDt = deleted.ModDt and Txnd.ModTime > Deleted.ModTime)))
 If @Row > 0  
 begin   
  Select @ErrMsg= 'Cannot Modify/Delete As Bag Transactions exists for Repair Bag'  
  GoTo ErrHndlr  
 end

     
  If @Mode ='D'     
  Begin    
   /* Current Partition */    
   select @ROW =Count('x')  From Deleted where  OdPrtKey=@wCurrPrtn and    
    Exists (select 'x' From SysDb where (SysId='EMR' and ',' + SdCoCd + ',' Not like '%,'+ OdCoCd +',%'))    
   if @Row > 0      
   Begin     
    select @errmsg= 'Cannot Delete '     
    goto ErrHndlr     
   end     
    
   /*****If  db= '-' then Insert  Not allowed in OrdDsg  for OmChr='WEB' if OmAckYN<>'Y' ******/    
   /* Current Partition */    
   Select @Row=Count('x') From Deleted where OdPrtKey=@wCurrPrtn and OdChr='WEB' and     
   (Select OmAckYN From OrdMst where OmIdNo=OdOmIdNo and OmCoCd=OdCoCd and OmTc=OdTc and OmYy=OdYy and OmChr=OdChr and OmNo=OdNo and OmPrtKey=OdPrtKey)='N'    
    and @wSysDb='-'    
   If @Row> 0    
   Begin      
    select @errmsg= 'Cannot Delete Order Design of an UnAcknowledged Web Orders'      
    goto ErrHndlr      
   end      
     
   /*****If  db= 'WEB' then Insert/Update  Not allowed in OrdMst  for OdChr<>'WEB'/OdChr='WEB' and OmSubmitYN='Y' ******/    
   /* Current Partition */    
   Select @Row=Count('x') From Deleted where OdPrtKey=@wCurrPrtn and @wSysDb='WEB' and     
   (OdChr<>'WEB' Or (OdChr='WEB' and (Select OmSubmitYN From OrdMst where OmIdNo=OdOmIdNo and OmCoCd=OdCoCd and OmTc=OdTc and     
        OmYy=OdYy and OmChr=OdChr and OmNo=OdNo and OmPrtKey=OdPrtKey)='Y'))     
   If @Row> 0    
   Begin      
    select @errmsg= 'Cannot Delete Ord Designs from Orders Other than Chr=''WEB'' and Submitted=''N'' '      
    goto ErrHndlr      
   end      
    /*** Jay 3.3(FG) ***/  
 select @Row= Count('x') from deleted join InvHd on InCoCd= OdCoCd and InTc= OdTc and   
   InYy= OdYy and InChr= OdChr and InNo= OdNo where InCls= 'Y' and OdTc='FOT'  
 If @Row > 0  
 begin   
  Select @ErrMsg= 'Cannot Delete As Invoice Is Closed'  
  GoTo ErrHndlr  
 end


 
   /****** Whenever the OrdDsg record is deleted, delete records from the child tables (OrdRm, OrdLab, OrdAmd, OrdTgt) ******/    
   /* *** Jay 2.13(CT) ***  OrdCT Table Added */    
   /* Sachin 3.02 - Current Partition - Id Nos added */    
   Delete OrdRm From deleted, OrdRm where OdIdNo=OrOdIdNo and OdCoCd = OrCoCd and OdTc = OrTc and     
    OdYy = OrYy and OdChr = OrChr and OdNo = OrNo and OdSr= OrSr and OdPrtKey=OrPrtKey    
     
   Delete OrdLab From deleted, OrdLab where OdIdNo=OlOdIdNo and OdCoCd = OlCoCd and OdTc = OlTc and     
    OdYy = OlYy and OdChr = OlChr and OdNo = OlNo and OdSr= OlSr and OdPrtKey=OlPrtKey    
     
   Delete OrdAmd From deleted, OrdAmd where OdIdNo=OaOdIdNo and OdCoCd = OaCoCd and OdTc = OaTc and     
    OdYy = OaYy and OdChr = OaChr and OdNo = OaNo and OdSr= OaSr and OdPrtKey=OaPrtKey    
     
   Delete OrdTgt From deleted, OrdTgt where OdCoCd = OtCoCd and OdTc = OtTc and     
    OdYy = OtYy and OdChr = OtChr and OdNo = OtNo and OdSr = OtSr and OdPrtKey=OtPrtKey    
     
   Delete OrdPln From deleted, OrdPln where OdCoCd = OpCoCd and OdTc = OpTc and     
    OdYy = OpYy and OdChr = OpChr and OdNo = OpNo and OdSr = OpSr     
    
   Delete OrdCT From deleted, OrdCT where OdIdNo=OctOdIdNo and OdCoCd = OctCoCd and OdTc = OctTc and     
    OdYy = OctYy and OdChr = OctChr and OdNo = OctNo and OdSr = OctSr and OdPrtKey=OctPrtKey    
    End      
 End    
    
/* If Not Exists(Select 'x' From Inserted Join Head On OdCoCd=HCoCd )    
   and  Not Exists(Select 'x' From deleted Join Head On OdCoCd=HCoCd )     
 Return    
*/    
  /******** Key Cannot Be Changed ********/     
  if @mode = 'C'    
  Begin      
  /*** (should thi check be kept??? was there in 2.13)    
   ******** Key Cannot Be Changed when bag exist ********     
  select @Row= Count('x') from deleted del where     
    exists(Select 'x' from Bag where BCoCd= del.OdCoCd and BOdTc= del.OdTc     
    and BOdYy= del.OdYy and BOdChr= del.OdChr and BOdNo= del.OdNo and BOdSr= del.OdSr)     
  If @Row > 0    
  begin     
   Select @ErrMsg= 'Cannot Change Key As Bag exists.'    
   GoTo ErrHndlr     
  end    
  ***/    
    
  /* Prt Key Not Required - Id No added */    
  select @Row= Count('x') from deleted del where     
    not exists (Select 'x' from inserted ins where ins.OdIdNo=del.OdIdNo and ins.OdCoCd= del.OdCoCd     
    and ins.OdTc= del.OdTc and ins.OdYy= del.OdYy and ins.OdChr= del.OdChr     
    and ins.OdNo= del.OdNo and ins.OdSr= del.OdSr)    
  If @Row > 0    
  begin     
   Select @ErrMsg= 'Cannot Change Company Code/Tc/Yy/Chr/No/Sr'    
   GoTo ErrHndlr    
  end    
  /*********************Geeta***************Emr206************************/    
  /*********************On Hold can be changed ***************************/    
  /****** Cannot change On Hold option if Order= Export Order Of Fgd Table  ******/    
/*  select @row= count('x') from deleted del where     
   not exists (select 'x' from inserted ins where ins.OdCoCd= del.OdCoCd and     
     ins.OdTc= del.OdTc and ins.OdYy= del.OdYy and ins.OdChr= del.OdChr and    
     ins.OdNo= del.OdNo and ins.OdSr= del.OdSr and ins.OdHld= del.OdHld) and     
   exists(Select 'x' from Fgd where FdCoCd= del.OdCoCd and FdExpOdTc= del.OdTc and     
    FdExpOdYy = del.OdYy and FdExpOdChr = del.OdChr and FdExpOdNo = del.OdNo and     
    FdExpOdSr = del.OdSr)    
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Change On Hold Option As Export Order Exists In Fgd Table'    
   goto ErrHndlr    
  end   */    
    
  /*** (Jen 2.14 Next) ***/    
  /****** Cannot change On Hold option to 'Y' if rec exists in InvFgd Table  ******/    
  /* Complete Database  ****Geeta */    
  /****** Manali 3.9.1 - Check skipped for CTB *****/  
  select @row= count('x') from inserted ins where ins.OdHld= 'Y'     
   and (ins.OdPrtFGQty<>0 or exists(Select 'x' from Fgd     
    join InvFgd on IfPrtKey=FdPrtKey and IfFdIdNo=FdIdNo and IfCoCd= FdCoCd and IfFdTc= FdTc   
    and IfFdYy= FdYy and IfFdChr= FdChr and IfFdNo= FdNo and IfFdSr= FdSr    
    and (Select PValue From Param Where PTyp='TC' and PMCd=IfTc)='IN'  
    where FdCoCd= ins.OdCoCd and FdExpOdTc= ins.OdTc and FdExpOdYy = ins.OdYy     
    and FdExpOdChr = ins.OdChr and FdExpOdNo = ins.OdNo and FdExpOdSr = ins.OdSr))    
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Change On Hold Option To ''Y'' As Bag Exists For The Export Order In InvFgd Table'    
   goto ErrHndlr    
  end       
  /*** (Jen 2.14 Next) ***/    
    
    
  /* Geeta CRM Emr 213 @wPkChg=0 added */     
  /****** Cannot Change OdDmCol code when bag exists For Ord Design ******/    
  /* Current Partition */    
  select @row= count('x') from deleted del where del.OdPrtKey=@wCurrPrtn and    
   not exists(Select 'x' from inserted ins where ins.OdIdNo=del.OdIdNo and ins.OdCoCd= del.OdCoCd     
    and ins.OdTc= del.OdTc and ins.OdYy= del.OdYy     
    and ins.OdChr= del.OdChr and ins.OdNo= del.OdNo     
    and ins.OdSr= del.OdSr and ins.OdDmCol= del.OdDmCol)     
   and (OdPrtFgQty >0 or exists(Select 'x' from Bag where BOdIdNo=OdIdNo and BCoCd= OdCoCd     
    and BOdTc= del.OdTc and BOdYy= del.OdYy     
    and BOdChr= del.OdChr and BOdNo= del.OdNo     
    and BOdSr= del.OdSr and BPrtKey=del.OdPrtKey))     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Change Design Color As Bag Exists'    
   goto ErrHndlr    
  end    
  
  
 /****** Zubin 3.02.01 (270308) OdChgPtrOnStwYN =  PMCd ('YN')  ******/  
 /* Current Partition */  
 select @row= count('x') from inserted where OdPrtKey=@wCurrPrtn and   
  not exists (select 'x' from Param where PTyp= 'YN' and PMCd= OdChgPtrOnStwYN and PSCd= '')  
 if @row> 0     
 begin  
  select @errmsg= 'Change Pointer On STW (Y/N)'  
  goto ErrHndlr  
 end   
  
 /****** Zubin 3.02.01 (270308) OdChgPtrOnStwYN cannot be changed when OrdRm exists ******/  
 select @row= count('x') from deleted del where del.OdPrtKey=@wCurrPrtn and    
  not exists(Select 'x' from inserted ins where ins.OdIdNo=del.OdIdNo and ins.OdCoCd= del.OdCoCd     
   and ins.OdTc= del.OdTc and ins.OdYy= del.OdYy and ins.OdChr= del.OdChr and ins.OdNo= del.OdNo     
   and ins.OdSr= del.OdSr and ins.OdChgPtrOnStwYN= del.OdChgPtrOnStwYN)     
  and exists(Select 'x' from OrdRm where OdPrtKey=OrPrtKey and OdIdNo=OrOdIdNo and OdCoCd= OrCoCd   
   and OdTc= OrTc and OdYy= OrYy and OdChr= OrChr and OdNo= OrNo and OdSr= OrSr)    
 if @row> 0     
 begin    
  Select @ErrMsg= 'Cannot Change ''Change Pointer On STW (Y/N)'' When Rm Exists'  
  goto ErrHndlr    
 end    
  
 /****** Zubin 3.02.01 (270308) OdILabWtFrOrd =  PMCd ('YN')  ******/  
 select @row= count('x') from inserted where OdPrtKey=@wCurrPrtn and  
  not exists (select 'x' from Param where PTyp= 'YN' and PMCd= OdILabWtFrOrd and PSCd= '')  
 if @row> 0     
 begin  
  select @errmsg= 'Labor Weight From Order (Y/N)'  
  goto ErrHndlr  
 end   
   
 /*** Jay 3.3(FG) - dmid/ sfx cannot change for 'FG' tctyp ***/  
 select @row= count('x') from deleted del where del.OdPrtKey=@wCurrPrtn and    
  not exists(Select 'x' from inserted ins where ins.OdIdNo=del.OdIdNo and ins.OdCoCd= del.OdCoCd     
   and ins.OdTc= del.OdTc and ins.OdYy= del.OdYy and ins.OdChr= del.OdChr and ins.OdNo= del.OdNo     
   and ins.OdSr= del.OdSr and (ins.OdDmStkNo= del.OdDmStkNo or ins.OdSfx= del.OdSfx ))  
  and exists (Select 'x' from Param where Ptyp = 'TC' and PValue= 'FG' and PMCd= del.OdTc)  
 if @row> 0     
 begin    
  Select @ErrMsg= 'Cannot Change DmId/ Suffix'  
  goto ErrHndlr    
 end   
  
 /* *** manali 3.5.0 Diamond tolerance at Order Level *** */  
 Select @row=count('x') from inserted Where OdPrtKey=@wCurrPrtn and OdMinDiaTolWt > OdMaxDiaTolWt  
 If @row > 0  
 Begin  
  Select @Errmsg='Minimunm Diamond Tolerance cannot be Greater Than Maximum Diamond Tolerance'  
  Goto ErrHndlr  
 end   
    
  /****** Cannot Change OdOmCtCd code when bag exists For Ord Design ******/    
/*  ################### Check Remove Now onwards     
  Contractor cn be changed any Time in Order Master.    
 select @row= count('x') from deleted del where     
   not exists(Select 'x' from inserted ins where ins.OdCoCd= del.OdCoCd     
    and ins.OdTc= del.OdTc and ins.OdYy= del.OdYy     
    and ins.OdChr= del.OdChr and ins.OdNo= del.OdNo     
    and ins.OdSr= del.OdSr and ins.OdOmCtCd= del.OdOmCtCd)     
   and exists(Select 'x' from Bag where BCoCd= OdCoCd     
    and BOdTc= del.OdTc and BOdYy= del.OdYy     
    and BOdChr= del.OdChr and BOdNo= del.OdNo     
    and BOdSr= del.OdSr)     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Change Contractor Cd As Bag Exists'    
   goto ErrHndlr    
  end    
*/    
    
  /*** Jen Try 25/06/07 ***/    
  /*** OdOrdQty Cannot Be Changed when OdCls= 'Y' ***/    
  /* Select @row= count('x') from inserted where     
   OdCls= 'Y' and convert (decimal (14, 1), OdOrdQty)<> convert (decimal (14, 1), OdExpQty)     
  if @row> 0     
  Begin    
   select @errmsg= 'Order Quantity Cannot Be Changed When Order Is Closed.'     
   goto ErrHndlr    
  end    
  */     
  /*** Jen Try 25/06/07 ***/    
    
 End    
    
  if @mode = 'A'     
  Begin    
/* **** Zubin 211 TCTYP= 'QF' added **** */     
  /****** Check for valid Design or whether the Design is on hold for Order Tc Types 'SO', 'PL', 'QT', 'QF' ******/    
  /* Current Partition */    
 /***** Manali Trading Module - 'JT' added *****/  
  -- 4.1.3.0 - DmValid  
  select @row= count('x') from inserted     
    Join OrdMst On OmIdNo=OdOmIdNo and OmCoCd=OdCoCd And OmTc=OdTc And OmYy=OdYy And OmChr=OdChr And OmNo=OdNo and OmPrtKey=OdPrtKey    
    where OdPrtKey=@wCurrPrtn and OmReYy= '' And OmReChr= '' And OmReNo=0 And @wIsJLTc = 'N' and
    (Select PValue from Param where PTyp= 'TC' and PMCd= OdTc) in ('PL', 'QT', 'SO', 'QB', 'JT') and     
    not exists (select 'x' from DsgMst where DmIdNo=OdDmIdNo and DmTcTyp= 'DM'     
        and DmHld= 'N' And DmValidYn='Y' and DmCd= OdDmCd and DmSz= ''  and DmPrtKey=OdPrtKey)    
  if @row> 0     
  begin    
   select @errmsg= 'Design Code Not Defined Or Is On Hold'    
   goto ErrHndlr    
  end    
    
  /* Current Partition */    
  /***** Manali Trading Module - 'JT' added *****/  
  -- 4.1.3.0 - DmValid  
  select @row= count('x') from inserted     
    Join OrdMst On OmIdNo=OdOmIdNo and OmCoCd=OdCoCd And OmTc=OdTc And OmYy=OdYy And OmChr=OdChr And OmNo=OdNo and OmPrtKey=OdPrtKey    
   where OdPrtKey=@wCurrPrtn and OmReYy= '' And OmReChr= '' And OmReNo=0 And  @wIsJLTc = 'N' and    
    (Select PValue from Param where PTyp= 'TC' and PMCd= OdTc) in ('PL', 'QT', 'SO', 'QB', 'JT') and     
	(Select TcMst.TmJLooseTC from TcMst where TmTc = OdTc and tmcocd = OdCoCd)='N' and
    Exists (select 'x' from DsgMst where DmIdNo=OdDmIdNo and DmTcTyp= 'DM'     
     and (DmHld= 'Y' Or DmValidYn='N') and DmCd= OdDmCd and DmSz= OdDmSz and DmPrtKey=OdPrtKey)    
  if @row> 0     
  begin    
