			if @PTyp= 'PRTCD' 
			Begin 
				/****** Cannot delete Priority Code in use in xTxn table ******/
				select @row=count('x') from deleted del where 
					exists (select 'x' from xTxn  where xTPrtCd= PMCd)
				if @row>0 
				Begin
					select @errmsg='Cannot Delete As Priority Code In Use In xTxn Table'
					goto ErrHndlr
				end
				/****** Cannot delete Priority Code in use in xTxnDsg table ******/				select @row=count('x') from deleted del where 
				exists (select 'x' from xTxnDsg where xTdPrtCd= PMCd)
				if @row>0 
				Begin
					select @errmsg='Cannot Delete As Priority Code In Use In xTxnDsg Table'
					goto ErrHndlr
				end
			End

			if @PTyp= 'YY' 
			Begin 
				/****** Cannot delete Year in use in xTxn table ******/
				select @row=count('x') from deleted del where 
					exists (select 'x' from xTxn where xTYy= PMCd)
				if @row>0 
				Begin
					select @errmsg= 'Cannot Delete As Year In Use In xTxn Table'
					goto ErrHndlr
				end
				/****** Cannot delete Year in use in xTxnDsg table ******/
				select @row=count('x') from deleted del where 
					exists (select 'x' from xTxnDsg where xTdIdYy= PMCd)
				if @row>0 
				Begin
					select @errmsg= 'Cannot Delete As Year As A Part Of Id In Use In xTxnDsg Table'
					goto ErrHndlr
				end
			
				/****** Cannot delete Year in use in xIdMst table ******/
				select @row= count('x') from deleted del where 
					exists (select 'x' from xIdMst where xImIdYy= PMCd)
				if @row> 0 
				Begin
					select @errmsg= 'Cannot Delete As Year As A Part Of Id In Use In xIdMst Table'
					goto ErrHndlr
				end
			End
		END	

	END



return
ErrHndlr:
begin
	select @errmsg='|'+@errmsg
	raiserror(@errmsg,16,1)
	rollback transaction 
		end
end


GOGO

ALTER TRIGGER [dbo].[PrdPts_INUPDL] ON [dbo].[PrdPts]
 FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
 	DECLARE @ROW INT
 	DECLARE @mode char(1)
 	DECLARE @errmsg varchar(255)
	Declare @ReplAgt BIT

 	IF @@ROWCOUNT=0
  	RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'PrdPts' )
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
       		           else
   			  case (select count('x') from deleted) when 0 then 'A' else 'C' end
       		           end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	If  (@ReplAgt<>1)
	Begin

		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

 	/******** Records Of Only One Typ Can Be Inserted At A Time ********/
	select @Row= Count(distinct(PpTyp)) from inserted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Prd Pts Records Of Only One Type Can Be Acted On At A Time'
		GoTo ErrHndlr
	End

	/******** Records Of Only One Typ Can Be Deleted At A Time ********/
	select @Row= Count(distinct(PpTyp)) from deleted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Prd Pts Records Of Only One Type Can Be Acted On At A Time'
		GoTo ErrHndlr
	End

	/******** Prd Typ Not Defined ********/
    --3.11.0
	select @row= count('x') from inserted where PpTyp<>'BL' And
		     not exists (select 'x' from Param where PTyp= 'PRDTYP' and PMCd =PpTyp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Prd Type Not Defined'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpPrdCtg= valid PMCd('PRDCTG')  ******/
	select @row= count('x') from inserted where PpTyp<>'BL' And PpPrdCtg<> '' and 
  		not exists (select 'x' from Param where PTyp= 'PRDCTG' and PMCd= PpPrdCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Production Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpTyp='BL' And PpPrdCtg= valid PMCd('DMCTG')  ******/
	select @row= count('x') from inserted where PpTyp='BL' And PpPrdCtg<> '' and 
  		not exists (select 'x' from Param where PTyp= 'DMCTG' and PMCd= PpPrdCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpPrdCtg') = 'N' then PpPrdCtg = Not Blank ******/
	select @row= count('x') from inserted where PpPrdCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		    and TsIdName= 'PpPrdCtg') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Production Category Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpSetTyp= valid PSCd('LABSCD', 'SET')  ******/
	select @row= count('x') from inserted where PpSetTyp<> '' and 
  		not exists (select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= PpSetTyp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Setting Type Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpSetTyp') = 'N' then PpSetTyp = Not Blank ******/
	select @row= count('x') from inserted where PpSetTyp= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpSetTyp') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Setting Type Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpDmCd= valid DmCd('DM')  ******/
	select @row= count('x') from inserted where PpDmCd<> '' and 
  		not exists (select 'x' from DsgMst where DmTcTyp= 'DM' and DmCd= PpDmCd and DmSz= ''
						 and ((Case When PpTyp='BL' Then DmCtg Else DmPrdCtg End)= PpPrdCtg or 
						 PpTyp='GS' or PpTyp = 'WS'))
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code Not Defined/ Ctg Not Matching'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpDmCd') = 'N' then PpDmCd = Not Blank ******/
	select @row= count('x') from inserted where PpDmCd= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpDmCd') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpLoc= valid Loc(LocTyp= 'P')  ******/
	/****uma P replaced by R ****/
	select @row= count('x') from inserted where PpLoc<> '' and 
	  		not exists (select 'x' from Loc where LocTyp= 'R' and LocCd= PpLoc)
 	if @row> 0
 	Begin
  		select @errmsg= 'Process Location Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpLoc') = 'N' then PpLoc = Not Blank ******/
	select @row= count('x') from inserted where PpLoc= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
		and TsIdName= 'PpLoc') = 'N'
 	if @row> 0
 	Begin
		select @errmsg= 'Process Location Cannot Be Blank'
		goto ErrHndlr
 	end

	/******  If not Blank then PpSubPrc= valid PSCd('SUBPRC', PpLoc)  ******/
	select @row= count('x') from inserted where PpSubPrc<> '' and 
  		not exists (select 'x' from Param where PTyp= 'SUBPRC' and PMCd= PpLoc and PSCd= PpSubPrc)
 	if @row> 0
 	Begin
  		select @errmsg= 'Sub Process Not Defined For The Process Location'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpSubPrc') = 'N' then PpSubPrc = Not Blank ******/
	select @row= count('x') from inserted where PpSubPrc= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpSubPrc') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Sub Process Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpPts') = 'N' then PpPts = Not Blank ******/
	select @row= count('x') from inserted where PpPts= 0 and 
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpPts') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Production Points Should Be Greater Than Zero'
  		goto ErrHndlr
 	end

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date: 03/12/2003																			 */
/*	Cnange:	Check Adeed For fields RmCtg & RmSCtg  (New Added in Table PrdPts)					 */

	/******  If not Blank then PpRmCtg= valid Rm Category (PTyp= 'RMCTG')  ******/
	select @row= count('x') from inserted where PpRmCtg<> '' and
	  		not exists (select 'x' from Param where PTyp= 'RMCTG' and PMCd= PpRmCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Rm Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpRmCtg') = 'N' then PpRmCtg = Not Blank ******/
	select @row= count('x') from inserted where PpRmCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= ''
		and TsIdName= 'PpRmCtg') = 'N'
 	if @row> 0
 	Begin
		select @errmsg= 'Rm Category Cannot Be Blank'
		goto ErrHndlr
 	end

	/******  If not Blank then PpRmCtg= valid Rm Category (PTyp= 'RMCTG')  ******/
	select @row= count('x') from inserted where PpRmSCtg<> '' and
	  		not exists (select 'x' from Param where PTyp= 'RMSCTG' and PMCd= PpRmCtg And PSCD = PpRmSCtg )
 	if @row> 0
 	Begin
  		select @errmsg= 'Rm Sub Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpRmCtg') = 'N' then PpRmCtg = Not Blank ******/
	select @row= count('x') from inserted where PpRmSCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= ''
		and TsIdName= 'PpRmSCtg') = 'N'
 	if @row> 0
 	Begin
		select @errmsg= 'Rm Sub Category Cannot Be Blank'
		goto ErrHndlr
 	end

	Select @row = Count('x') From Inserted ins 
	Where  
	(Select count('x') From PrdPts Pp
		Where Pp.PpTyp=Ins.PpTyp And Pp.PpLoc=Ins.PpLoc And Pp.PpSubPrc=Ins.PpSubPrc And Pp.PpPrdCtg=Ins.PpPrdCtg
			And Pp.PpSetTyp=Ins.PpSetTyp And Pp.PpDmCd=Ins.PpDmCd And Pp.PpRmCtg=Ins.PpRmCtg And Pp.PpRmSCtg=Ins.PpRmSCtg 
   			and  (    (Pp.PpFrRmWt<= ins.PpFrRmWt and
      				 Pp.PpToRmWt>= ins.PpFrRmWt)
			    or  	(Pp.PpFrRmWt<= ins.PpToRmWt and
			      	 Pp.PpToRmWt>= ins.PpToRmWt)
    			    or  	(ins.PpFrRmWt<= Pp.PpFrRmWt and
				 ins.PpToRmWt>= Pp.PpToRmWt) 	 )) > 1
	if @row> 0
 	Begin
  		select @errmsg= 'Weight Range Already Defined'
  		goto ErrHndlr
 	End  

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */

Return
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	end
end




GOGO
ALTER TRIGGER [dbo].[Txn_INUPDL] ON [dbo].[Txn] 
	   FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
	BEGIN
	/* Trigger Version 3.10.0  */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wTcTyp varchar(3)
	DECLARE @wEntTyp varchar(8)
	Declare @wHCd Varchar(8) 
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
		
	IF @@ROWCOUNT=0   RETURN
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Txn' )
	RETURN
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'
	else
		case (select count('x') from deleted) when 0 then 'A' else 'C' end
	end

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	 If @ReplAgt = 1         Return
      

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins Where ins.TIdNo=del.TIdNo and ins.TCoCd=del.TCoCd and ins.TTc=del.TTc and
									ins.TYy=del.TYy and ins.TChr=del.TChr and ins.TNo=del.TNo and ins.TPrtKey<>del.TPrtKey) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end

	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where TPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TCoCd +',%')) 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where TPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Partition Key Not required */
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= TTc and PScd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time. *********/
	/* Partition Key Not Required */
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd=TTc and PSCd=''
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted on'
		GoTo ErrHndlr
	END

	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp=max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= TTc and PSCd=''
	end

	if @mode in ('D')
	Begin
		select @wTcTyp=max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= TTc and PSCd=''
	end

	/*** Storing Entry Type In The Variable @wEntTyp ***/
	select @wEntTyp= PValue1 from Param  where PTyp= 'TCTYP' and PMCd=@wTcTyp and PSCd=''

	if @mode in ('A','C')
	Begin
		/*** Transactions Of Only 'TxnBag' and 'TxnRm' Type Permitted ***/
		/* Current Partition */
		select @row= count('x') from inserted where TPrtKey=@wCurrPrtn and not exists 
			(select 'x' from Param where PTyp= 'TC' and PMCd= TTc and 
				PValue in (Select PMCd from Param where PTyp= 'TCTYP' 
						and PValue1 in('TXNBAG', 'TXNRM', 'TZ'))
				   	   )
		if @row> 0 
		begin
   			select @errmsg= 'Transactions Of Only ''Txn''/ ''Tz'' Types Permitted'
			goto ErrHndlr
		end

		/******  TCoCd = HCoCd   *******/
		/* Current Partition */
		select @row=count('x') from inserted where TPrtKey=@wCurrPrtn and 
					not exists (select 'x' from Head where HCoCd= TCoCd and HCd= @wHCd)
		if @row>0 
		begin 
			select @errMsg= 'Company Code Not Valid'
			goto ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where TPrtKey=@wCurrPrtn and not exists 
			(select 'x' from Param where PTyp='YY' and PMCd= TYy)
		if @row> 0 
		begin
			select @errmsg= 'Voucher Year Not Defined'
			goto ErrHndlr
		end

		/*****4.1.2********/	
		Select @Row=Count('x') From Inserted ins where 
			(Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=TCoCd)='Y' and
			(@Mode='A' or (@Mode='C' and  ins.TDt<>IsNull((Select TDt From Deleted del where 
									ins.TPrtKey=del.TPrtKey and ins.TIdNo=del.TIdNo 
									and ins.TCoCd= del.TCoCd and ins.TTc= del.TTc and ins.TYy= del.TYy 
										and ins.TChr= del.TChr and ins.TNo= del.TNo),ins.TDt))) and  
							 exists(Select 'x' From DtTbl Where DtTag='HOL' and TDt=DtDt and DtHolYN='Y')
		If @Row> 0
		begin  
			select @errmsg= 'Cannot Add Voucher On Holidays.'  
			goto ErrHndlr  
		end  
		
		

		/***************************** urmi Jul 03 Ch74 *****************************************/
		/* Current Partition */
		select @row= count('x') from inserted Where @wTcTyp in ('TZ') and TPrtKey=@wCurrPrtn 
			and not exists(select 'x' from Param where PTyp= 'ImpTyp' and PMCd= TImpTyp) 
		if @row> 0 
		begin
			select @errmsg= 'Import Type Not Defined'
			goto ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where @wTcTyp not in ('TZ') and TPrtKey=@wCurrPrtn 
				and TImpTyp<> ''  
		if @row> 0 
		begin
			select @errmsg= 'Import Type Should Not Be Defined'
			goto ErrHndlr
		end
		/***************************** urmi Jun 03 Ch74 *****************************************/


		/**** Manali 3.8.0 - TIMPCTG  *****/
		select @row= count('x') from inserted Where @wTcTyp in ('TZ') and TPrtKey=@wCurrPrtn 
			and not exists(select 'x' from Param where PTyp= 'ImpCtg' and PMCd= TImpCtg) 
		if @row> 0 
		begin
			select @errmsg= 'Import Category Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted Ins Where @wTcTyp in ('TZ') and TPrtKey=@wCurrPrtn 
			and Exists(Select 'x' from Deleted Del Where Del.TCoCd=Ins.TCoCd and Del.TTc=Ins.TTc and Del.TYy=Ins.TYy and Del.TChr=Ins.TChr and Del.TNo=Ins.TNo and Del.TPrtKey=Ins.TPrtKey and Del.TIdNo=Ins.TIdNo
										and Del.TImpCtg<>Ins.TImpCtg and 
										exists(Select 'x' from Txndz Where 
										TzCoCd=Del.TCoCd and TzTc=Del.TTc and TzYy=Del.TYy and TzChr=Del.TChr and TzNo=Del.TNo and TzPrtKey=Del.TPrtKey and TzTIdNo=Del.TIdNo
										and Convert(Decimal(14,3), TzRmDespWt)>0))
		if @row> 0 
		begin
			select @errmsg= 'Import Category Cannot Be Changed After Matching Is Done'
			goto ErrHndlr
		end


		select @row= count('x') from inserted where @wTcTyp not in ('TZ') and TPrtKey=@wCurrPrtn 
				and TImpCtg<> ''  
		if @row> 0 
		begin
			select @errmsg= 'Import Category Should Not Be Defined'
			goto ErrHndlr
		end
		/**** Manali 3.8.0 - TIMPCTG  *****/

		/*** (Jen 3.1.1) ***/
		/* Current Partition */		
		select @row= count('x') from inserted where TPRtKey=@wCurrPrtn and @wTcTyp in ('TXNBAG', 'TXNRM') and TCmCd<> ''  
		if @row> 0 
		begin
			select @errmsg= 'Customer Code Should Not Be Defined' 
			goto ErrHndlr
		end

		/* Current Partition */
