     Not Exists (Select 'x' from deleted del where ins.TdCoCd= del.TdCoCd and              
      ins.TdTc= del.TdTc and ins.TdYy= del.TdYy and ins.TdChr= del.TdChr and              
      ins.TdNo= del.TdNo and ins.TdSr= del.TdSr and ins.TdPtQty = del.TdPtQty)              
     If @Row> 0              
         Begin              
     Select @ErrMsg= 'Cannot Change Part Quantity'              
       GoTo ErrHndlr              
         end              
   End              
*/              
/* **** Not required **** */              
   /* Issuing Qty shld be <= receiving Qty of all receiving bags */              
/*        select @Row= Count('x') from inserted Ins              
    Join Txnd Td On Td.TdCoCd= ins.TdCoCd and Td.TdTc= ins.TdTc and              
     Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and Td.TdNo= ins.TdNo and              
     Td.TdSrNo= 0 and Td.TdBDc= (case when ins.TdBDc= 'D' then 'C'              
       when ins.TdBDc= 'C' then 'D' end)              
     and (case when ins.TdBDc= 'D' then ins.TdBQty              
       when ins.TdBDc= 'C' then Td.TdBQty end)<              
      (case when ins.TdBDc= 'D' then Td.TdBQty              
       when ins.TdBDc= 'C' then ins.TdBQty end)              
    where ins.TdSrNo= 0              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Receiving Bag Quantity Cannot Be < Issuing Bag Quantity'              
      GoTo ErrHndlr              
        end              
*/              
/* **** Not required **** */              
              
   if @mode in ('D')              
   begin              
    /*** (Bef 2.13)              
    --****** Cannot Delete 'BM', TdDc='C', Tdsrno= 0              
     If exists TdBDc='D', TdSrno=0 in same voucher ********              
    select @Row=Count('x') from Deleted Del where              
     Exists (Select 'x' from Txnd  where              
      Txnd.TdCoCd= Del.TdCoCd and Txnd.TdTc= Del.TdTc and              
      Txnd.TdYy= Del.TdYy and Txnd.TdChr= Del.TdChr and              
 Txnd.TdNo= Del.TdNo and Txnd.TdBDc= 'D' and TdSrNo= 0              
             )              
           and TdBDc= 'C' and TdSrNo= 0              
    If @Row > 0              
     begin              
       Select @ErrMsg='Cannot Delete Parent, Child Exists'              
       GoTo ErrHndlr              
         end              
    (Bef 2.13) ***/              
              
              
    /*** (Jen 2.13) ***/              
    /****** Cannot Delete 'BM', TdDc= 'C', TdSrNo= 0               
    If exists TdBDc= 'D', TdSrNo= 0, with same TdRefKey in same voucher ********/               
    /* Current Partition */              
    Select @Row= Count('x') from Deleted Del where Del.TdPrtKey=@wCurrPrtn and               
     Exists (Select 'x' from Txnd Td where Td.TdPrtKey=Del.TdPrtKey and              
      Td.TdTIdNo=Del.TdTIdNo and Td.TdCoCd= Del.TdCoCd and Td.TdTc= Del.TdTc and               
      Td.TdYy= Del.TdYy and Td.TdChr= Del.TdChr and               
      Td.TdNo= Del.TdNo and Td.TdBDc= 'D' and Td.TdSrNo= 0 and               
      Td.TdRefKey= Del.TdRefKey               
      /* and Td.TdSr> Del.TdSr */              
             )               
           and TdBDc= 'C' and TdSrNo= 0               

    If @Row > 0              
         Begin              
		    Select @ErrMsg= 'Cannot Delete Parent, Child Exists'              
			GoTo ErrHndlr              
         End              


   End              
  End
/* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */              
 End              
              
 /******* End of Checks only For @wEntTyp='TxnBag'  ***********/              
 /******************************************************************/              
              
              
              
              
 /***** performing fields Valids for wEntTyp='TxnRm' ********/              
 /********************************************************/              
              
 IF @wEntTyp='TxnRm'              
 BEGIN              
  /********* All Bag fields should be Blank *********/              
  /* Current Partition */             
Select @Row=Count('x') From Inserted Ins where Ins.TdPrtKey=@wCurrPrtn and               
   TdBYy<> '' or TdBChr<>'' or TdBNo<>0 or TdBDc <> ''              
        or TdFrBLoc <> '' or TdToBLoc <> '' or TdBGrWt <> 0              
        or TdBQty <> 0 or TdPtQty <> 0              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Bag related fields should be empty'              
   GoTo ErrHndlr              
  END              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */              
  /********** TdFrRmLoc Then Valid Loc, LocTyp<>'P' ************/              
  /* Current Partition */               
  Select @Row=Count('x') From Inserted Ins              
   Where Ins.TdPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdFrRmLoc And LocValidYN='Y')              
   /* AND TdFrRmDc = 'C' */              
      If @Row>0              
  BEGIN              
              
   Select @ErrMsg='Invalid From Rm Loc'              
     GoTo ErrHndlr              
  END              
              
/* **** Zubin 211 (Or Condition for 'TdFrRmDc' was missing) **** */              
  /********** TdFrRmLoc Then Valid Loc, LocTyp<>'P' ************/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and              
   (Ins.TdFrRmLoc <> ISNULL((SELECT Del.TdFrRmLoc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR              
   Ins.TdFrRmDc <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR Ins.TdFrRmLoc ='')              
   AND NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
    LocTyp<> 'P' AND LocCd = Ins.TdFrRmLoc AND LocValidYN = 'Y')              
   AND TdFrRmDc = 'D'              
/* **** Zubin 211 (Or Condition for 'TdFrRmDc' was missing) **** */              
      IF @Row>0              
  BEGIN              
              
   SELECT @ErrMsg='Invalid From Rm Loc'              
     GOTO ErrHndlr              
  END              
/*              
  Select @Row=Count('x') From Inserted Ins              
   Where Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdFrRmLoc)              
      If @Row>0              
  BEGIN              
              
   Select @ErrMsg='Invalid From Rm Loc'              
     GoTo ErrHndlr              
  END              
*/              
/*  #########################################  Manoj  #########################################  */              
              
  /********** TdFrRmDc  if 'TxnRm' then Valid 'Dc'*************/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Param where PTyp='DC'              
    and PMCd = Ins.TdFrRmDc and PScd='')               
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid From Rm DC'              
     GoTo ErrHndlr              
  END              
              
  /*********** TdRmCd if 'TxnRm' then Valid RmCd, RmZ='N' *********/              
  /* Current Partition */               
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and Not Exists (Select 'x' From RmMst where RmCd=TdRmCd and RmPrtKey=TdPrtKey and RmZ='N')              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Rm Code'              
     GoTo ErrHndlr              
  END              
              
/*  ####################  Manoj # Ver: 2.0.11 Patch 01 # Date: 17/08/2005  ####################  */              
  If @wTcTyp = 'PR'              
  Begin            
   /* Current Partition */              
   Select @Row=Count('x') From Inserted Ins              
    Join Loc On LocTyp = 'XP' And LocCoCd = Ins.TdCoCd              
    And LocCd = (Case When Ins.TdFrRmDc = 'C' Then Ins.TdFrRmLoc              
      When Ins.TdFrRmDc = 'D' Then Ins.TdToRmLoc End)              
   Where TdPrtKey=@wCurrPrtn and (Ins.TdRmCd <> ISNULL((SELECT Del.TdRmCd FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR              
   Ins.TdFrRmDc <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')      
   OR              
   (Case When Ins.TdFrRmDc = 'C' Then Ins.TdFrRmLoc When Ins.TdFrRmDc = 'D' Then Ins.TdToRmLoc End)              
    <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo               
    and Ins.TdCoCd = Del.TdCoCd And              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), ''))              
   And Not Exists (Select 'x' From RmMst where RmCd=TdRmCd and RmZ='N' And RmValidYN = 'Y')              
       If @Row>0              
   BEGIN              
    Select @ErrMsg='Rm Code Not Defined / InValid'              
      GoTo ErrHndlr              
   END              
  End              
/*  #########################################  Manoj  #########################################  */              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */               
  /* Current Partition */              
Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdToRmLoc And LocValidYn='Y'              
    and (@wTcTyp Not In('Rec','Cnv','Bs') Or LocTyp= 'Xc')))              
    /* AND TdToRmDc = 'C'*/              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid To Rm Loc'              
     GoTo ErrHndlr              
  END              
/* **** Zubin 211 (Or Condition for 'TdToRmLoc' was missing) **** */              
  /****** TdToRmLoc If 'TxnRm' Then Valid Loc, LocTyp<>'P' Else ''              
   If 'Rec', 'Cnv', 'Bs' Then LocTyp='Xc' ********/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE Ins.TdPrtKey=@wCurrPrtn and              
   ((              
   (Ins.TdToRmLoc <> ISNULL((SELECT Del.TdToRmLoc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR              
   Ins.TdToRmDc <> ISNULL((SELECT Del.TdToRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   )              
   AND (NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
    LocTyp<> 'P' AND LocCd = Ins.TdToRmLoc AND LocValidYN = 'Y'              
    AND (@wTcTyp NOT IN('Rec','Cnv','Bs') OR LocTyp= 'Xc'))))              
   Or Ins.TdToRmLoc = '')              
   AND TdToRmDc = 'D'              
/* **** Zubin 211 (Or Condition for 'TdToRmLoc' was missing) **** */              
      IF @Row>0              
  BEGIN              
   SELECT @ErrMsg='Invalid To Rm Loc'              
     GOTO ErrHndlr              
  END              
/*              
  Select @Row=Count('x') From Inserted Ins              
   Where (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdToRmLoc              
    and (@wTcTyp Not In('Rec','Cnv','Bs') Or LocTyp= 'Xc')))              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid To Rm Loc'              
     GoTo ErrHndlr              
  END              
*/              
/*  #########################################  Manoj  #########################################  */              
              
  /* Current Partition */              
  select @row= count('x') from inserted Ins where Ins.TdPrtKey=@wCurrPrtn and /*TdSrNo<>0 and */              
    Ins.TdFrRmLoc = Ins.TdToRmLoc and (Ins.TdFrRmLoc <> '' or              
    Ins.TdToRmLoc <> '')              
    if @row>0                begin              
      select @errmsg= 'To Rm Loc and From Rm Loc cannot be same'              
      goto ErrHndlr              
    end              
              
  /****** if 'TxnRm' then TdFrRmLoc or TdToRmLoc should not be of LocTyp= 'W' **********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
     LocTyp= 'W' and LocCd = Ins.TdFrRmLoc)              
           or Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and LocTyp= 'W' and LocCd = Ins.TdToRmLoc)              
    If @Row>0              
  begin              
   Select @ErrMsg= 'From Or To Rm Loc Should Not Be ''W'' '              
   GoTo ErrHndlr              
  end              
              
  /******* All Rj, Sp, Prd related fields If @wEntTyp='TxnRm' then '' *********/    
--Prev              
/*              
  Select @Row= Count('x') From Inserted Ins where              
   TdRjDc<> '' or TdRjQty<>0 or TdRjPtQty<> 0 or TdRjCd<> ''              
        or TdWrk<> '' or TdAck<>'' or TdPrdYN<> '' or TdByLoc<> ''              
   or TdByWrk<> '' or TdDustWt<> 0              
      If @Row> 0              
  begin              
   Select @ErrMsg= 'Rej, Prd Related Fields Should Be Empty'              
     GoTo ErrHndlr              
  end */              
  /* Current Partition */              
  Select @Row= Count('x') From Inserted Ins where Ins.TdPrtKey=@wCurrPrtn and              
   TdRjDc<> '' or TdRjQty<>0 or TdRjPtQty<> 0 or TdRjCd<> ''              
        or TdWrk<> '' or TdAck<>'' or TdPrdYN<> '' or TdByLoc<> ''              
   or TdByWrk<> ''              
      If @Row> 0              
  begin              
   Select @ErrMsg= 'Rej, Prd Related Fields Should Be Empty'              
     GoTo ErrHndlr              
  end /* Zubin 212 */              
              
  if (@wTcTyp= 'PR' and @wTc<> 'PR') Or (@wTcTyp<> 'PR' and @wTcTyp<> 'MV')              
  Begin              
  if @wTc <>'DT'
  begin
   /* Current Partition */              
  /* Manali 3.6.0 - Company level check removed (DiaJewel )*/      
   Select @Row= Count('x') From Inserted Ins where Ins.TdPrtKey=@wCurrPrtn and TdLotNo<> '' and              
    Exists (Select 'x' from Head where HCd= @wHCd and HCoCd= TdCoCd and HLotNoYN= 'Y') and             
 /*Not ((Select PValue from Param where PTyp='MWOPT' and PMCd='MULCOTRF' and PSCd='')='Y' and @wTcTyp= 'DT') and */             
    Not Exists (Select 'x' from SYyMm where SPrtKey=TdPrtKey /*and SCoCd= TdCoCd */ and SLotNo= TdLotNo)              
       If @Row> 0              
   begin              
    Select @ErrMsg= 'Invalid Lot No./Lot No. Does Not Exist'              
      GoTo ErrHndlr              
   end   End              
   end
/* Zubin 212 */           
      
 /***** Manali 3.8.0 - TdRtByQW *****/      
   select @Row= Count('x') from Inserted Ins where Ins.TdPrtKey=@wCurrPRtn and @wTc='PR'       
  and Not Exists(Select * from param Where Ptyp='LABQW' and PMCd=Ins.TdRtByQW)      
   If @Row> 0              
   begin              
    Select @ErrMsg= 'Invalid Rm Qw Option'              
    GoTo ErrHndlr              
   end              
        
   select @Row= Count('x') from Inserted Ins where Ins.TdPrtKey=@wCurrPRtn and @wTc='PR'       
  and Ins.TdRtByQW='Q' and (TdRmCtg<>'X' and TdRmCtg<>'D' and TdRmCtg<>'C')   
   If @Row> 0              
   begin              
    Select @ErrMsg= '"Q" Allowed in Rate By QW Option Only For Dia/CS/Accessories'              
    GoTo ErrHndlr              
   end              
         
 END              
              
              
              
 /***** End of performing fields Valids for wEntTyp='TxnRm' ********/              
 /***************************************************************/              
              
              
              
            
 /*** UPDATES ***/              
              
              
 /*** Update SYyMm from TdFrRmLoc ***/              
/* Zubin 212 (Lot No included in all SYyMm Inserts and Updates) */              
 if @mode in ('C','D')              
 begin              
  /* Current Partition */      
              
  update SYyMm set              
  SRmCrQty= SRmCrQty- (select isnull(sum(Del.TdRmQty), 0) from Deleted Del              
     where Del.TdFrRmDc='C' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd              
   and Del.TdLotNo= SLotNo and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and Del.TDRmSz3=SRmSz3 and Del.TdRmStkRt=SRmStkRt and Del.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))= SYyMm),              
  SRmCrWt= SRmCrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del              
   where Del.TdFrRmDc='C' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd              
     and Del.TdLotNo= SLotNo and Del.TDRmSz= SRmSz and Del.TDRmSz2= SRmSz2 and Del.TDRmSz3= SRmSz3 and Del.TdRmStkRt= SRmStkRt and Del.TdFrRmLoc=SLoc              
     and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrQty= SRmDrQty-(select isnull(sum(Del.TdRmQty),0) from Deleted Del              
    where Del.TdFrRmDc='D' and Del.TdPrtKEy=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd              
      and Del.TdLotNo= SLotNo and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and Del.TDRmSz3=SRmSz3 and Del.TdRmStkRt=SRmStkRt and Del.TdFrRmLoc=SLoc              
      and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt= SRmDrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del              
      where Del.TdFrRmDc='D' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd              
      and Del.TdLotNo= SLotNo and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and Del.TDRmSz3=SRmSz3 and Del.TdRmStkRt=SRmStkRt and Del.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Deleted       
   where Deleted.TdPrtKey=SPrtKey and Deleted.TdCoCd= SCoCd and Deleted.TdRmCd= SRmCd and Deleted.TdLotNo= SLotNo              
   and Deleted.TDRmSz= SRmSz and Deleted.TDRmSz2= SRmSz2 and Deleted.TDRmSz3= SRmSz3 and Deleted.TdRmStkRt= SRmStkRt and Deleted.TdFrRmLoc= SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm              
   and (Deleted.TdFrRmDc='D'  or Deleted.TdFrRmDc='C') and      
   ((@Mode='C' and Exists(Select 'x' From Inserted ins where ins.TdCoCd =Deleted.TdCoCd and ins.TdTc=Deleted.TdTc and ins.TdYy=Deleted.TdYy and      
         ins.TdChr=Deleted.TdChr and ins.TdNo=Deleted.TdNo and ins.TdSr=Deleted.TdSr and ins.TdSrNo=Deleted.TdSrNo and          
      (ins.TdPrtKey<>Deleted.TdPrtKey Or  ins.TdCoCd<>Deleted.TdCoCd Or ins.TdRmCd<>Deleted.TdRmCd Or ins.TdLotNo<>Deleted.TdLotNo      
        Or  ins.TDRmSz<>Deleted.TDRmSz or ins.TDRmSz2<>Deleted.TDRmSz2 or ins.TDRmSz3<>Deleted.TDRmSz3 or ins.TdRmStkRt<>Deleted.TdRmStkRt Or ins.TdFrRmLoc<>Deleted.TdFrRmLoc Or       
         Ins.TdRmWt<>Deleted.TdRmWt Or Ins.TdRmQty<>Deleted.TdRmQty Or  Ins.TdFrRmDC<>Deleted.TdFrRmDC Or    
         convert(int,convert(varchar(6),ins.TdDt,112))<>convert(int,convert(varchar(6),Deleted.TdDt,112))))) Or @Mode='D')      
      
if @wSysDbUni='Y'
begin      
  Update PpcTxnUpd set 
	PpuQtyCmpl = PpuQtyCmpl - (Select isnull(sum(Del.TdBQty), 0) 
										from Deleted Del 
										where Del.TdPrdYN='Y' and BRepYN = 'N' and PpuLoc =  Del.TdByLoc and Bag.BOdLnIdKey = PpuOdlIdKey)
  from Deleted
	join Bag on BCoCd = TdCoCd and BYy = TdBYy and BChr = TdBChr and BNo = TdBNo and BIdNo = TdBIdNo
  End
               

       
 end              
      
       
              
              
 if @mode in ('A','C')              
 begin              
  /* Current Partition */              
  insert into SYyMm(SPrtKey,SCoCd,SRmCd,SLotNo,SRmSz,SRmSz2, SRmSz3, SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt)              
   select distinct TdPrtKey, TdCoCd, TdRmCd,TdLotNo,TdRmSz,TdRmSz2, TdRmSz3, TdRmStkRt,TdFrRmLoc,convert(int,convert(varchar(6),TdDt,112)),0,0,0,0              
   from inserted       
   where not exists(select 'x' from  SYyMm where SPrtKey=TdPrtKey and SCoCd= TdCoCd and SRmCd=TdRmCd and SLotNo= TdLotNo              
   and SRmSZ=TdRmSz and SRmSZ2=TdRmSz2 and SRmSZ3=TdRmSz3 and SRmStkRt=TdRmStkRt and SLoc=TdFrRmLoc and              
   SYyMm= convert(int,convert(varchar(6),TdDt,112))) and              
   ((@wEntTyp= 'TxnBag' and TdSrNo<> 0) or (@wEntTyp= 'TxnRm' and TdSrNo= 0))              
              
  /* Current Partition */               
  update SYyMm set              
  SRmCrQty=SRmCrQty+(select isnull(sum(Ins.TdRmQty),0) from Inserted Ins       
   where Ins.TdFrRmDc='C' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
  and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmCrWt=SRmCrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdFrRmDc='C' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrQty=SRmDrQty+(select isnull(sum(Ins.TdRmQty),0) from Inserted Ins       
   where Ins.TdFrRmDc='D'  and Ins.TdPrtKey=SPrtKEy and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt=SRmDrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdFrRmDc='D'  and Ins.TdPRtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Inserted       
   where Inserted.TdPrtKey=SPrtKey and Inserted.TdCoCd= SCoCd and Inserted.TdRmCd= SRmCd and Inserted.TdLotNo=SLotNo              
   and Inserted.TDRmSz= SRmSz and Inserted.TDRmSz2= SRmSz2 and Inserted.TDRmSz3= SRmSz3  and Inserted.TdRmStkRt= SRmStkRt              
   and Inserted.TdFrRmLoc= SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm              
   and (Inserted.TdFrRmDc='D' or Inserted.TdFrRmDc='C')  and      
   ((@Mode='C' and Exists(Select 'x' From Deleted Del where Inserted.TdCoCd =Del.TdCoCd and Inserted.TdTc=Del.TdTc and Inserted.TdYy=Del.TdYy and      
         Inserted.TdChr=Del.TdChr and Inserted.TdNo=Del.TdNo and Inserted.TdSr=Del.TdSr and Inserted.TdSrNo=Del.TdSrNo and          
      (Inserted.TdPrtKey<>Del.TdPrtKey Or  Inserted.TdCoCd<>Del.TdCoCd Or Inserted.TdRmCd<>Del.TdRmCd Or Inserted.TdLotNo<>Del.TdLotNo      
        Or  Inserted.TDRmSz<>Del.TDRmSz or Inserted.TDRmSz2<>Del.TDRmSz2 or Inserted.TDRmSz3<>Del.TDRmSz3 or Inserted.TdRmStkRt<>Del.TdRmStkRt Or Inserted.TdFrRmLoc<>Del.TdFrRmLoc Or       
        Inserted.TdRmWt<>Del.TdRmWt Or Inserted.TdRmQty<>Del.TdRmQty Or Inserted.TdFrRmDC<>Del.TdFrRmDC Or      
         convert(int,convert(varchar(6),Inserted.TdDt,112))<>convert(int,convert(varchar(6),Del.TdDt,112))))) Or @Mode='A')             

if @wSysDbUni='Y'
begin      
  Insert into PpcTxnUpd (PpuOdlIdKey, PpuPrcs, PpuEvnt, PpuLoc, PpuQtyCmpl ,EntityRowNum)
   Select distinct BOdLnIdKey,Loc.LocPrcs,'',TdByLoc,0,0
   from Inserted
   join Loc on LocCoCd = inserted.TdCoCd and Loc.LocCd = inserted.TdByLoc 
   join Bag on BCoCd = inserted.TdCoCd and BYy = TdBYy and BChr = TdBChr and BNo = TdBNo 
	where TdPrdYN='Y' and Bag.BRepYN='N' 
	and not exists(select 'x' from PpcTxnUpd where PpuOdlIdKey = BOdLnIdKey and PpuLoc = TdByLoc)

  Update PpcTxnUpd set 
	PpuQtyCmpl = PpuQtyCmpl + (Select isnull(sum(TdBQty), 0) 
										from Inserted Ins 
										where Ins.TdPrdYN='Y' and BRepYN = 'N' and PpuLoc =  Ins.TdByLoc and Bag.BOdLnIdKey = PpuOdlIdKey)
  from Inserted
	join Bag on BCoCd = TdCoCd and BYy = TdBYy and BChr = TdBChr and BNo = TdBNo and BIdNo = TdBIdNo

end
 end              
              
 /*** Update SYyMm from TdToRmLoc ***/              
 if @mode in ('C','D')              
 begin              
  /* Current Partition */              
  update SYyMm set              
  SRmCrQty=SRmCrQty-(select isnull(sum(Del.TdRmQty),0) from Deleted Del       
   where Del.TdToRmDc='C' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd and Del.TdLotNo=SLotNo              
   and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and  Del.TDRmSz3=SRmSz3 and Del.TdRmStkRt=SRmStkRt and Del.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmCrWt=SRmCrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del       
   where Del.TdToRmDc='C' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and Del.TdLotNo=SLotNo              
   and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and Del.TDRmSz3=SRmSz3   and Del.TdRmStkRt=SRmStkRt and Del.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrQty=SRmDrQty-(select isnull(sum(Del.TdRmQty),0) from Deleted Del       
   where Del.TdToRmDc='D' and Del.TdPrtKEy=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd and Del.TdLotNo=SLotNo              
   and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and Del.TDRmSz3=SRmSz3 and Del.TdRmStkRt=SRmStkRt and Del.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt=SRmDrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del       
   where Del.TdToRmDc='D' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd and Del.TdLotNo=SLotNo              
   and Del.TDRmSz=SRmSz and Del.TDRmSz2=SRmSz2 and Del.TDRmSz3=SRmSz3 and Del.TdRmStkRt=SRmStkRt and Del.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Deleted       
   where Deleted.TdPrtKey=SPrtKey and Deleted.TdCoCd= SCoCd and Deleted.TdRmCd= SRmCd and Deleted.TdLotNo=SLotNo              
   and Deleted.TDRmSz= SRmSz and Deleted.TDRmSz2= SRmSz2 and Deleted.TDRmSz3= SRmSz3 and Deleted.TdRmStkRt= SRmStkRt and Deleted.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),Tddt,112))= SYyMm              
   and (Deleted.TdToRmDc='D' or Deleted.TdToRmDc='C')  and      
   ((@Mode='C' and Exists(Select 'x' From Inserted ins where ins.TdCoCd =Deleted.TdCoCd and ins.TdTc=Deleted.TdTc and ins.TdYy=Deleted.TdYy and      
         ins.TdChr=Deleted.TdChr and ins.TdNo=Deleted.TdNo and ins.TdSr=Deleted.TdSr and ins.TdSrNo=Deleted.TdSrNo and          
      (ins.TdPrtKey<>Deleted.TdPrtKey Or  ins.TdCoCd<>Deleted.TdCoCd Or ins.TdRmCd<>Deleted.TdRmCd Or ins.TdLotNo<>Deleted.TdLotNo      
        Or  ins.TDRmSz<>Deleted.TDRmSz or ins.TDRmSz2<>Deleted.TDRmSz2 or ins.TDRmSz3<>Deleted.TDRmSz3 or    ins.TdRmStkRt<>Deleted.TdRmStkRt Or ins.TdToRmLoc<>Deleted.TdToRmLoc Or       
        Ins.TdRmWt<>Deleted.TdRmWt Or Ins.TdRmQty<>Deleted.TdRmQty Or Ins.TdToRmDC<>Deleted.TdToRmDC Or      
         convert(int,convert(varchar(6),ins.TdDt,112))<>convert(int,convert(varchar(6),Deleted.TdDt,112))))) Or @Mode='D')      
      
             
 end              
              
 if @mode in ('A','C')              
 begin              
  /* Current Partition */              
  insert into SYyMm(SPrtKey,SCoCd, SRmCd,SLotNo,SRmSz,SRmSz2, SRmSz3, SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt)              
  select distinct TdPrtKey,TdCoCd, TdRmCd,TdLotNo,TdRmSz,TdRmSz2, TdRmSz3, TdRmStkRt, TdToRmLoc, convert(int,convert(varchar(6),TdDt,112)), 0, 0, 0, 0              
   from inserted       
   where not exists(select 'x' from  SYyMm where SPrtKey=TdPrtKey and SCoCd= TdCoCd and SRmCd=TdRmCd and SLotNo=TdLotNo              
   and SRmSZ=TdRmSz and SRmStkRt=TdRmStkRt and SLoc=TdToRmLoc and    SRmSZ2=TdRmSz2 and    SRmSZ3=TdRmSz3        and       
   SYyMm=convert(int,convert(varchar(6),TdDt,112))) and              
   ((@wEntTyp= 'TxnBag' and TdSrNo<> 0) or (@wEntTyp= 'TxnRm' and TdSrNo= 0))              
              
  /* Current Partition */              
  update SYyMm set              
  SRmCrQty=SRmCrQty+(select isnull(sum(Ins.TdRmQty),0) from Inserted Ins       
   where Ins.TdToRmDc='C' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmCrWt=SRmCrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdToRmDc= 'C' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrQty=SRmDrQty+(select isnull(sum(Ins.TdRmQty),0) from Inserted Ins       
   where Ins.TdToRmDc='D' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt=SRmDrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdToRmDc='D' and Ins.TdPrtKEy=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TDRmSz2=SRmSz2 and Ins.TDRmSz3=SRmSz3 and Ins.TdRmStkRt=SRmStkRt and Ins.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Inserted       
   where Inserted.TdPrtKey=SPrtKey and Inserted.TdCoCd= SCoCd and Inserted.TdRmCd=SRmCd and Inserted.TdLotNo=SLotNo              
   and Inserted.TDRmSz=SRmSz and Inserted.TDRmSz2=SRmSz2 and Inserted.TDRmSz3=SRmSz3 and Inserted.TdRmStkRt=SRmStkRt and Inserted.TdToRmLoc= SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm              
   and (Inserted.TdToRmDc='D' or Inserted.TdToRmDc='C')  and      
 ((@Mode='C' and Exists(Select 'x' From Deleted Del where Inserted.TdCoCd =Del.TdCoCd and Inserted.TdTc=Del.TdTc and Inserted.TdYy=Del.TdYy and      
         Inserted.TdChr=Del.TdChr and Inserted.TdNo=Del.TdNo and Inserted.TdSr=Del.TdSr and Inserted.TdSrNo=Del.TdSrNo and          
      (Inserted.TdPrtKey<>Del.TdPrtKey Or  Inserted.TdCoCd<>Del.TdCoCd Or Inserted.TdRmCd<>Del.TdRmCd Or Inserted.TdLotNo<>Del.TdLotNo      
        Or  Inserted.TDRmSz<>Del.TDRmSz Or  Inserted.TDRmSz2<>Del.TDRmSz2 or  Inserted.TDRmSz3<>Del.TDRmSz3 or Inserted.TdRmStkRt<>Del.TdRmStkRt Or Inserted.TdToRmLoc<>Del.TdToRmLoc Or       
          Inserted.TdRmWt<>Del.TdRmWt Or Inserted.TdRmQty<>Del.TdRmQty Or  Inserted.TdToRmDC<>Del.TdToRmDC Or    
         convert(int,convert(varchar(6),Inserted.TdDt,112))<>convert(int,convert(varchar(6),Del.TdDt,112))))) Or @Mode='A')                   
       
 end              
              
 /* urmi NegStk Start*/              
 IF @wEntTyp in ('TxnRm', 'TxnBag')              
 BEGIN              
 /* While adding or changing Chk for Issuing Location */              
      if @mode in ('A','C')              
/*  ####################  Manoj # Ver: 2.0.11 Patch 01 # Date: 17/08/2005  ####################  */              
      begin              
/*  Select @Row=Count('x') From Inserted Ins join Txn on TCoCd= Ins.TdCoCd and              
         TTc= Ins.TdTc and TYy= ins.TdYy and              
         TChr= Ins.TdChr and TNo= Ins.TdNo              
  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and Exists (Select 'X' from Param where PTyp= 'SEOPWD' and PMCD='SEOPWD'              
   and TSeoPwd<> PValue1)              
  and Exists (Select 'X' From Loc where LocCoCd= Ins.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
                         when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
          else '' end) )              
              
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
--  and ( (Select SUM(SRmDrWt)-SUM(SRmCrWt) from SYyMm              
    where Ins.TdCoCd= SCoCd and Ins.TdRmCd= SRmCd and              
     Ins.TDRmSz= SRmSz and              
     (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
     when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
     else '' end )= SLoc              
       )--- Ins.TdRmWt              
      ) < 0              
*/              
  /* Checking When AvgStkRt = 'Y' Or Stock By StkRt = 'N' */              
/* Zubin 212 (LotNo added) */              
  if @wTc = 'DT'
  begin 
  /* Zubin 212 */              
  /* Lot No shld be valid from SYyMm for CoCd */              
  /* Current Partition */              
  /* Manali 3.6.0 - Company level check removed (DiaJewel )*/      
  Select @Row= Count('x') From Inserted Ins where TdPrtKey=@wCurrPrtn and TdLotNo<> '' and              
   Not(TdFrRmDc= 'C' and TdFrRmLoc= 'W') and Not(TdFrRmDc= 'D' and TdToRmLoc= 'W') and              
   /*Not ((Select PValue from Param where PTyp='MWOPT' and PMCd='MULCOTRF' and PSCd='')='Y' and @wTcTyp= 'DT') and */            
   Not Exists (Select 'x' from SYyMm where SPrtKey=TdPrtKey /*and SCoCd= TdCoCd*/ and SLotNo= TdLotNo)              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Invalid Lot No./Lot No. Does Not Exist'              
     GoTo ErrHndlr              
  end              
  /* Zubin 212 */              
  end
  /* ****** Sachin 2.14.0 [RmMst Join added For RmCtg Check] ****** */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x')               
     From Inserted Ins               
      Join Txn on TPrtKey=Ins.TdPrtKey and TIdNo=Ins.TdTIdNo and TCoCd= Ins.TdCoCd and TTc= Ins.TdTc and TYy= ins.TdYy and              
        TChr= Ins.TdChr and TNo= Ins.TdNo               
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKey=Ins.TdPrtKey and RmCd=Ins.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
        Else (Select ','+PDesc225+',' From Param               
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= Ins.ModUsr and UaMnuCd = Ins.TdTc and UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Ins.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
                         when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
          else '' end) )              
  and ((Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Ins.TdPrtKEy=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd= SRmCd and Ins.TdLotNo= SLotNo and              
     Ins.TDRmSz= SRmSz and              Ins.TDRmSz2= SRmSz2 and              Ins.TDRmSz3= SRmSz3 and              
     (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
 when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
     else '' end )= SLoc              
       )/*- Ins.TdRmWt */              
      ) < 0              
  And (Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'Y')              
       Or              
       Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Ins.TdPrtKey and RmCd = Ins.TdRmCd And              
   PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'N'))              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
       end              
              
  /* Checking When AvgStkRt = 'N' And Stock By StkRt = 'Y' */              
  /* Zubin 212 (LotNo added) */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins               
    join Txn on TPrtKey=Ins.TdPrtKey and TIdNo=Ins.TdTIdNo and TCoCd= Ins.TdCoCd and              
       TTc= Ins.TdTc and TYy= ins.TdYy and TChr= Ins.TdChr and TNo= Ins.TdNo              
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKey=Ins.TdPrtKey and RmCd=Ins.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
    Else (Select ','+PDesc225+',' From Param               
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess Ua on Ua.UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= ins.ModUsr and Ua.UaMnuCd = ins.TdTc and Ua.UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Ins.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
                         when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
          else '' end) )              
              
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd= SRmCd and Ins.TdLotNo= SLotNo and              
     Ins.TDRmSz= SRmSz and Ins.TDRmSz2= SRmSz2 and Ins.TDRmSz3= SRmSz3 and Ins.TdRmStkRt =SRmStkRt and              
     (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
        when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
      else '' end )= SLoc              
     )/*- Ins.TdRmWt */              
      ) < 0              
  And Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'N')              
  And Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Ins.TdPrtKey and RmCd = Ins.TdRmCd And              
   PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'Y')              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
       end              
              
              
      end               
 /* While deleting Chk for Receiving Location */              
      if @mode in ('D')              
      begin              
/*  Select @Row=Count('x') From Deleted Del join Txn on TCoCd= Del.TdCoCd and              
         TTc= Del.TdTc and TYy= Del.TdYy and              
         TChr= Del.TdChr and TNo= Del.TdNo              
  Where Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and Exists (Select 'X' from Param where PTyp= 'SEOPWD' and PMCD='SEOPWD'              
   and TSeoPwd<> PValue1)              
  and Exists (Select 'X' From Loc where LocCoCd= Del.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
                          when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
 else '' end) )              
             
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
--  and ( (Select SUM(SRmDrWt)-SUM(SRmCrWt) from SYyMm              
    where Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and              
     Del.TDRmSz= SRmSz and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) --- Del.TdRmWt              
      ) < 0              
              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock'              
     GoTo ErrHndlr              
  end              
*/              
  /* Checking When AvgStkRt = 'Y' Or Stock By StkRt = 'N' */              
/* Zubin 212 (LotNo added) */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x') From Deleted Del join Txn on TPrtKey=Del.TdPrtKEy               
       and TIdNo=Del.TdTIdNo and TCoCd= Del.TdCoCd and              
       TTc= Del.TdTc and TYy= Del.TdYy and              
       TChr= Del.TdChr and TNo= Del.TdNo              
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKEy=Del.TdPrtKey and RmCd=Del.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
         Else (Select ','+PDesc225+',' From Param               
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= Del.ModUsr and UaMnuCd = Del.TdTc and UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Del.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
                          when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
          else '' end) )              
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and Del.TdLotNo= SLotNo and              
     Del.TDRmSz= SRmSz and              Del.TDRmSz2= SRmSz2 and              Del.TDRmSz3= SRmSz3 and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) /*- Del.TdRmWt */              
      ) < 0              
  And (Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'Y')              
    Or              
       Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKEy=Del.TdPrtKEy and RmCd = Del.TdRmCd And              
   PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'N'))              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
  end              
              
 /* Checking When AvgStkRt = 'Y' Or Stock By StkRt = 'N' */              
 /* Zubin 212 (LotNo added) */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x') From Deleted Del join Txn on TPrtKey=Del.TdPrtKey and TIdNo=Del.TdTIdNo              
       and TCoCd= Del.TdCoCd and TTc= Del.TdTc and TYy= Del.TdYy and              
       TChr= Del.TdChr and TNo= Del.TdNo              
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKEy=Del.TdPrtKey and RmCd=Del.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
          Else (Select ','+PDesc225+',' From Param             
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= Del.ModUsr and UaMnuCd = Del.TdTc and UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Del.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
                          when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
          else '' end) )              
              
  and ((Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Del.TdPrtKey=SPRtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and Del.TdLotNo= SLotNo and              
     Del.TDRmSz = SRmSz and Del.TDRmSz2 = SRmSz2 and Del.TDRmSz3 = SRmSz3 and Del.TdRmStkRt = SRmStkRt and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) /*- Del.TdRmWt */              
      ) < 0              
  And Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'N')              
  And Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Del.TdPrtKey and RmCd = Del.TdRmCd And              
       PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'Y')              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
  End              
      End  /*  #########################################  Manoj  #########################################  */              
 END              
 END              
 /**** urmi NegStk end ****/              
              
 If @wEntTyp = 'TxnBag' And @wTcTyp= 'BM'               
 Begin              
  If @Mode in ('A', 'C')              
  Begin              
   /****** (Jen 2.13 CT) changed the where clause for considering Component Bags ******/              
   /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge  ****** */              
   /* This check has been put at end as there are certain checks which fail when bag is closed               
      and are placed above this update ***** */              
   /* Current Partition */              
   Update Bag               
    Set BCls = 'Y',              
                      BClsDt= (Select TDt From Txn Where TPrtKey=ins.TdPrtKey               
          and TIdNo=ins.TdTIdNo and TCoCd= ins.TdCoCd And TTc = ins.TdTc               
          And TYy = ins.TdYy And TChr= ins.TdChr And TNo= ins.TdNo)               
   From inserted ins              
   Where BPrtKey=ins.TdPrtKey and BIdNo=ins.TdBIdNo and BCoCd= ins.TdCoCd And BYy= ins.TdBYy And BChr= ins.TdBChr               
    And BNo= ins.TdBNo And ins.TdSrNo= 0               
    And Convert( Decimal (16, 1), BQty) = Convert( Decimal (16, 1), 0)               
    And Convert( Decimal (16, 3), BGrWt) = Convert( Decimal (16, 3), 0)               
    And BPtQty = 0               
    And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= ins.TdBChr And PSCd= '') in ('C', 'F')               
    /*  (Bef 2.13 CT)              
      And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= Del.TdBChr And PSCd= '' )= 'Y'              
         (Bef 2.13 CT) */              
   /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge  ****** */               
  End              
 End                
Return              
ErrHndlr:              
 BEGIN              
  Select @ErrMsg='|'+@ErrMsg              
  RaisError(@ErrMsg,16,1)              
  Rollback Transaction              
 END 





GOGO


ALTER TRIGGER [dbo].[TxndPrd_INUPDL] ON [dbo].[TxndPrd] 
        FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
	 /* Trigger Version 3.11.0 */
	 DECLARE @ROW INT  
	 DECLARE @mode char(1)  
	 DECLARE @errmsg varchar(255)  
	 DECLARE @ReplAgt BIT  
	 DECLARE @wCurrPrtn VarChar(1)

	IF @@ROWCOUNT=0   RETURN  
  
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TxndPrd' )  
	RETURN  
  
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
       else  
	case (select count('x') from deleted) when 0 then 'A' else 'C' end  
       end   

	Select @wCurrPrtn='C'
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TpPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins 
									Where ins.TpIdNo=del.TpIdNo and ins.TpCoCd=del.TpCoCd and ins.TpTc=del.TpTc and
										  ins.TpYy=del.TpYy and ins.TpChr=del.TpChr and ins.TpNo=del.TpNo and 
										  ins.TpSr=del.TpSr and ins.TpSrNo=del.TpSrNo and ins.TpPrtKey<>del.TpPrtKey) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end

	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TpPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TpPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where  TpPRtKey=@wCurrPrtn and
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TpCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where TpPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TpCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	if @mode in ('A', 'C')
	Begin
		/*** Voucher Sr should Exist In Txnd ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and not exists (select 'x' from Txnd where
			TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
			and TdNo= TpNo and TdSr= TpSr ) /*and TdPrdYN= 'Y'*/
		if @row>0
		begin
			select @errmsg= 'Voucher Sr Not Defined In Txnd' /* /TdPrdYn = 'N' */
			goto ErrHndlr
		end

		/*** TpSrNo > 0  ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSrNo<= 0
		if @row>0
		begin
			select @errmsg= 'Serial Number Cannot Be Zero'
			goto ErrHndlr
		end

		/*** Valid Worker ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpByWrk<> '' and
			not exists (select vPMCd from vParam where vPCoCd = TpCoCd
				and vPTyp= 'WORK' and vPMCd= TpByWrk and vPValidYN='Y')
		if @row>0
		begin
			select @errmsg= 'Worker Code Not Defined'
			goto ErrHndlr
		end

		/*** TdBQty (Txnd) >= 0 ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and not exists (select 'x' from Txnd where
			TdPrtKey=TpPRtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
			and TdNo= TpNo and TdSr= TpSr and TdBQty>= 0)
		if @row>0
		begin
			select @errmsg= 'Bag Qty Should Be >= 0'
			goto ErrHndlr
		end

		/****** Cannot Add/ Change As Not The Last Transaction Of The Bag ********/
		/* Current Partition */
		select @Row= Count('x') from inserted join Txnd on TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo
				and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
				and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0
			where TpPrtKey=@wCurrPrtn and not exists (Select 'x' from Bag where BPrtKey=TdPrtKey and BIdno=TdBIdNo 
				and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo and BLstYyKey= TdYyKey)
		If @Row > 0
		begin
			Select @ErrMsg= 'Cannot Edit Since Not The Last Transaction Of The Bag'
			GoTo ErrHndlr
		end

		/* Current Partition */
		/*select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSubPrc<> '' and
				not exists (select PSCd from Param where PTyp= 'SUBPRC'
					and PMCd= (Select TdByLoc from Txnd where TdPRtKey=TpPrtKey and TdIdNo=TpTdIdNo 
					and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
					and TdSr= TpSr and TdSrNo= 0) and PSCd= TpSubPrc)
		if @row>0
		begin
			select @errmsg= 'Sub Process Not Defined'
			goto ErrHndlr
		end*/
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSubPrc<> '' and
				not exists (select PSCd from Param where PTyp= 'SUBPRC'
					and PMCd= (Select LocPrcs from Loc where LocCoCd =TpCoCd and 
					LocCd = (Select TdByLoc from Txnd where TdPRtKey=TpPrtKey and TdIdNo=TpTdIdNo 
					and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
					and TdSr= TpSr and TdSrNo= 0) and PSCd= TpSubPrc))
		if @row>0
		begin
			select @errmsg= 'Sub Process Not Defined'
			goto ErrHndlr
		end
		
		
/*
		select @row= count('x') from inserted where (TpBQty< 0 or TpPrdCtg= '' or TpRmQty<> 0 or TpRmCtg<> '' or TpRmSCtg<> '' or TpSetTyp<> '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
						and TdSr= TpSr and TdSrNo= 0) in ('GN')
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Bag Qty Should Be >= 0, Rm Qty = 0, PrdCtg Not Blank, RmCtg/RmSubCtg/SetTyp Blank'
			goto ErrHndlr
		end
*/

		/* (Bef 2.13)		
		select @row= count('x') from inserted where (TpPrdCtg= '' or TpRmQty<> 0 or TpRmCtg<> '' or TpRmSCtg<> '' or TpSetTyp<> '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
						and TdSr= TpSr and TdSrNo= 0) in ('GN')
		(Bef 2.13) */


		/*** (Jen 2.13) ***/		
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and (TpPrdCtg= '' or TpRmQty<> 0 or TpRmCtg<> '' or TpRmSCtg<> '' or TpSetTyp<> '') and
					(Select (Select LocPrdTyp from Loc where LocCoCd= TdCoCd and LocCd= TdByLoc) 
						from Txnd where TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy 
						and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0 ) in ('GN')
		/*** (Jen 2.13) ***/		
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Rm Qty = 0, PrdCtg Not Blank, RmCtg/RmSubCtg/SetTyp Blank'
			goto ErrHndlr
		end
/*
		select @row= count('x') from inserted where (TpBQty< 0 or TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp= '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
						and TdSr= TpSr and TdSrNo= 0) in ('WS', 'GS')
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Bag Qty Should Be >= 0, Rm Qty > 0, PrdCtg Blank, RmCtg/RmSubCtg/SetTyp Not Blank'
			goto ErrHndlr
		end
*/

		/* (Bef 2.13)
		select @row= count('x') from inserted where (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp= '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc 
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WS', 'GS')
		(Bef 2.13) */

		/*** (Jen 2.13)	***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp= '') and
					(Select (Select LocPrdTyp from Loc where LocCoCd= TdCoCd and LocCd= TdByLoc) 
					From Txnd where TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WS', 'GS')
		/*** (Jen 2.13)	***/
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Rm Qty <> 0, PrdCtg Blank, RmCtg/RmSubCtg/SetTyp Not Blank'
			goto ErrHndlr
		end
/*	#################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date:	08/12/2003																			 */
/*	Cnange:	Following Check is added for checking only required values are Entered				 */

		
		/* (Bef 2.13)
		select @row= count('x') from inserted where (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp<> '') and 
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc 
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WP', 'GP')
		(Bef 2.13) */

		/*** (Jen 2.13)	***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp<> '') and 
					(Select (Select LocPrdTyp from Loc where LocCoCd= TdCoCd and LocCd= TdByLoc) 
					from Txnd where TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WP', 'GP')
		/*** (Jen 2.13)	***/
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry for PrdTyp in (''GP'',''WP''), Rm Qty <> 0, PrdCtg Blank, RmCtg/RmSubCtg Not Blank, SetTyp Blank'
			goto ErrHndlr
		end
		/*  #########################################  Manoj  #########################################  */

		/******  If not Blank then TpPrdCtg= valid PMCd('PRDCTG')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpPrdCtg<> '' and
	  		not exists (select 'x' from Param where PTyp= 'PRDCTG' and PMCd= TpPrdCtg)
 		if @row> 0
	 	Begin
  			select @errmsg= 'Production Category Not Defined'
  			goto ErrHndlr
	 	end

		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpRmCtg<> '' and not exists (select PMCd from Param where PTyp= 'RMCTG'
				and PMCd= TpRmCtg)
		if @row>0
		begin
			select @errmsg= 'Raw Material Category Not Defined'
			goto ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpRmSCtg<> '' and not exists (select PSCd from Param where PTyp= 'RMSCTG'
				and PMCd= TpRmCtg and PSCd= TpRmSCtg)
		if @row>0
		begin
			select @errmsg= 'Raw Material Sub Category Not Defined'
			goto ErrHndlr
		end

		/******  If not Blank then TpSetTyp= valid PSCd('LABSCD', 'SET')  ******/
		/* 3.11.0 */
		Select @row= count('x') from inserted 
					Join Head On HCoCd=TpCoCd And HCd='ZSELF'
		Where TpPrtKey=@wCurrPrtn and TpSetTyp<> '' and
		 ((hSetTypOnlyFrOrdYN='N' And Not exists (Select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= TpSetTyp)) OR
		  (hSetTypOnlyFrOrdYN='Y' And Not exists (select 'x' from Txnd 												
														Join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo
														Join OrdRm on OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr and OrNo= BOdNo and OrSr= BOdSr
													Where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr 
														And TdSrNo=0 And OrRmCtg= TpRmCtg and OrRmSCtg= TpRmSCtg And OrSetSCd=TpSetTyp))) 			

 		if @row> 0
	 	Begin
  			select @errmsg= 'Setting Type Not Defined or Absent in Order'
  			goto ErrHndlr
	 	end

		/* Current Partition */
		/* Before 3.11.0 */
		/* select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSetTyp<> '' and
	  		not exists (select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= TpSetTyp)
 			if @row> 0
	 		Begin
  				select @errmsg= 'Setting Type Not Defined'
  				goto ErrHndlr
	 		end */

/*	#################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date:	08/12/2003				Ver:	2.0.6												*/
/*	Cnange:	In this Check is condition is added for allowing SETTYP Blank When PRDTYP in ('GP','WP')*/
		/* Current Partition */
/* **** Manali 3.5.0 - Check for Setting Type from OrdRm removed **** */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpRmCtg<> '' and
			not exists (select 'x' from inserted join Txnd on TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy 
						and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0 
					join Bag on BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo 
					join OrdRm on OrPrtKey=BPrtKey and OrOdIdNo=BOdIdNo and OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr 
						and OrNo= BOdNo and OrSr= BOdSr 
					where OrRmCtg= TpRmCtg and OrRmSCtg=TpRmSCtg /*and 
						(OrSetSCd= TpSetTyp Or (Select LocPrdTyp From Loc Where LocCoCd = TdCoCd 
						And LocCd = TdByLoc) in ('GP', 'WP'))*/) 
		If @row> 0
		begin
			select @errmsg= 'Raw Material Ctg/ Sub Ctg Combination Not Defined In OrderRm'
			/* select @errmsg= 'Raw Material Ctg/ Sub Ctg/ SetTyp Combination Not Defined In OrderRm' */
			goto ErrHndlr
		end
/*
		select @row= count('x') from inserted where TpRmCtg<> '' and
			not exists (select 'x' from inserted join Txnd on TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and
				    TdNo= TpNo and TdSr= TpSr and TdSrNo= 0 join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and
				    BNo= TdBNo join OrdRm on OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr and
				    OrNo= BOdNo and OrSr= BOdSr where OrRmCtg= TpRmCtg and OrRmSCtg=TpRmSCtg
				    and OrSetSCd= TpSetTyp)
		if @row>0
		begin
			select @errmsg= 'Raw Material Ctg/ Sub Ctg/ SetTyp Combination Not Defined In OrderRm'
			goto ErrHndlr
		end
*/
/*  #########################################  Manoj  #########################################  */
/*		select @row= count('x') from inserted where TpPts= 0
		if @row>0
		begin
			select @errmsg= 'Production Points Cannot Be Zero'
			goto ErrHndlr
		end
*/
		/* (Bef 2.13) select @row= count('x') from inserted where Str(TpPts, 16, 2)= Str(0, 16, 2) */
		/*** (Jen 2.13) ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and convert (decimal (16, 2), TpPts)= convert (decimal (16, 2), 0)
		/*** (Jen 2.13) ***/
		if @row> 0
		begin
			select @errmsg= 'Production Points Cannot Be Zero'
			goto ErrHndlr
		end
/*		*** Do not allow negative values for a Bag+ RmCtg+ RmSCtg+ SetTyp (this check to be applied later) ***
		select @row= count('x') from inserted ins join Txnd Td on TdTc= TpTc and TdYy= TpYy
			and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr
			and exists(Select 'x' from Txnd Td1 join TxndPrd Tp on Tp.TpTc= Td1.TdTc
			and Tp.TpYy= Td1.TdYy and Tp.TpChr= Td1.TdChr and Tp.TpNo= Td1.TdNo
			and Tp.TpSr= Td1.TdSr where Td1.TdBYy= Td.TdBYy
			and Td1.TdBChr= Td.TdBChr and Td1.TdBNo= Td.TdBNo
			group by Tp.TpRmCtg, Tp.TpRmSCtg, Tp.TpSetTyp
			having Round(sum(Tp.TpBQty), 1)< 0 or sum(Tp.TpRmQty) < 0
			or Round(sum(Tp.TpPts), 2)< 0)
		if @row> 0
		begin
			select @errmsg= 'Total Production Points Cannot Be Negative For The Bag'
			goto ErrHndlr
		end
*/
	/* **** Zubin 211 **** */
/* NOT REQUIRED */
/*		select @row= count('x') from inserted ins where ins.TpRmCtg In ('D', 'C') and
			Exists (select 'x' from Head where HCoCd= TpCoCd and HOrdPrdPts= 'Y') and
			(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
				where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
					and TdSr= TpSr and TdSrNo= 0) In ('GP', 'GS', 'WP', 'WS') and
			(select Convert(decimal(16, 2), Sum(Tp.TpRmQty) /
					Sum(case when Convert(decimal(16, 1), Tp.TpBQty)= 0 then 1 else Tp.TpBQty end))
				from TxndPrd Tp
				join Txnd on TdCoCd= Tp.TpCoCd and TdTc= Tp.TpTc and TdYy= Tp.TpYy and
					TdChr= Tp.TpChr and TdNo= Tp.TpNo and TdSr= Tp.TpSr and TdSrNo= 0
				join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo
				where Tp.TpCoCd= ins.TpCoCd and Tp.TpTc= ins.TpTc and Tp.TpYy= ins.TpYy and
					Tp.TpChr= ins.TpChr and Tp.TpNo= ins.TpNo and Tp.TpSr= ins.TpSr and
					Tp.TpRmCtg= ins.TpRmCtg and Tp.TpRmSCtg= ins.TpRmSCtg
				Group By Tp.TpRmCtg, Tp.TpRmSCtg )>
			(select Convert(decimal(16, 2), Sum(OrPrdQty)) from Txnd
				Join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo
				join OrdRm on OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr and
					OrNo= BOdNo and OrSr= BOdSr
			where TdSrNo= 0 and Exists (Select 'x' from TxndPrd where TdCoCd= TpCoCd and TdTc= TpTc and
				TdYy= TpYy and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and OrRmCtg= TpRmCtg and
				OrRmSCtg= TpRmSCtg ) and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and
				TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and OrRmCtg= ins.TpRmCtg and
				OrRmSCtg= ins.TpRmSCtg
				Group By OrRmCtg, OrRmSCtg )
		if @row> 0
		begin
			select @errmsg= 'Cannot Give Production Points For RmQty More Than In Order'
			goto ErrHndlr
		end
*/
/* **** Zubin 211 **** */
	End
	if @mode in ('C')
	Begin
		/****** Key Cannot Be Changed ******/
		/* Current Partition */
		select @Row=Count('x') from deleted del where del.TpPrtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.TpPrtKey=del.TpPrtKey and ins.TpIdNo=del.TpIdNo
			and ins.TpCoCd= del.TpCoCd and ins.TpTc= del.TpTc and ins.TpYy= del.TpYy and ins.TpChr= del.TpChr
			and ins.TpNo= del.TpNo and ins.TpSr= del.TpSr and ins.TpSrNo= del.TpSrNo)
		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change Voucher No.'
			GoTo ErrHndlr
		end
	End
	
	
	If @mode in ('D')
	Begin
		/****** Cannot Delete As Not The Last Transaction Of The Bag ********/
		/* Current Partition */
		select @Row= Count('x') from Deleted join Txnd on TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo
				and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
				and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0
			where TpPrtKey=@wCurrPrtn and not exists (Select 'x' from Bag where BPrtKey=TdPrtKey and BIdno=TdBIdNo 
				and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo and BLstYyKey= TdYyKey)
		If @Row > 0
		begin
			Select @ErrMsg= 'Cannot Delete Since Not The Last Transaction Of The Bag'
			GoTo ErrHndlr
		end

	End
RETURN
ErrHndlr:
	Begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	End
END

GOGO

ALTER TRIGGER [dbo].[vParam_INUPDL] ON [dbo].[vParam] 
   For INSERT,UPDATE,DELETE
   NOT FOR REPLICATION
As
BEGIN
 /* Trigger Version 2.14.0 [Original] */	
 DECLARE @ROW INT
 DECLARE @mode char(1)
 DECLARE @errmsg varchar(255)
 DECLARE @vPTyp varchar(8)
 DECLARE @wHCd VARCHAR(8)
 DECLARE @wSelfCoCd VARCHAR(3)
 DECLARE @ReplAgt BIT  
	
 IF @@ROWCOUNT=0   RETURN

 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'vParam' )
  RETURN

 select @mode=case (select count('x') from inserted) when 0 then 'D'
       else
   case (select count('x') from deleted) when 0 then 'A' else 'C' end
       end

	set @wHCd = 'ZSELF'	
	set @wSelfCoCd= 'ZZZ'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One vPTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One vPTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/*** Storing PTyp In The Variable @PTyp ***/
	select @vPTyp= case  when @mode in ('C', 'A') then (Select max(vPTyp) from inserted)  else (Select max(vPTyp) from deleted) end  

	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	select @Row=Count('x') from vParam vPm where (@vPTyp= 'PTYP') or 
		(vPm.vPTyp= 'PTYP' and vPm.vPMCd= @vPTyp and vPm.vPValue= 'M')
	If @Row > 0
	begin 
		Select @ErrMsg='Cannot Add/Change/Delete Microway Parameter - '+ @vPTyp
		GoTo ErrHndlr
	end		

 	/******** Key Cannot Be Changed  (i.e.vPCoCd, vPTyp, vPMCd and vPSCd cannot be changed) ********/ 
 	If @mode = 'C'
 	Begin
  		select @Row=Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.vPCoCd= del.vPCoCd and 
			ins.vPTyp= del.vPTyp and ins.vPMCd= del.vPmCd and ins.vPSCd= del.vPSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Variable Param Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	BEGIN
		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp<> 'PTYP' and 
		not exists (select 'x' from vParam Prm where Prm.vPCoCd= @wSelfCoCd and 
					Prm.vPTyp= 'PTYP' and Prm.vPMCd= ins.vPTyp)
		if @row> 0 
		begin
			select @errmsg= 'Variable Parameter Type Not Defined'
			goto ErrHndlr
		end

		/****** vPCoCd= valid HCoCd ******/
		select @row= count('x') from inserted ins where not exists
			 (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd)
		if @row>0 
		begin
			select @errmsg= 'Company Code Not Defined'
			goto ErrHndlr
		end

		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp= 'PTYP' and 
			ins.vPCoCd<> @wSelfCoCd 
		if @row> 0 
		begin
			select @errmsg= 'For PTyp= ''PTYP'', the Company Code should Be '+@wSelfCoCd
			goto ErrHndlr
		end

		/*** vPMCd cannot be Blank ***/
		select @row=count('x') from inserted where vPMCd= ''
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end
		/*** vPDesc cannot be blank ***/
		/* ******* Geeta CRM 2.12 ******** */
		select @row=count('x') from inserted where vPDesc= '' and vPTyp<>'CRMWIW'
		if @row>0 
		begin
			select @errmsg='Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @vPTyp= 'CHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row> 0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd= Not Blank ******/
			select @row= count('x') from inserted where vPSCd= ''
			if @row>0 
			begin
				select @errmsg= 'Character Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****************Geeta**Crm*2.12************************************/
			select @row= count('x') from inserted ins where vPSCd='WEB' and 
				(Not Exists(Select 'x' From SysDb where SysId='CRM') Or 
				Not Exists (Select 'x' From Param 
					where PTyp='TC' and PMCd=vPMCd  and PValue in ('SO','QT','QS','MF')))
			if @row>0 
			begin
				select @errmsg= 'WEB Chr can be Used Only for ''SO'',''QS'',''QT'',''MF'' in CRM Database  '
				goto ErrHndlr
			end
			/****Geeta*****Crm**************/  
			select @row= count('x') from inserted ins where vPCoCd='WEB' and  vPSCd<>'WEB'	
			if @row>0   
			begin  
				select @errmsg= 'Character Other than ''WEB'' cannot be defined for CoCd=''WEB''  '  
				goto ErrHndlr  
			end  
			/****** vPValue= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPValue<>'' and 
				not exists (select 'x' from Loc where LocCoCd = vPCoCd 
					and LocTyp<> 'P' and LocCd= vPValue)
			if @row>0 
			begin
				select @errmsg= 'Default From Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum= 0 ******/
			select @row= count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPDesc225<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp<> 'P' and LocCd= vPDesc225)
			if @row>0 
			begin
				select @errmsg= 'Default To Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPValue1= Valid Bag Loc ****** Bhavna removed check for tc FB as multiple locns in FB*/
			select @row= count('x') from inserted where vPValue1<> '' and vPMCd <> 'FB' and  
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp= 'P' and LocCd= vPValue1)
			if @row>0 
			begin
				select @errmsg= 'Default Bag Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum1= 0 ******/
			select @row= count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2= 'D' or 'C' (Raw Material Debit Or Credit) ******/
			select @row= count('x') from inserted ins where ins.vPValue2<> '' and 
					not exists (select 'x' from Param Prm where Prm.PTyp= 'DC' 
        						and Prm.PMCd= ins.vPValue2)
			if @row>0 
			begin
				select @errmsg= 'Default Raw Material Debit / Credit Not Defined'
				goto ErrHndlr
			end

			/****** vPValue3 = Y/N ******/
			select @row=count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'YN' 
					    and Prm.PMCd= ins.vPValue3)

			if @row>0 
			begin
				select @errmsg= 'TrialChr Should Be Y/N'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> 'Y' and vPValidYn <> 'N' and vPValidYn <> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Y/N'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
		End


		if @vPTyp= 'DEFCHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row>0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd = Blank ******/
			select @row=count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end

			/****** vPValue= Valid vPSCd ('CHR') ******/
