				exists (select 'x' from Fg where FgCoCd= vPCoCd and FgTc= vPMCd and FgChr= vPSCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Fg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Chr in use in Fgd table ******
			select @row= count('x') from deleted del where 
				exists (select 'x' from Fgd where FdCoCd = vPCoCd and (FdPrdOdTc= vPMCd and FdPrdOdChr= vPSCd) 
					or (FdExpOdTc= vPMCd and FdExpOdChr= vPSCd) or (FdInTc= vPMCd and FdInChr= vPSCd))
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Fgd Table'
				goto ErrHndlr
			end
			*/

			/****** Cannot delete Chr in use in OrdMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdMst where OmCoCd= vPCoCd and OmTc= vPMCd and OmChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In OrdMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Txn table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txn where TCoCd= vPCoCd and TTc= vPMCd and TChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Txn Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in TxndZ table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from TxndZ where TzCoCd= vPCoCd and TzTc= vPMCd and TzChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In TxndZ Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in InvHd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from InvHd where InCoCd= vPCoCd and InTc= vPMCd and InChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Invoice Head Table'
				goto ErrHndlr
			end

			/****** Cannot delete Chr in use in MultiPrcQtMst table ******/
			/* ***** Manali 3.10.0 - Multi Price Qt Module *****/
			select @row=count('x') from deleted del where 
				exists (select 'x' from MultiPrcQtMst where MqmCoCd= vPCoCd and MqmTc= vPMCd and MqmChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Multi Price Quotation Table'
				goto ErrHndlr
			end
		End


/******************************************************************************************/
		if @vPTyp= 'FGSUBLOC' 
		Begin 
			/****** Cannot delete FgSubLoc in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgSubLoc In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgSubLoc In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Fg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from FG where FgCoCd= vPCoCd and FgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In FG Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Fgd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Fgd where FdCoCd= vPCoCd and FdSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In Fgd Table'
				goto ErrHndlr
			end

			/****** Cannot delete FgSubLoc in use in Fmd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Fmd where FmdCoCd= vPCoCd and FmdFrFgSubLoc= vPMCd
					or FmdToFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In Fmd Table'
				goto ErrHndlr
			end
	
		End
/*****************************************************************************************/

		if @vPTyp= 'LINE' 
		Begin 
			/****** Cannot Delete 'ZZZ' Line For The Company If Other Line Rec Exists For The Company ******/ 
			select @row= count('x') from deleted del where vPMCd= @wSelfCoCd and 
				exists (Select 'x' from vParam vPrm 
					    where vPrm.vPCoCd= del.vPCoCd 
						  and vPrm.vPTyp= del.vPTyp 
						  and vPrm.vPMCd<> @wSelfCoCd) 
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete ''ZZZ'' Line For The Company If Other Line Rec Exists For The Company' 
				goto ErrHndlr
			end

			/****** Cannot delete Line in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdMst where OmCoCd= vPCoCd and OmLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdDsg Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdPln table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdPln where OpCoCd= vPCoCd and OpLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdPln Table'
				goto ErrHndlr
			end
		End

		if @vPTyp= 'PRDSEQ' 
		Begin 
			/****** Cannot delete Production Sequence in use in DsgMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from DsgMst where DmPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In DsgMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd and hDmPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In OrdDsg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Production Sequence in use in Param table where PTyp= 'PRDCTG' ******
			select @row=count('x') from deleted del where 
				exists (select 'x' from Param Pm where Pm.PTyp= 'PRDCTG' and Pm.PValue= del.vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Param Table Where PTyp= 'PRDCTG''
				goto ErrHndlr
			end
			*/
		End

		if @vPTyp= 'WORK' 
		Begin 
			/****** Cannot delete Worker in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BWrk= vPMCd)
			if @row>0 
			Begin
			select @errmsg='Cannot Delete As Worker In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in Txnd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txnd where TdCoCd= vPCoCd and (TdWrk= vPMCd or TdByWrk= vPMCd))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In Txnd Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in TxndPrd table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndPrd where TpCoCd= vPCoCd and TpByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndPrd Table'
				goto ErrHndlr
			End
			/****** Bhavna Cannot delete Worker in use in TxndRwrk table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndRwrk where TrwCoCd= vPCoCd and TrwByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndRwrk Table'
				goto ErrHndlr
			End

		End

		if @vPTyp In ('WIWSEQ' ,'WIWLONG')
		Begin 
			/* ****** WIWSEQ/WIWLONG Cannot be deleted From ZZZ if it exists in other companies ****** */
			Select @Row=Count('x') From Deleted Del Where Del.vPCoCd=@wSelfCoCd And Del.vPTyp In ('WIWSEQ','WIWLONG') And Del.vPValue3='N' 
				And Exists (Select 'x' From vParam vWIW Where vWIW.vPCoCd<>@wSelfCoCd And Del.vPTyp=vWIW.vPTyp And Del.vPMCd=vWIW.vPMCd 
							And Del.vPValue3=vWIW.vPValue3)  			
			If @Row > 0
			Begin
				select @errmsg= 'Cannot Delete As '+ @vPTyp + ' Sequence Exists in One of the Companies'
				goto ErrHndlr
			End
		End	
		/* *** JAY 3.2.0 [AutoTree] */ 
		if @vPTyp= 'TRDEF' 
		Begin 
			select @row=count('x') from deleted del 
			if @row>0 
			Begin
			select @errmsg='Cannot Delete Record'
				goto ErrHndlr
			end
		end
		/* *** JAY 3.2.0 [AutoTree] */ 
	End

	Return

ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end

GOGO

ALTER TRIGGER [dbo].[Param_INUPDL] ON [dbo].[Param] 
       FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/****** Trigger Version - 3.11.1 ******/
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @PTyp varchar(8)
	DECLARE @wHCd VARCHAR(8)
	DECLARE @SYS VARCHAR(5)
 	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT= 0
		RETURN
	If Exists (Select 'x' From TrgDisa Where TdTblNm = 'Param')
		RETURN

	Set @wHCd = 'ZSELF'	
	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	/****** Determining whether the trigger has been called in an insert, update or delete mode ******/
	/****** If there no records in inserted the the mode is 'Delete' 			    ******/
	/****** If there no records in deleted the the mode is 'Insert' 		            ******/
	/****** If there records in both inserted and deleted the the mode is 'Update' 		    ******/
	Select @mode=case (select count('x') from inserted) when 0 then 'D'
		Else Case (select count('x') from deleted) when 0 then 'A' else 'C' end
       	End 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/*** Storing PTyp In The Variable @PTyp ***/
	select @PTyp= case  when @mode in ('C', 'A') then (Select max(PTyp) from inserted)  else (Select max(PTyp) from deleted) end  

	If  (@ReplAgt<>1)
	Begin
	 
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   Exists ( Select 'x' From SysDb where SysId='EMR' and SdMst='N' )  Or  
		     Exists ( Select 'x' From SysDb where SysId='CRM' and SysDb='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
		
		if @mode in ('A','C')
		Begin
			If @PTyp= 'SUBPRC' 
			Begin 
				/****** PMCd = valid Process Loc ******/
				/*uma **** P replaced by R ***/
				select @row= count('x') from inserted where not exists (select 'x' from Loc where LocTyp= 'R' and LocCd= PMCd)
				if @row>0 
				begin
					select @errmsg= 'Process Not Defined'
					goto ErrHndlr
				end
			End
			
			/*********Bhavna PMCD = Valid proc loc for rework ******/
			/**** uma P to R******/
			If @PTyp= 'RWRK' 
			Begin 
				/****** PMCd = valid Process Loc ******/
				select @row= count('x') from inserted where not exists (select 'x' from Loc where LocTyp= 'R' and LocCd= PMCd)
				if @row>0 
				begin
					select @errmsg= 'Process Not Defined'
					goto ErrHndlr
				end
			End
			/*********Bhavna PMCD = Valid proc loc for rework ******/
		End
	End  

	Set DateFormat DMY 

	/***Geeta****From CRM 2.12 Onwards 
	NOTE::	***PTYP  Should be Unique in Param,vParam & cParam*****************/ 

 	/******** Records Of Only One PTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(PTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One PTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(PTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	/* (Bef 3.01)
	select @Row=Count('x') from Param Pm where (@PTyp= 'PTYP') or 
		(Pm.PTyp= 'PTYP' and Pm.PMCd= @PTyp and Pm.PValue= 'M')
	(Bef 3.01) */

	/*** (Jen 3.01) ***/

	select @Row= Count('x') from Param Pm where (@PTyp= 'PTYP') or 
		(Pm.PTyp= 'PTYP' and Pm.PMCd= @PTyp and Pm.PValue= 'M' and @PTyp<> 'VER')
	/*** (Jen 3.01) ***/
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add/Change/Delete Microway Parameter - '+ @PTyp
		GoTo ErrHndlr
	end		

	/*** (Jen 3.01) ***/
	select @Row= Count('x') from Param Pm where @mode in ('A','D') and 
		Pm.PTyp= 'PTYP' and Pm.PMCd= @PTyp and Pm.PValue= 'M' and @PTyp= 'VER' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add/Delete Microway Parameter - '+ @PTyp
		GoTo ErrHndlr
	end		
	/*** (Jen 3.01) ***/
	
	select @Row= Count('x') from Inserted where @mode ='A' and PTyp= 'LOCKDT' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add  LOCKDT Parameter '
		GoTo ErrHndlr
	end	

	select @Row= Count('x') from Deleted where @mode ='D' and PTyp= 'LOCKDT' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Delete  LOCKDT Parameter '
		GoTo ErrHndlr
	end		

	select @Row= Count('x') from Inserted where @mode ='A' and PTyp= 'DMMATX' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add Records to Design Matrix Parameter '
		GoTo ErrHndlr
	end	
			
		
 	/******** Key Cannot Be Changed  (i.e. PTyp, PMCd and PSCd cannot be changed) ********/ 
 	if @mode = 'C'
 	Begin
  		select @Row= Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.PTyp= del.PTyp and ins.PMCd= del.PmCd and ins.PSCd= del.PSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Param Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	BEGIN
		/*** Only a valid PTyp can be entered (i.e. a valid PMCd from Param where PTyp= 'PTYP') ***/
		select @row=count('x') from inserted ins where ins.PTyp<> 'PTYP' and 
		not exists (select 'x' from Param Prm where Prm.PTyp='PTYP' and Prm.PMCd= ins.PTyp)
		if @row>0 
		begin
			select @errmsg='Parameter Type Not Defined'
			goto ErrHndlr
		end
		/*** PMCd cannot be Blank ***/
		select @row= count('x') from inserted where PMCd= ''
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end

		/***  PDesc cannot be blank ***/
		/* *** Jay 3.2.0 [Stmp Instr] */
		/**** Manali 3.8.1 - SETCD started ****/
		select @row= count('x') from inserted where PDesc= '' and @PTyp not in ('INVDESC', 'STMPINST', 'SETCD','DMMATX')
		if @row>0 
		begin
			select @errmsg= 'Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @PTyp= 'CPYRT' 
		Begin 
			/****** PSCd= Blank ******/
			select @row=count('x') from inserted where PSCd<> ''
			if @row> 0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue= Blank ******/
			select @row=count('x') from inserted where PValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PValue Should Be Blank'
				goto ErrHndlr
			end
			/****** PNum= 0 ******/
			select @row=count('x') from inserted where PNum<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end

/*** ###
			select @row=count('x') from inserted where PDesc225<> '' and 
			if @row>0 
			begin
				select @errmsg= 'Raw Material Category In Sequence Not Defined'
				goto ErrHndlr
			end
***/
			select @row= count('x') from inserted where PDesc225= '' 
			if @row> 0 
			begin
				select @errmsg= 'Raw Material Category Sequence Should Be Entered'
				goto ErrHndlr
			end

			/****** PValue1= Blank ******/		
			select @row= count('x') from inserted where PValue1<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** PNum1= 0 ******/
			select @row= count('x') from inserted where PNum1<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** PValue2= Blank ******/
			select @row= count('x') from inserted where PValue2<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue3 = Blank ******/
			select @row= count('x') from inserted where PValue3<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue3 Should Be Blank'
				goto ErrHndlr
			end

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where PValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'PValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */

			/* Bef 3.03 - Following check no more reqd for PmCd= 'GPSDCXAM' */
			/****** Cannot add or change the Record of PmCd= 'GPSDCXAM' ******/
			/*
			select @row= count('x') from inserted where PMCd= 'GPSDCXAM'
			if @row> 0 
			begin
				select @errmsg= 'Cannot Add Or Change The Record ''GPSDCXAM'' '
				goto ErrHndlr
			end
			*/

			/* Manali 3.03 - 12/07/08 */
			/****** Cannot add or change the Record of PmCd= 'GPSLDCXM' ******/
			select @row= count('x') from inserted where PMCd= 'GPSLDCXM'
			if @row> 0 
			begin
				select @errmsg= 'Cannot Add Or Change The Record ''GPSLDCXM'' '
				goto ErrHndlr
			end
			/* Manali 3.03 - 12/07/08 */
		End

		if @PTyp= 'CURNCY' 
		Begin 
			/****** PMCd= Not Blank ******/
			select @row= count('x') from inserted where PMCd= ''
			if @row> 0 
			begin
				select @errmsg= 'Main Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****** PSCd= Blank ******/
			select @row= count('x') from inserted where PSCd<> ''
			if @row> 0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/* Zubin 213 (Bef 213) */ 
			/****** PValue= Blank ******/
/*			select @row= count('x') from inserted where PValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PValue Should Be Blank'
				goto ErrHndlr
			end
*/ 
			/* Zubin 213 */ 
			select @row= count('x') from inserted where PValue= '' 
			if @row> 0 
			begin
				select @errmsg= 'Currency Unit Description Cannot Be Blank'
				goto ErrHndlr
			end

			/****** Round(PNum, 3)> 0 ******/
			select @row= count('x') from inserted where Round(PNum, 3)<= 0
			if @row> 0 
			begin
				select @errmsg= 'Currency Conversion Rate Should Be > Zero'
				goto ErrHndlr
			end
/* COMMENTED TEMPORARILY (WILL BE INCORPORATED LATER) */ 
			/* Zubin 213 */ 
/*			select @row= count('x') from inserted where PNum<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end
*/
			/****** PDesc225= Blank ******/
			select @row= count('x') from inserted where PDesc225<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/* Zubin 213 (Bef 213) */ 
			/****** PValue1= Blank ******/		
/*			select @row=count('x') from inserted where PValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
