           ,[ModDt]
           ,[ModTime]
           ,[LocCoCd]
           ,[LocPrdStg]
           ,[LocValidYN]
           ,[LocLsTyp]
           ,[LocPrntYN]
           ,[LocPrntCd]
           ,[LocPrtKey]
           ,[LocAllowLsPer]
           ,[LocHideYN])
     select  
