Create Table #LocPrcs(
		LpID int,
		LpLoccd varchar(8),
		LpCoCd varchar(3),
		LpPrdTyp varchar(2),
		LpPrcStg varchar(5),
		LpLsTyp varchar(2),
		LpPer int, 
		LpPrntYN varchar(1),
		LpPrntCd varchar(8),
		LpRPrntCd varchar(8),
		LpPrcs varchar(8)) 


Insert into #LocPrcs(LpID ,LpLoccd ,LpCoCd ,LpPrdTyp ,LpPrcStg ,LpLsTyp ,LpPer ,LpPrntYN ,LpPrntCd ,LpRPrntCd ,LpPrcs )
	Select ROW_NUMBER() OVER ( ORDER BY LocCd ) AS 'Row', LocCd, LocCoCd,
	ISNULL((case when (LocPrdTyp='' or LocPrdTyp is null) and LocPrntYN<>'Y' then 'GN' else LocPrdTyp end),''),
	ISNULL(LocPrdStg,''),ISNULL(LocLsTyp,''),ISNULL(LocAllowLsPer,0),LocPrntYN,ISNULL(LocPrntCd,''),'','' from Loc 
	where LocTyp ='P' 




Update #LocPrcs set LpPrcs= 'R'+LpLocCd 






Update #LocPrcs set LpRPrntCd= 'R'+LpPrntCd






Insert Into Loc (LocCd,LocDesc,LocTyp,LocPrdTyp,LocLoss,LocBrk,LocMsg,ModUsr,ModDt,ModTime,LocCoCd,LocPrdStg,LocValidYN,
	LocLsTyp,LocPrntYN,LocPrntCd,LocPrtKey,LocAllowLsPer,LocHideYN,LocPrcs,LocUseCapOf)
	Select LpPrcs, '', 'R', LpPrdTyp, '', '', '', 'MIC', '1980-01-01 00:00:00', 0.00, LpCoCd, LpPrcStg, 'Y',
	LpLsTyp, LpPrntYN,	LpRPrntCd, 'C', LpPer, 'N', '', '' from #LocPrcs 
	where LpPrcs<>'' and not exists (Select 'a' from Loc where LocCd =LpPrcs and LocCoCd =LpCoCd)


/******** Change fields for Loc **********/

Update Loc set LocPrdTyp='', LocPrdStg='', LocLsTyp='', LocAllowLsPer=0, LocPrcs=LpPrcs, LocUseCapOf=LpLoccd
	from Loc join #LocPrcs on LocTyp ='P' and LocCd =LpLoccd and LocCoCd =LpCoCd and LpPrcs <>'' 
	where LocPrntYN='N'

/******** Update Param table (Loc to Process) **********/

Update Param set PMCd =LpPrcs from Param join #LocPrcs on LpLoccd =PMCd and PTyp ='SUBPRC'  
Update Param set PMCd =LpPrcs from Param join #LocPrcs on LpLoccd =PMCd and PTyp ='RWRK'  


/******** Update PrdPts & Process Loss Master table **********/

Update PrdPts set PpLoc =LpPrcs from PrdPts join #LocPrcs on LpLoccd =PpLoc 

/******** Update LossMst (Loc to Process) **********/

Update LossMst set LmLocCd =LpPrcs from LossMst join #LocPrcs on LpLoccd =LmLocCd and LmCoCd =LpCoCd 

Update DsgPrd set  [DppLoc] = LpPrcs from DsgPrd join #LocPrcs on LpLoccd = DppLoc 

GOGO

/******** Create PRCSSEQ **********/
Declare @PrdLine varchar(8)
Select @PrdLine= PMCd from Param where PTyp ='PRDLINE' and PMCd ='JW' and PSCd=''

IF @PrdLine is null
begin
	Insert Into Param (PTyp,PMCd,PSCd,PDesc,PDesc225,PValue,PNum,PValue1,PNum1,PValue2,ModUsr,ModDt,ModTime,PValue3,PValidYn,PPrtKey) 
	values('PRDLINE','JW','','Jewellery Line','','',0,'',0,'','MIC','1980-01-01 00:00:00',0.00,'','Y','C')	
	
	Select @PrdLine= PMCd from Param where PTyp ='PRDLINE' and PMCd ='JW' and PSCd=''
end


