	ModTime,vPValidYn,vPValue4,vPPrtKey)
	SELECT  HCoCd,'PRCSSEQ','JW','','Process Sequence','RFG','',0,@PrdLine,0,'','','MIC','1980-01-01 00:00:00',
	0.00,'Y','','C' from Head 
    where not exists (Select 'a' from vParam where vPCoCd =HCoCd and vPTyp ='PRCSSEQ' and vPMCd ='JW' and vPSCd ='')

Update Head set hDmPrcsSeq='JW' where hDmPrcsSeq='' 


Update Head set hClstrCd = '0' 

Update DsgMst set DmPrcsSeq ='JW' where DmPrcsSeq='' 

GOGO

